      "path": "packages/dsh-plugin-shop/package.json",
      "content": "{\n  \"name\": \"dsh-plugin-shop\",\n  \"version\": \"0.9.4\",\n  \"description\": \"Browse, install, enable, and update plugins for DeepSeek Harness.\",\n  \"icon\": \"./assets/icon.png\",\n  \"keywords\": [\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"dsh\",\n    \"deepseek\",\n    \"plugin-manager\",\n    \"plugin-marketplace\",\n    \"plugin-catalog\",\n    \"harness\"\n  ],\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/LivXue/dsh-plugin-shop.git\"\n  },\n  \"homepage\": \"https://github.com/LivXue/dsh-plugin-shop#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/LivXue/dsh-plugin-shop/issues\"\n  },\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/types/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/types/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": {\n      \"types\": \"./lib/types/client/index.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./remote\": {\n      \"types\": \"./lib/typert.remote-client.d.ts\",\n      \"default\": \"./lib/typert.remote-client.js\"\n    },\n    \"./typert\": {\n      \"types\": \"./lib/typert.host.d.ts\",\n      \"default\": \"./lib/typert.host.js\"\n    },\n    \"./types\": {\n      \"types\": \"./lib/types/host/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"LICENSE\",\n    \"assets/icon.png\",\n    \"lib/index.js\",\n    \"lib/client.js\",\n    \"lib/types/**/*.js\",\n    \"lib/types/**/*.d.ts\",\n    \"lib/typert.host.js\",\n    \"lib/typert.host.d.ts\",\n    \"lib/typert.remote-client.js\",\n    \"lib/typert.remote-client.d.ts\",\n    \"cordis.patch.yml\"\n  ],\n  \"license\": \"Apache-2.0\",\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [],\n      \"platform\": \"web\"\n    }\n  },\n  \"scripts\": {\n    \"prepublishOnly\": \"pnpm build\",\n    \"build\": \"node -e \\\"require('node:fs').rmSync('lib',{recursive:true,force:true})\\\" && tsdown && tsc && tsdown -c tsdown.client.config.ts\",\n    \"test\": \"tsdown && tsdown -c tsdown.client.config.ts && vitest run\",\n    \"typecheck\": \"tsdown && tsc --noEmit && tsc -p tsconfig.test.json\",\n    \"shoot:screenshots\": \"node --experimental-strip-types scripts/shoot-readme-screenshots.ts\"\n  },\n  \"dependencies\": {\n    \"js-yaml\": \"^4.2.0\",\n    \"semver\": \"^7.6.3\",\n    \"yaml\": \"^2.5.1\",\n    \"zod\": \"^4.4.3\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/cordis-plugin-include\": \"^1.0.6\",\n    \"@deepseek-ai/dsh-app-boot\": \">=0.1.1-rc.2 <0.3.0-0\",\n    \"@deepseek-ai/dsh-home-paths\": \">=0.1.1-rc.2 <0.3.0-0\",\n    \"@deepseek-ai/dsh-typert-protocol\": \">=0.1.1-rc.2 <0.3.0-0\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/cordis\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/cordis-plugin-include\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-app-boot\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-home-paths\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-typert-protocol\": {\n      \"optional\": true\n    }\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/dsh-api-remotes\": \"^0.1.1-rc.2\",\n    \"@deepseek-ai/dsh-app-boot\": \"^0.1.1-rc.2\",\n    \"@deepseek-ai/dsh-client-locale\": \"^0.1.1-rc.2\",\n    \"@deepseek-ai/dsh-client-runtime\": \"^0.1.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"^0.1.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"^0.1.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"^0.1.1-rc.2\",\n    \"@deepseek-ai/dsh-home-paths\": \"^0.1.1-rc.2\",\n    \"@deepseek-ai/dsh-typert-generator\": \"^0.1.1-rc.2\",\n    \"@deepseek-ai/dsh-typert-protocol\": \"workspace:^0.1.1-rc.2\",\n    \"@testing-library/react\": \"^16.1.0\",\n    \"@types/js-yaml\": \"^4.0.9\",\n    \"@types/node\": \"^22.9.0\",\n    \"@types/react\": \"^18.3.31\",\n    \"@types/react-dom\": \"^18.3.7\",\n    \"@types/semver\": \"^7.5.8\",\n    \"jsdom\": \"^25.0.1\",\n    \"playwright\": \"^1.49.0\",\n    \"react\": \"18.3.1\",\n    \"react-dom\": \"18.3.1\",\n    \"tsdown\": \"^0.22.2\",\n    \"typescript\": \"^5.6.3\",\n    \"vitest\": \"^2.1.4\"\n  }\n}\n"
