    {
      "path": "packages/dsh-plugin-shop/src/client/index.ts",
      "content": "/**\n * Shop surface, browser half — the shop's own page in dsh's main column\n * (`main`), which browses the catalog, installs on one click, toggles\n * enablement, lists installed plugins, and restarts dsh after installs; its\n * row in the left sidebar (`sidebar.panellist`); and the two buttons on dsh's\n * Plugins page that lead into it (`plugins.detail.actions`) (design\n * 2026-10-16-shop-sidebar-page).\n * Mounts the shop Remote itself (the assembly does not know this package)\n * and holds no privilege beyond the nine `shop/*` methods (the shop design's\n * §5.3).\n */\n\nimport type {} from '@deepseek-ai/dsh-api-remotes/client'\nimport type {} from '@deepseek-ai/dsh-client-locale/client'\nimport type { ClientContext } from '@deepseek-ai/dsh-client-runtime/client'\nimport type { TypertRemoteNamespaceMap } from '@deepseek-ai/dsh-typert-protocol'\nimport shopRemote from 'dsh-plugin-shop/remote'\nimport type { ShopCatalogResult, ShopRestartResult, ShopVersionResult } from '../host/index.ts'\nimport type { ShopLocaleKey } from './locales.ts'\nimport { en, zh } from './locales.ts'\nimport { refineAgainstModuleTable } from './module-table.ts'\nimport { createPageStore, disposeOccupant, installPageStore, readPredecessor } from './page-store.ts'\nimport { answeredByAnotherProcess, updateAwaitsRestart } from './present.ts'\nimport { noteBoot, registerRestartCarrier } from './restart-monitor.ts'\nimport { ShopDetailAction, type PluginsSubject, type ShopDetailActionInjected } from './ShopDetailAction.tsx'\nimport { ShopGlyph } from './ShopGlyph.tsx'\nimport { ShopPage } from './ShopPage.tsx'\nimport type { ShopTabInjected } from './ShopTab.tsx'\n\ndeclare module '@deepseek-ai/dsh-client-ui-slots' {\n  interface LocaleNamespaceMap {\n    /** The shop page's copy. */\n    'settings.shop': ShopLocaleKey\n  }\n  interface SlotMap {\n    /** dsh's left column of global panels (`dsh-client-ui-sidebar`, on\n     * 0.1.5-rc.3, 0.1.7-rc.2 and 0.2.0-rc.2): one row per entry, which owns\n     * the button, its label and its selection, and renders the entry's glyph\n     * at the size it asks. Declared here, in dsh's own terms, because the\n     * 0.1.1-rc.2 protocol this package builds against predates it — as\n     * `connection/reset` is below. */\n    'sidebar.panellist': { kind: 'list'; scope: 'root'; owner: { size: number; active: boolean } }\n    /** The main column, keyed by panel id (`dsh-client-ui-layout`, the same\n     * harnesses): only the selected key is mounted, and the sidebar row with\n     * the same id selects it. Declared here for the same reason. */\n    'main': { kind: 'keyed'; scope: 'root' }\n    /** Controls at the head of a detail page on dsh's Plugins page\n     * (`dsh-client-ui-plugin-manager`, 0.1.7-rc.2 and later), rendered with\n     * the page's subject; an entry renders null for a subject it has nothing\n     * for. On a harness without the Plugins page nothing declares it, and a\n     * registration into it waits without ever rendering. */\n    'plugins.detail.actions': { kind: 'list'; scope: 'root'; owner: { subject: PluginsSubject } }\n  }\n}\n\ndeclare module '@deepseek-ai/cordis' {\n  interface Events {\n    /** A connection generation was established: the first connect after\n     * plugin boot, and every reconnect. `@deepseek-ai/dsh-client-connection`\n     * declares it, in these words, from 0.1.5-rc.3 on, and dsh-api-gateway's\n     * client emits it there through 0.2.0-rc.2; the 0.1.1-rc.2 this package\n     * builds against predates the declaration. A harness that never emits\n     * it leaves the shop as it was before it listened. */\n    'connection/reset'(): void\n  }\n}\n\n/** Dictionary namespace owned by this plugin. */\nexport const NS = 'settings.shop'\n\n/** The id the shop's sidebar row and its main-column page share (design\n * 2026-10-16-shop-sidebar-page §4.1). */\nexport const SHOP_PANEL = 'shop'\n\n/** The npm package this client belongs to: the bundle dsh's own Plugins page\n * opens for the desktop self-update. */\nconst SHOP_PACKAGE = 'dsh-plugin-shop'\n\n/** dsh's own Plugins page (dsh-client-ui-plugin-manager's `PANEL_ID`), the\n * surface that updates a package on the desktop profile. The fallback for a\n * harness without `pluginNavigation`. */\nconst DSH_PLUGINS_PANEL = 'plugins'\n\n/** How long a stashed catalog may satisfy a plain open. The host applies the\n * same five-minute freshness window, so the client stash must not outlive it. */\nexport const WARM_TTL_MS = 5 * 60 * 1000\n\n/** The boot-time warm fetch: the catalog the tab wants on its first open.\n * Started in apply — the client bundle boots with the web app, long before\n * the user opens the shop — so the host's slow network fetch runs while\n * nobody is looking at the shop, and the tab's mount consumes this promise\n * instead of starting its own fetch. A rejection stays stored (the injected\n * catalog falls back to a fresh call); the extra catch keeps the\n * fire-and-forget from surfacing as an unhandled rejection. Every later\n * result, including an explicit refresh, replaces this timestamped stash. */\nlet warmCatalog: { at: number; result: Promise<ShopCatalogResult> } | null = null\n\n/** Package names THIS PAGE has uninstalled since it loaded (design\n * 2026-09-01-harness-compatibility section 9.1): the module table can still\n * hold a graph row or a `loadCache` record for one after a restart-free\n * uninstall (module-table.ts's header explains why), so\n * the refinement must never clear a name here on the table's say-so — the\n * host's verdict stands unconditionally. Module-level so it survives the tab\n * closing and reopening; reset in `apply` beside `warmCatalog`, because a\n * re-applied bundle is a new page that has uninstalled nothing yet. An\n * uninstall made from another tab, another window, or the CLI is never added\n * here and stays unknown to this page until it reloads. */\nlet pageRemoved = new Set<string>()\n\n/** Services required by the page, row and Plugins page button registrations\n * and the Remote mount.\n *\n * `remote.shop` is deliberately ABSENT: this package both mounts its own\n * Remote (the assembly does not know it, §7.3) and consumes it, and cordis\n * will not let one package do both through the inject face. Declaring the\n * face makes the boot's activation gate wait for the `remote.shop` service —\n * which only this package's own apply can register — and the real web boot\n * deadlocked on exactly that (\"waiting for service: remote.shop\"). The\n * namespace is therefore read through the reflect shop instead (`ctx.get`,\n * see apply), which has no inject requirement. */\nexport const inject = ['remote', 'slots', 'locale']\n\n/** The shop's own mounted Remote namespace: the generated client surface\n * `ctx.remote.shop` would expose, read here without the inject gate. */\ntype ShopRemoteNamespace = TypertRemoteNamespaceMap['shop']\n\n/** What the shop CALLS on dsh's layout service (`dsh-client-ui-layout`).\n * Only `selectPanel` — one call, identical on 0.1.5-rc.3, 0.1.7-rc.2 and\n * 0.2.0-rc.2. The shop does NOT read the selection observable from this\n * service: measured 2026-10-16 (design 2026-10-16-shop-sidebar-page §3.1),\n * 0.1.5-rc.3's ILayout is a command facade and the observable lives on a\n * root slot hook reachable only through a private field of `ctx.slots`,\n * while 0.1.7-rc.2 and 0.2.0-rc.2 carry it on ILayout. Reading\n * `ctx.layout.panelInfo` unguarded throws on 0.1.5-rc.3 — that crash is\n * what the probe hit before it was made shape-tolerant. Instead the shop\n * records whether its OWN page is mounted, which is a fact it owns. The\n * 2026-10-16 probe measured the teardown record running before the `main`\n * entry leaves, while dsh's selection still stands, on all three legs; that\n * the page is still mounted then is the design's argued half (design\n * 2026-10-16-shop-sidebar-page §6). The e2e's hot-swap case witnesses it on\n * 0.1.7-rc.2 and 0.2.0-rc.2: the page comes back there only through rule 1,\n * which reads that record, and the case fails with rule 1 removed (measured\n * 2026-10-17). */\ninterface ShopLayoutFace {\n  selectPanel(panelId: string | null): void\n}\n\n/** What the shop CALLS on dsh's plugin manager's navigation service\n * (`pluginNavigation`, provided by dsh-client-ui-plugin-manager through the\n * reflect shop): `openBundle` selects the Plugins panel, switches to its\n * Installed tab and opens one package's detail page — the page whose Update\n * button runs `updateBundle`. Shape-checked like `ShopLayoutFace`, because a\n * harness may provide neither. */\ninterface ShopPluginNavigationFace {\n  openBundle(packageName: string): void\n}\n\n/** Mount the shop Remote and contribute the shop's page, its sidebar row and\n * its buttons on dsh's Plugins page. */\nexport async function apply(ctx: ClientContext): Promise<void> {\n  // What this instance replaces (design 2026-10-16-shop-sidebar-page §6),\n  // read before anything below puts a store of its own on the page.\n  const predecessor = readPredecessor()\n  ctx.effect(() => ctx.locale.register(NS, { zh, en }), 'dsh-plugin-shop: dictionaries')\n\n  // `ctx.on('dispose')` never fires in cordis 4.0.1; an effect whose body\n  // returns the mount disposer is what actually runs it on teardown. The\n  // restart path registered below is withdrawn in that same teardown, and\n  // FIRST: disposing the mount aborts a restart call still in flight on it\n  // (dsh binds every call to its mount), and that abort has to find a\n  // request the page already knows to ask again, not one it would report as\n  // undeliverable (restart-monitor.ts).\n  const dispose = await ctx.remote.$mount(shopRemote)\n  let withdrawRestart = (): void => {}\n  ctx.effect(() => () => {\n    withdrawRestart()\n    return dispose()\n  }, 'dsh-plugin-shop: shop remote mount')\n\n  // The mount registered the `remote.shop` service on the gateway's fiber;\n  // `ctx.remote.shop` would still refuse it here (\"cannot get property\n  // remote.shop without inject\"), because cordis hands a mounted namespace\n  // out through the facade only to a fiber whose inject face names it. The\n  // reflect shop has no such gate: `ctx.get` reads a registered service from\n  // any fiber, and the mount above has settled, so the strict availability\n  // check passes.\n  const ns = ctx.get('remote.shop') as ShopRemoteNamespace | undefined\n  if (ns === undefined) {\n    throw new Error('dsh-plugin-shop: the shop remote did not register (service \"remote.shop\" missing after $mount)')\n  }\n\n  // The wire envelope is unwrapped here, once: the tab sees either the value\n  // or a thrown error, never the transport shape (§5.3).\n  const unwrap = <T,>(result: { ok: true; value: T } | { ok: false; error: { code: string; message: string } }): T => {\n    if (!result.ok) throw new Error(`shop remote: ${result.error.code}: ${result.error.message}`)\n    return result.value\n  }\n\n  // The boot-time warm: the catalog fetch starts now, in the background;\n  // the tab's first open consumes it instead of waiting on it. The smaller\n  // reads warm the host's snapshot too (their results are discarded — the\n  // tab re-requests them on mount and the host serves them from memory).\n  // Each boot starts its own warm fetch — a re-applied bundle must not\n  // serve the previous boot's catalog.\n  warmCatalog = null\n  pageRemoved = new Set()\n  // Promise.resolve wraps the wire result so a stub or an ill-behaved\n  // transport can never throw synchronously out of apply.\n  const warmed = Promise.resolve(ns.catalog(undefined)).then(result => unwrap(result))\n  warmCatalog = { at: Date.now(), result: warmed }\n  void warmed.catch(() => {})\n  void Promise.resolve(ns.installed()).then(result => unwrap(result)).catch(() => {})\n\n  // Which process answers the page (design §8, 2026-10-06 amendment). Every\n  // version answer passes through here — the boot warm-up just below, the\n  // tab's own checks, and the re-ask on every reconnect — so whichever is\n  // first to come from a new process is the one that says so, and the first\n  // a reloaded page gets judges the restart it reloaded after (`noteBoot`),\n  // before any tab is open. A process that differs from the last answer's is\n  // dsh restarted under the page: the warm catalog holds the old process's\n  // verdicts, and the tab holds receipts the restart has settled.\n  let lastVersion: ShopVersionResult | null = null\n  const restartListeners = new Set<(fresh: ShopVersionResult) => void>()\n  const version = async (): Promise<ShopVersionResult> => {\n    const result = unwrap(await ns.version())\n    noteBoot(result.bootId)\n    const previous = lastVersion\n    lastVersion = result\n    if (previous !== null && answeredByAnotherProcess(previous, result)) {\n      warmCatalog = null\n      for (const listener of [...restartListeners]) listener(result)\n    }\n    return result\n  }\n  // The check is advisory, and so is its failure: a transport that cannot\n  // answer leaves the last answer standing, which is all this path can do.\n  const firstAnswer = version()\n  void firstAnswer.catch(() => {})\n  // dsh reconnects to whatever server holds the origin and reloads nothing,\n  // so a restart from a terminal, by a supervisor, or one whose own reload\n  // never came leaves the page on the old process's answers. Asking again on\n  // every connection — the first one after boot included, which only finds\n  // the process the warm-up already found — is how the page learns it.\n  ctx.on('connection/reset', () => {\n    // Advisory, like the warm-up above: a failed ask changes nothing.\n    void version().catch(() => {})\n  })\n\n  // The host's own result: the stash when it is fresh, the wire otherwise.\n  // Every result becomes the stash, refresh included. A plain open only\n  // consumes it inside the host's own freshness window.\n  //\n  // `reverdict` is not a network refresh: it is \"judge again against the\n  // installation as it stands now\", asked with the same plain call as a\n  // stash-expired open, so it gets the host's own snapshot and freshness\n  // window rather than forcing npm/registry work a refresh would. It always\n  // bypasses the stash (an install or uninstall just settled, so the stash\n  // predates it) and always becomes the new one. Every branch below builds\n  // its own literal for `ns.catalog(...)` rather than forwarding the\n  // caller's `args` — the host RPC accepts only `{ refresh?: boolean }`, and\n  // a client-only key like `reverdict` must never reach the wire, even by a\n  // future field added to `args` and forwarded by accident.\n  const hostCatalog = async (args?: { refresh?: boolean; reverdict?: boolean }): Promise<ShopCatalogResult> => {\n    // `refresh` is checked FIRST: it also bypasses the stash and restashes,\n    // exactly like reverdict, so checking it first costs the\n    // refresh branch nothing — but checking reverdict first would have let a\n    // caller-supplied `{ refresh: true, reverdict: true }` fall into the\n    // reverdict branch and silently drop the network refresh the caller\n    // asked for.\n    if (args?.refresh === true) {\n      const refreshed = unwrap(await ns.catalog({ refresh: true }))\n      warmCatalog = { at: Date.now(), result: Promise.resolve(refreshed) }\n      return refreshed\n    }\n    if (args?.reverdict === true) {\n      // Dropped before asking, not after: a failed reverdict must not leave\n      // the PRE-mutation stash standing for the next plain open to replay —\n      // the mutation already landed, so no stash is safer than a stale one.\n      warmCatalog = null\n      const judged = unwrap(await ns.catalog(undefined))\n      warmCatalog = { at: Date.now(), result: Promise.resolve(judged) }\n      return judged\n    }\n    const warm = warmCatalog\n    if (warm !== null && Date.now() - warm.at < WARM_TTL_MS) {\n      try {\n        return await warm.result\n      } catch {\n        // The stashed fetch failed; a fresh call is the retry.\n      }\n    }\n    const fresh = unwrap(await ns.catalog(undefined))\n    warmCatalog = { at: Date.now(), result: Promise.resolve(fresh) }\n    return fresh\n  }\n\n  // \"Does the shelf list this name?\", for the Plugins page's button (design\n  // 2026-10-16-shop-sidebar-page §7): the stash, whatever its age — a\n  // listing question needs none of a shelf's freshness — and one plain read\n  // when there is no stash to ask. A question asked while that read is in\n  // flight shares it rather than start another whole-catalog read; the\n  // window opens whenever a mutation drops the stash. Once the read settles,\n  // the next question finds the stash it left, or reads again if it failed.\n  let listingRead: Promise<ShopCatalogResult> | null = null\n  const listing = async (): Promise<ShopCatalogResult> => {\n    const warm = warmCatalog\n    if (warm !== null) {\n      try {\n        return await warm.result\n      } catch {\n        // The stashed fetch failed; the plain read below is the retry.\n      }\n    }\n    listingRead ??= hostCatalog().finally(() => { listingRead = null })\n    return listingRead\n  }\n\n  // The host's peer list is only half a verdict (module-table.ts says why and\n  // how much of it is wrong), so every result is refined against this page's\n  // module table on its way to the tab — warm, stashed, fresh and refreshed\n  // alike, exactly once each. On the way OUT, never on the way in: the warm\n  // fetch starts during plugin boot, when nothing guarantees the `modules`\n  // service is registered yet, while the tab cannot be opened before it is —\n  // the web shell mounts its UI only once plugin boot has run (`runPluginBoot`\n  // then `mountApp`, on 0.1.5-rc.3). The table also grows as modules\n  // materialize, so the stash keeps the host's own result and each hand-over\n  // judges it against the table as it stands then.\n  //\n  // Read through the reflect shop rather than declared in `inject`: an inject\n  // requirement would hold the whole tab back on a harness that publishes no\n  // table, where the right cost is the peer badges alone\n  // (`refineAgainstModuleTable` answers `{}` there).\n  const handOver = async (result: ShopCatalogResult): Promise<ShopCatalogResult> => ({\n    ...result,\n    // `result.incompatible` is `?? {}`'d before it ever reaches the\n    // refinement: a host built at 0.5.4 or earlier answers without the field\n    // at all, and `refineIncompatible` reads it with an unguarded\n    // `Object.entries`, so an absent field would reject a function this\n    // module documents as never rejecting.\n    incompatible: await refineAgainstModuleTable(result.incompatible ?? {}, ctx.get('modules') as unknown, pageRemoved),\n  })\n\n  // The restart the tab is handed, registered as this instance's path to the\n  // host: when a self-update's HMR swap tears this mount down with a restart\n  // in flight, the page asks again through the instance that replaces it.\n  const restart = async (): Promise<ShopRestartResult> => unwrap(await ns.restart())\n  withdrawRestart = registerRestartCarrier(restart)\n\n  // The face's mutators, named because the page store runs its flows on them\n  // too. Each drops the stash the MOMENT it starts, not when it settles\n  // (design 2026-09-01-harness-compatibility section 9.1): a mutation always\n  // changes what a reverdict would say, and the next plain open, on this tab\n  // or a fresh one, must ask the host rather than replay a stash from before\n  // the mutation. Residual: a mount DURING the mutation refills the stash\n  // before the mutation settles. The page store covers that case: a settle\n  // leaves it a pending reverdict, and the next mount asks for that first\n  // (design 2026-10-16-shop-sidebar-page §5.4).\n  const install: ShopTabInjected['install'] = async args => { warmCatalog = null; return unwrap(await ns.installStart(args)) }\n  const installStatus: ShopTabInjected['installStatus'] = async args => unwrap(await ns.installStatus(args))\n  const uninstall: ShopTabInjected['uninstall'] = async args => { warmCatalog = null; return unwrap(await ns.uninstallStart(args)) }\n  const updateStart: ShopTabInjected['updateStart'] = async args => { warmCatalog = null; return unwrap(await ns.updateStart(args)) }\n  // Favorites and rollback (design 2026-11-02-market-borrowings §6–§7). A\n  // rollback is a mutation of the profile like any other, so it drops the\n  // catalog stash for the same reason an install does.\n  const state: ShopTabInjected['state'] = async () => unwrap(await ns.state())\n  const setFavorite: ShopTabInjected['setFavorite'] = async args => unwrap(await ns.setFavorite(args))\n  const rollback: ShopTabInjected['rollback'] = async args => { warmCatalog = null; return unwrap(await ns.rollbackStart(args)) }\n  const noteUninstalled = (name: string): void => { pageRemoved.add(name) }\n\n  // The page's store (page-store.ts): the reader's place on the shelf and\n  // every flow, kept across leaving and returning (design\n  // 2026-10-16-shop-sidebar-page §5). Built per apply, since a re-applied\n  // bundle is a new page, and disposed with this instance, so its polling\n  // never outlives the code that started it. It hears every restart under\n  // the page, whether or not a tab is mounted to hear it.\n  const page = createPageStore(() => ({ install, uninstall, updateStart, installStatus, noteUninstalled }), { pollUnwatched: true })\n  // The store this one replaces is disposed with its own instance; disposing\n  // it here as well covers an instance whose teardown never ran. Disposal is\n  // idempotent, and its hand-over stays readable (design\n  // 2026-10-16-shop-sidebar-page §5.1). A later shop's store, met after a\n  // downgrade, need not share this shape: it is read as another schema's,\n  // and only a `dispose` it has is called (`disposeOccupant`), so a missing\n  // one cannot throw the shop off the page.\n  disposeOccupant(installPageStore(page))\n  ctx.effect(() => () => { page.dispose() }, 'dsh-plugin-shop: page store')\n  restartListeners.add(() => { page.noteRestarted() })\n\n  // dsh's layout service, read through the reflect shop rather than `inject`,\n  // as `modules` is: what needs it degrades without it, and an inject\n  // requirement would hold the whole client back on a harness that lacks it.\n  // Read as a shape to check rather than to trust: a service without\n  // `selectPanel`, as a reshaped one could be, cannot move the reader, so\n  // nothing here calls it or offers to.\n  const layout = (): Partial<ShopLayoutFace> | undefined => ctx.get('layout') as Partial<ShopLayoutFace> | undefined\n  const selectShopPage = (): void => {\n    const service = layout()\n    if (typeof service?.selectPanel !== 'function') return\n    try {\n      service.selectPanel(SHOP_PANEL)\n    } catch {\n      // dsh refuses a key no `main` entry holds, the one throw `selectPanel`\n      // documents: this instance's own entry is gone, a teardown under way,\n      // so there is no page to select.\n    }\n  }\n  /** Open the shop's own page inside dsh's plugin manager, where its Update\n   * button runs the remove → install → restore operation the shop cannot run\n   * on itself. `pluginNavigation.openBundle` is the direct route: it selects\n   * the Plugins panel, switches to Installed and opens this package's detail\n   * page. A harness without that service (before dsh's plugin manager\n   * exported it) falls back to selecting the panel itself — one click further\n   * from the update, but no dead button. */\n  const openDshPluginPage = (): void => {\n    const navigation = ctx.get('pluginNavigation') as Partial<ShopPluginNavigationFace> | undefined\n    if (typeof navigation?.openBundle === 'function') {\n      try {\n        navigation.openBundle(SHOP_PACKAGE)\n        return\n      } catch {\n        // A service whose page is not mounted refuses the call; the panel\n        // selection below is the part that still can work.\n      }\n    }\n    const service = layout()\n    if (typeof service?.selectPanel !== 'function') return\n    try {\n      service.selectPanel(DSH_PLUGINS_PANEL)\n    } catch {\n      // See `selectShopPage`: a key no `main` entry holds is the one throw,\n      // and there is nothing else this button can do about it.\n    }\n  }\n\n  const injected = (): ShopTabInjected => ({\n    catalog: async args => handOver(await hostCatalog(args)),\n    install,\n    installStatus,\n    setEnabled: async args => unwrap(await ns.setEnabled(args)),\n    installed: async () => unwrap(await ns.installed()),\n    installedSpecs: async () => unwrap(await ns.installedSpecs()),\n    uninstall,\n    noteUninstalled,\n    restart,\n    version,\n    onRestarted: listener => {\n      restartListeners.add(listener)\n      return () => { restartListeners.delete(listener) }\n    },\n    updateStart,\n    state,\n    setFavorite,\n    rollback,\n    openUpdatePage: openDshPluginPage,\n    page,\n  })\n\n  // The shop's own page in dsh's main column (design\n  // 2026-10-16-shop-sidebar-page §4.1), under the key its sidebar row\n  // selects. The page first: the row's click selects `shop`, which dsh\n  // refuses while no `main` entry holds that key.\n  ctx.slots.inject('main', () => [\n    ctx.slots.register({\n      name: 'main',\n      key: SHOP_PANEL,\n      locale: NS,\n      inject: injected,\n    }, ShopPage),\n    // Listed after the registration, so it runs before it: cordis disposes\n    // an effect's collected disposers in reverse. The record reads the\n    // page's own mount (ShopPage.tsx), never dsh's selection, and the entry\n    // leaving is what unmounts the page, so run first it reads the page as\n    // the reader last saw it, even on a host that unmounts the page the\n    // moment its entry leaves (design 2026-10-16-shop-sidebar-page §6).\n    () => { page.recordTeardown() },\n  ])\n  // Its row in the sidebar, directly under dsh's own Plugins row (order 0)\n  // and above Automation (10). The sidebar owns the button, its label and its\n  // selection; the shop supplies the glyph.\n  ctx.slots.inject('sidebar.panellist', () => ctx.slots.register({\n    name: 'sidebar.panellist',\n    id: SHOP_PANEL,\n    order: 5,\n    label: () => ctx.locale.bind(NS)('title'),\n    locale: NS,\n  }, ShopGlyph))\n  // The Plugins page's two buttons (0.1.7-rc.2 and later; design\n  // 2026-10-16-shop-sidebar-page §7). They open the page through the layout\n  // service, so without one that can select it they do not render\n  // (`canOpen`).\n  ctx.slots.inject('plugins.detail.actions', () => ctx.slots.register({\n    name: 'plugins.detail.actions',\n    id: SHOP_PANEL,\n    order: 0,\n    locale: NS,\n    inject: (): ShopDetailActionInjected => ({ listing, canOpen: () => typeof layout()?.selectPanel === 'function', openShop: selectShopPage, page }),\n  }, ShopDetailAction))\n\n  // The hand-over (design 2026-10-16-shop-sidebar-page §6). A hot swap took\n  // the page from a reader who was on it (rule 1), or swapped out a 0.8.x\n  // shop that lived in Settings (rule 2): either way the page that offers the\n  // restart comes back. Rule 2 sees 0.8.4 and later, through the restart\n  // monitor's store. From 0.8.4–0.8.6 the dialog stays on Built-in plugins\n  // and falls back to its first tab, and from 0.8.7 to its first section;\n  // 0.8.0–0.8.3 leave nothing to see and read as a fresh page, so nothing\n  // moves. Only while an update waits for a restart — a bundle switched off\n  // and on again leaves none, and must not move the reader — and only once,\n  // with this instance's own page in place.\n  //\n  // The first answer includes the host's npm lookup, which it makes uncached\n  // before it reads the profile's copy: about a second, and up to about 10 s\n  // when the registry does not answer (5 s for each of two registries). A\n  // reader who goes elsewhere in that window is moved to the page once, when\n  // the answer lands. That is accepted, with no time bound: the move brings\n  // the restart offer the update needs, and a bound would skip it exactly\n  // when an update has just finished on a slow mirror.\n  if (predecessor.kind === 'section' || (predecessor.kind === 'page' && predecessor.showing)) {\n    void firstAnswer.then(answer => {\n      if (updateAwaitsRestart(answer)) selectShopPage()\n    }, () => {\n      // No answer, no claim that an update waits: nothing moves.\n    })\n  }\n}\n"
    },
    {
      "path": "packages/dsh-plugin-shop/src/host/catalog.ts",
      "content": "/** Catalog fetch, verification, and disk cache — the Host's only network path. */\n\nimport { createHash } from 'node:crypto'\nimport { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'\nimport { dirname, join } from 'node:path'\nimport { z } from 'zod'\nimport { type CatalogOrigin, type OriginHandle, TransportError, httpOrigin } from './origin.ts'\nimport { normalizeRegistryUrl, npmOrigin } from './npm-origin.ts'\nimport { inCompletionOrder } from './race.ts'\nimport type { CatalogEntry, DeniedEntry } from './types.ts'\nimport { COMMIT_SHA, RELEASE_TAG } from '../shared/identity.ts'\nimport { CATALOG_NPM_NAME } from '../shared/npm-name.ts'\n\n/** Highest schemaVersion this build understands; a higher one is refused (§10).\n * 3 adds `source` and repo entries (github install channel); 4 adds `subdir`\n * for monorepo-subpackage entries (2026-08-31 hub-borrowings A); 5 adds\n * `added`, `tarball` (release rescue), the `theme` category, and\n * `denied[].replacement` (2026-08-31 market borrowings).\n *\n * 6 adds nothing. It was reserved for `peers` (2026-09-01 harness\n * compatibility), and that gate came off on 2026-09-03 without ever being\n * opened: `peers` rides 5, as every additive optional key does, because this\n * schema strips a key it does not know while a higher version NUMBER is what\n * a capped client refuses outright. Every shop built since this constant\n * became 6 accepts a 6 without knowing what one would mean, so a change those\n * shops must refuse has to be 7. */\nexport const SUPPORTED_SCHEMA_VERSION = 6\n\n/** A cached catalog younger than this is served without touching the network. */\nconst FRESH_MS = 5 * 60 * 1000\n\n/** How long a probe may take before the race gives up on that origin. Long\n * enough for a slow but working link, short enough that a black-holed origin\n * does not hold the shelf closed. */\nconst PROBE_TIMEOUT_MS = 10_000\n\n/** How long the committed origin has to produce its pointer. `httpOrigin`\n * answers instantly — its probe already fetched the bytes — but `npmOrigin`\n * downloads its tarball here, so this is a bulk-transfer budget, not a probe\n * one. Without it a winner that stalls mid-body parks the race forever while\n * healthy origins sit settled and unread, which is the exact failure the race\n * exists to prevent. Generous against every measured npm origin (12.53 MB/s\n * mirror -> 0.12 s for 1.5 MB; npmjs direct 1.99 MB/s -> 0.75 s). */\nconst COMMIT_TIMEOUT_MS = 30_000\n\n/** Run one committed-origin read under a deadline and abort it on expiry. */\nasync function withCommitBudget<T>(\n  id: string,\n  what: string,\n  start: (signal: AbortSignal) => Promise<T>,\n): Promise<T> {\n  const controller = new AbortController()\n  let timer: ReturnType<typeof setTimeout> | undefined\n  try {\n    return await Promise.race([\n      start(controller.signal),\n      new Promise<never>((_resolve, reject) => {\n        timer = setTimeout(() => {\n          const expired = new TransportError(`${id} did not ${what} within ${COMMIT_TIMEOUT_MS} ms`)\n          controller.abort(expired)\n          reject(expired)\n        }, COMMIT_TIMEOUT_MS)\n      }),\n    ])\n  } finally {\n    clearTimeout(timer)\n  }\n}\n\n// npm's package-name grammar lives in `shared/npm-name.ts` so the registry's\n// gate and `emit`'s last-line invariant read the same definition.\n\n/** Canonical SemVer 2.0.0, including legal prerelease/build metadata. */\nconst NPM_VERSION = /^(?:0|[1-9]\\d*)\\.(?:0|[1-9]\\d*)\\.(?:0|[1-9]\\d*)(?:-(?:0|[1-9]\\d*|\\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\\.(?:0|[1-9]\\d*|\\d*[a-zA-Z-][0-9a-zA-Z-]*))*)?(?:\\+[0-9a-zA-Z-]+(?:\\.[0-9a-zA-Z-]+)*)?$/\n\n/** The repository binding used to build a GitHub install spec. */\nconst REPO_FULL_NAME = /^[\\w.-]+\\/[\\w.-]+$/\n\n/** Records when the loader itself wrote the cache; the pointer's `builtAt` is\n * the catalog's build time, not the cache's fetch time. */\nconst META_FILE = 'index.meta.json'\n\n/**\n * The grammar a pointer's file url must satisfy to name a cache file.\n *\n * `basename()` was the derivation and cannot be: the url is untrusted wire\n * data, and on untrusted input `basename` is neither confining nor\n * platform-independent.\n *\n *  - `basename('.')` is `.`, and `join(cacheDir, '.')` collapses to `cacheDir`\n *    itself — so the data-file write landed on the cache DIRECTORY and\n *    `writeFileSync` answered EISDIR. `resolveDataUrl` admits the url (`new\n *    URL('.', base)` IS `base`, so the origin check passes), which is how a\n *    pointer reached it.\n *  - `win32.basename('a\\\\b.json')` is `b.json` while `posix.basename` of the\n *    same string is the whole string, so the cache file one pointer names\n *    differed per platform for a url the WHATWG parser normalises the same way\n *    everywhere. Two hosts sharing a cacheDir disagreed about what was cached.\n *\n * So: a plain file name, tested rather than derived, and deliberately narrow —\n * no separator in either spelling, no leading dot (which excludes `.` and\n * `..`), no colon, no percent. Every catalog this project publishes names\n * `plugins.<sha256>.json` and `stars.<sha256>.json`, and `npmOrigin.file()`\n * has always refused anything else outright. This is the http transport\n * adopting the npm transport's rule, not a new one — before it the two\n * disagreed about the same pointer, which design §2 (\"one build, two\n * transports, one snapshot\") does not allow.\n */\nconst POINTER_FILE_NAME = /^[A-Za-z0-9][A-Za-z0-9._-]*$/\n\n/** The cache file a pointer url names — one derivation for all four sites, so\n * the path a load WRITES and the path the next boot READS cannot drift apart.\n * Throws on a url outside the grammar; the caller decides whether that is\n * loud (the plugins url, which is pointer interpretation) or advisory (the\n * stars sidecar, spec §5). */\nfunction cachePath(cacheDir: string, url: string, what: string): string {\n  if (!POINTER_FILE_NAME.test(url)) {\n    throw new Error(`catalog ${what} url ${JSON.stringify(url)} must be a plain file name`)\n  }\n  return join(cacheDir, url)\n}\n\nconst entrySchema = z.object({\n  // Bounded and control-character-free for every source. GitHub names can\n  // originate in an untrusted repository manifest and still reach argv.\n  name: z.string().min(1).max(214).regex(/^[^\\u0000-\\u001f\\u007f]+$/, 'entry name carries a control character'),\n  version: z.string().min(1).max(256),\n  integrity: z.string().nullable(),\n  publishedAt: z.string().nullable(),\n  repository: z.string().nullable(),\n  license: z.string().nullable(),\n  tier: z.enum(['verified', 'verified-stale', 'community']),\n  metadata: z.enum(['declared', 'derived']),\n  review: z.object({\n    reviewedVersion: z.string().optional(),\n    reviewedCommit: z.string().optional(),\n    // The release-rescued pin: the reviewed tarball's content hash, never the\n    // tag (a tag is a mutable ref an author can re-point at different content).\n    reviewedSha256: z.string().optional(),\n    // WHICH repository was reviewed. A github review binds (`repo`,\n    // `reviewedCommit`) and never a name, because 83 live bundle names are\n    // claimed by both a fork and an original — so without this key a verified\n    // badge cannot say which of them passed. The registry has written it since\n    // the review record existed (`config.ts` `repo: row.repo`); every client\n    // stripped it, exactly as `installSize` was stripped, and nothing noticed\n    // because `verified.yml` is empty. Declared now while the cost is zero.\n    repo: z.string().optional(),\n    reviewer: z.string(),\n    reviewCommit: z.string(),\n    notes: z.string(),\n  }).optional(),\n  catalog: z.object({\n    // v5: `theme` joins the enum. An old client's closed enum rejects a\n    // catalog containing it wholesale, which is why v5 is emitted only behind\n    // the release-time SHOP_CATALOG_V5 flag (design §3.5).\n    category: z.enum(['tool', 'provider', 'ui', 'workflow', 'integration', 'theme', 'other']),\n    summary: z.object({ en: z.string(), zh: z.string().optional() }),\n    capabilities: z.array(z.string()),\n  }).optional(),\n  // v3 (github channel); defaulted so a cached v2 catalog still parses.\n  source: z.enum(['npm', 'github']).default('npm'),\n  repo: z.string().regex(REPO_FULL_NAME, 'repo must be owner/slug').optional(),\n  // v4 (monorepo subpackages). The value reaches the install spec's argv,\n  // so the boundary keeps it to relative directory segments — and no\n  // segment may be `.` or `..`, which would escape the repository root.\n  subdir: z.string().regex(/^(?!.*(^|\\/)\\.\\.?(\\/|$))[A-Za-z0-9._-]+(\\/[A-Za-z0-9._-]+)*$/).optional(),\n  // v5 (market borrowings): `added` on every entry, and the release-rescue\n  // `tarball` — whose URL the coherence check below binds to the entry's\n  // own repo. `added` is OPTIONAL on the consumer: the live v4 catalog (and\n  // any cached pre-v5 data file) carries no such field, and requiring it\n  // made 0.5.0 refuse the still-published v4 catalog outright. Our own\n  // builds always carry it (registry E9); the client shows it on a card under\n  // the shelf's 「最新上架」 order (design 2026-10-12-shelf-orders §4).\n  added: z.string().optional(),\n  tarball: z.object({ url: z.string(), sha256: z.string().regex(/^[0-9a-f]{64}$/) }).optional(),\n  // The npm publishing account, additive and optional — deliberately NOT a\n  // schemaVersion bump. A version higher than SUPPORTED_SCHEMA_VERSION is\n  // refused outright above, so bumping to 6 would make every installed 0.5.x\n  // shop reject the catalog; an unknown key, by contrast, is stripped by this\n  // non-strict schema, which is what lets old and new hosts share one\n  // catalog. Same reasoning as `added`.\n  publisher: z.string().optional(),\n  // The package's declared peer dependency names, riding every schemaVersion\n  // (see SUPPORTED_SCHEMA_VERSION for the version-6 gate that never opened).\n  // OPTIONAL on the consumer, and this is not a style preference: a package\n  // that declares no peers carries none, and no github entry carries any yet\n  // — the registry harvests them from 2026-09-24 but withholds them from\n  // emission (`withholdRepoPeers`) until `SHOP_EMIT_REPO_PEERS` flips (design\n  // 2026-09-01-harness-compatibility §8.1, §9.8) — and making `added`\n  // required is exactly what made 0.5.0 refuse the published catalog for\n  // every user.\n  peers: z.array(z.string()).optional(),\n  // The author's own `dsh.compatibility` (same design, §8.2): a semver range\n  // over `@deepseek-ai/dsh` versions and the profile names the plugin\n  // supports, either of which may stand alone. A REQUIREMENT, never a\n  // verdict — the host judges it against the running installation\n  // (`compatibility.ts`). Additive and optional, so it rides every\n  // schemaVersion, and declared because this schema strips a key it does not\n  // know: that is how `installSize` was published for weeks and shown to\n  // nobody. Non-strict inside too, so a half this build has never heard of is\n  // stripped rather than refused.\n  //\n  // Typed rather than waved through, like the size keys below: the host hands\n  // `dsh` to semver and `profiles` to a membership test, and the registry\n  // publishes strings only, so anything else is our own build having written\n  // what it cannot write.\n  compatibility: z.object({\n    dsh: z.string().optional(),\n    profiles: z.array(z.string()).optional(),\n  }).optional(),\n  // The package's peers on the harness itself with their ranges verbatim\n  // (design 2026-09-26-dsh-017-readiness, B1): what dsh 0.1.7 refuses an\n  // install on, handed to the running dsh's own check (`peerVerdictsOf`).\n  // Declared for the reason `compatibility` is, and typed like it: the\n  // registry writes strings only (`dshPeersOf`), the empty range included.\n  // Both channels carry it: an npm entry is judged by its own `version`, a\n  // github entry by `manifestVersion` below, and not at all without one\n  // (design 2026-09-28-bundle-components-and-github-peers, section 7.3).\n  dshPeers: z.record(z.string(), z.string()).optional(),\n  // A github entry's installed manifest `version` (same design, section 6.1;\n  // registry `Entry.manifestVersion`): the version dsh keys an exemption by,\n  // where the entry's catalog `version` is a commit or a release tag. The\n  // registry writes it on github entries only, together with `dshPeers` or\n  // not at all: an npm entry's own `version` is already its manifest's.\n  // Declared for the reason every key above is: this schema strips a key it\n  // does not know, and `installSize` was published for weeks stripped this\n  // same way.\n  //\n  // Typed, and refused on the one thing typing can refuse: a non-string, on\n  // either channel, which costs the whole data file, since it is parsed with\n  // a throw. Nothing else is refused, so neither a stray key on an npm entry\n  // nor a github entry carrying one half of the pair costs a reader the\n  // catalog: the host reads the key on github entries only, and judges no\n  // github entry without both. Unbounded, unlike `version`: the registry\n  // bounds it, dsh's rule reads it only as an exemption key, and the one\n  // place it reaches a terminal, the exemption command, is offered only for\n  // an exact version (`allowVersionCommand`).\n  manifestVersion: z.string().optional(),\n  // The manifest's own `engines.dsh` range (design 2026-11-02-market-borrowings\n  // §1; registry `Entry.engines`). Not decoration: dsh 0.2.1's own rule returns\n  // on this key and never reads `dshPeers` when it is present, so\n  // `peerVerdictsOf` hands both to that rule and the verdict now matches what\n  // the install will actually do. A string on both channels, the empty range\n  // included — dsh reads a blank range as unsatisfiable on purpose, and a\n  // schema that refused one would cost a reader the whole data file over a\n  // verdict dsh forms fine.\n  engines: z.string().optional(),\n  // The count of the manifest's runtime `dependencies` (same design, §2). One\n  // bounded integer the registry writes; typed so a hand-edited catalog cannot\n  // put a string where the detail row formats a number.\n  dependencies: z.number().int().nonnegative().optional(),\n  // The command names the manifest's `bin` declares (same design, §2): a fact\n  // about the install surface, never a claim about what the command does. The\n  // registry bounds the list to three of 48 characters; the schema bounds it\n  // again because the strings are rendered as text in the detail row.\n  bin: z.array(z.string()).optional(),\n  // Whether the manifest declares a `preinstall`, `install` or `postinstall`\n  // script (registry `Entry.installScripts`; design 2026-11-04-borrowings-round-4\n  // §2). pnpm 10+ refuses to run one unless the profile allows it, so the\n  // detail row says the package asked to run code at install time. The\n  // registry writes `true` only and omits the key otherwise; typed as a\n  // boolean so a hand-edited `false` reads as \"declares none\" rather than\n  // costing the whole data file.\n  installScripts: z.boolean().optional(),\n  // npm's `dist.unpackedSize`, additive and optional for the same reason as\n  // `publisher` — this schema strips a key it does not know, so old and new\n  // hosts share one catalog, while bumping the version NUMBER would make\n  // every capped client refuse it outright.\n  //\n  // Typed rather than waved through: the client formats this into a size\n  // label, and a fraction or a negative would render as one. The registry\n  // already drops anything that is not a safe non-negative integer\n  // (`npm-client.ts`), so a value arriving here that fails this is our own\n  // build having written something it cannot write — which is exactly the\n  // class of thing this project stops for.\n  //\n  // `.int()` carries the safe-integer bound itself — zod 4 caps it at\n  // MAX_SAFE_INTEGER, so 2^53 and 1e21 are refused here and this matches the\n  // registry's `Number.isSafeInteger` guard exactly rather than merely\n  // resembling it. Measured, not assumed, and pinned by the cases in\n  // `catalog.test.ts`: a zod change that relaxed it would otherwise let\n  // through an integer JSON cannot round-trip.\n  unpackedSize: z.number().int().nonnegative().optional(),\n  // The same quantity for EVERY source: what installing the entry puts on\n  // disk. npm repeats `dist.unpackedSize` into it, a commit-pinned github\n  // entry sums its git tree's blobs (scoped to `subdir`), a release-rescued\n  // one sums the tarball it already inflated (registry `Entry.installSize`).\n  //\n  // A SECOND key rather than filling `unpackedSize` for github too, and the\n  // reason is this file: the superRefine below does not ignore a github\n  // `unpackedSize`, it raises on one, and the data file is read with a\n  // throwing `parse`. Filling the old key would therefore have cost every\n  // already-installed shop the WHOLE catalog until its client updated —\n  // which is not observable from here. An unknown key is stripped instead,\n  // so the registry shipped this alone and the catalog has carried it since\n  // 0.8.1; declaring it here is what finally lets a github size be SEEN.\n  //\n  // Same bound as `unpackedSize` and for the same reason — the client formats\n  // it into a label, and a fraction or a negative renders as one. Stated\n  // rather than inherited: until a key is declared it is stripped, so every\n  // malformed value parsed in silence.\n  installSize: z.number().int().nonnegative().optional(),\n  // Whether GitHub reports the repository as archived. github entries only;\n  // additive and optional, so it rides every schemaVersion and this schema\n  // strips it for a client that predates it (design 2026-10-08 §1.3).\n  archived: z.boolean().optional(),\n  // Whether GitHub reports the repository as a fork, answered by the same\n  // GraphQL pass as `archived` and emitted the same way (design 2026-10-11\n  // §1.1). github entries only; additive and optional, so it rides every\n  // schemaVersion and this schema strips it for a client that predates it.\n  forked: z.boolean().optional(),\n  // The sha256 that keys this entry's icon in the catalog's icons sidecar\n  // (registry `Entry.icon`; design 2026-10-23-shop-plugin-icons §6.1). Additive\n  // and optional, so it rides every schemaVersion and this schema strips it\n  // for a client that predates it (§6.3). Declared because this schema drops a\n  // key it does not know: an undeclared icon would be published and then lost\n  // by every shop, which is what `catalog-parity.test.ts` refuses.\n  //\n  // Held to the one grammar the registry writes (`assertCatalogInvariants`),\n  // like `tarball.sha256`, because the value only ever keys a lookup. The cost\n  // is the same too — a value outside it fails the throwing `parse` and costs\n  // the whole data file — which is why the build stops on one first.\n  icon: z.string().regex(/^[0-9a-f]{64}$/).optional(),\n}).superRefine((entry, ctx) => {\n  // The install spec differs by source, so the grammar does too. Refusing at\n  // this boundary prevents catalog bytes from reaching the process layer.\n  if (entry.source === 'npm') {\n    if (!CATALOG_NPM_NAME.test(entry.name)) {\n      ctx.addIssue({ code: 'custom', path: ['name'], message: `npm entry name ${JSON.stringify(entry.name)} is outside npm package-name grammar` })\n    }\n    if (!NPM_VERSION.test(entry.version)) {\n      ctx.addIssue({ code: 'custom', path: ['version'], message: `npm entry version ${JSON.stringify(entry.version)} is not a plain semver version` })\n    }\n    return\n  }\n  if (entry.repo === undefined) {\n    ctx.addIssue({ code: 'custom', path: ['repo'], message: 'a github entry must carry its repo — it is the entry\\'s identity and the spec is built from it' })\n  }\n  // `unpackedSize` names npm's OWN quantity, so a github entry carrying one is\n  // our build writing a number it cannot have measured: what GitHub reports is\n  // the repository's disk usage including history, which is not what installing\n  // the plugin puts on disk, and for a monorepo subpackage is not even close.\n  // A github size arrives as `installSize` instead, summed from the git tree's\n  // blobs — so this refuses a WRONG number under a right-looking key, and does\n  // not refuse github sizes as such (it did until 0.8.1; see `installSize`).\n  //\n  // Load-bearing rather than tidy: the data file is read with a throwing\n  // `parse`, so one github `unpackedSize` costs every already-installed shop\n  // the WHOLE catalog rather than the one entry. `assignRepoTier` merely\n  // happens not to write one today; the design states the rule, and without\n  // this it was stated nowhere that could refuse a violation.\n  if (entry.unpackedSize !== undefined) {\n    ctx.addIssue({ code: 'custom', path: ['unpackedSize'], message: 'a github entry carries no unpacked size — GitHub measures the repository, not the install' })\n  }\n  // GitHub entries use either a commit pin or a release tag. A tag may exist\n  // without a tarball; install() will report that missing rescue explicitly.\n  if (!COMMIT_SHA.test(entry.version) && !RELEASE_TAG.test(entry.version)) {\n    ctx.addIssue({ code: 'custom', path: ['version'], message: `github entry version ${JSON.stringify(entry.version)} is neither a 40-character commit sha nor a release tag` })\n  }\n}).transform((entry) => (\n  // ONE size key downstream. `installSize` is the field every consumer reads;\n  // `unpackedSize` is a wire-compatibility key the registry keeps emitting for\n  // npm so that a client older than this one still shows npm sizes.\n  //\n  // The merge belongs HERE and not at the render site, because this is the only\n  // place that knows an entry's `source` — the superRefine directly above has\n  // just proved that an `unpackedSize` present at all belongs to an npm entry,\n  // where the two keys name one quantity (equal on all 4,275 live npm entries,\n  // measured 2026-09-15). Doing it here makes the precedence a property of a\n  // parsed `CatalogEntry` rather than of one JSX expression: a second consumer\n  // — a sort, a detail row, an install confirmation — cannot read the stale key\n  // by accident, which is the failure `installSize` itself just shipped in\n  // reverse. Retiring `unpackedSize` then deletes this transform and its\n  // declaration, instead of hunting every read site.\n  entry.installSize === undefined && entry.unpackedSize !== undefined\n    ? { ...entry, installSize: entry.unpackedSize }\n    : entry\n))\n\nconst dataSchema = z.object({\n  schemaVersion: z.number(),\n  plugins: z.array(entrySchema),\n  // v5: `replacement` names the known substitute on a denial.\n  denied: z.array(z.object({ name: z.string(), detail: z.string(), replacement: z.string().optional() })).default([]),\n  /** Names the client's shop-like NAME filter must NOT hide: entries whose\n   * name reads like a competing plugin market but which are not one\n   * (registry/not-a-shop.yml). Defaulted, so a catalog built before this key\n   * existed still parses — the data file is non-strict for the same reason\n   * the pointer is. */\n  notAShop: z.array(z.string()).default([]),\n})\n\n/** The tarball URL must be the entry's own GitHub release — path segments\n * `/<owner>/<repo>/releases/...` matching the entry's `repo` (case-\n * insensitive). A catalog row that names a trusted repo but installs an\n * archive from somewhere else is refused loudly, never installed\n * (dsh-market's release-binding rule, their sources.ts:16-49). */\nfunction validateEntryCoherence(entries: CatalogEntry[]): void {\n  for (const entry of entries) {\n    if (entry.tarball === undefined) continue\n    if (entry.source !== 'github' || entry.repo === undefined) {\n      throw new Error(`catalog entry ${entry.name}: tarball requires a github entry with a repo`)\n    }\n    let parsed: URL\n    try {\n      parsed = new URL(entry.tarball.url)\n    } catch {\n      throw new Error(`catalog entry ${entry.name}: tarball url is unparseable`)\n    }\n    if (parsed.protocol !== 'https:' || parsed.hostname !== 'github.com') {\n      throw new Error(`catalog entry ${entry.name}: tarball url must be https on github.com`)\n    }\n    // Query strings and fragments can carry shell punctuation into the\n    // install spec. Release assets are addressed by their path alone.\n    if (parsed.search !== '' || parsed.hash !== '') {\n      throw new Error(`catalog entry ${entry.name}: tarball url must carry no query or fragment`)\n    }\n    const segments = parsed.pathname.split('/').filter(s => s !== '')\n    const owner = segments[0] ?? ''\n    const slug = segments[1] ?? ''\n    if (`${owner}/${slug}`.toLowerCase() !== entry.repo.toLowerCase() || segments[2] !== 'releases') {\n      throw new Error(`catalog entry ${entry.name}: tarball url is not a release of ${entry.repo}`)\n    }\n  }\n}\n\n// Non-strict on purpose: a future index may carry keys this build does not\n// know, and stripping them is what keeps old installed hosts working against\n// it. Do not add .strict().\nconst pointerSchema = z.object({\n  schemaVersion: z.number(),\n  builtAt: z.string(),\n  count: z.number(),\n  plugins: z.object({ url: z.string(), sha256: z.string() }),\n  stars: z.object({ url: z.string(), sha256: z.string() }).optional(),\n  icons: z.object({ url: z.string(), sha256: z.string() }).optional(),\n})\n\nexport interface CatalogSnapshot {\n  schemaVersion: number\n  builtAt: string\n  entries: CatalogEntry[]\n  denied: DeniedEntry[]\n  /** Names the shop-like NAME filter must not hide (registry/not-a-shop.yml).\n   * Absent for a catalog built before the key existed, which is why it is\n   * optional rather than defaulted here: the parse defaults it, a snapshot\n   * assembled by hand need not carry it. */\n  notAShop?: string[]\n  /** GitHub star counts by package name; {} when the pointer names no\n   * sidecar or the sidecar could not be fetched/verified (spec §5). */\n  stars: Record<string, number>\n  /** sha256 → data URL for the catalogue's icons; {} when the pointer names no\n   * sidecar, or it could not be fetched, verified or parsed (design\n   * 2026-10-23-shop-plugin-icons §7). Optional like `notAShop`: `loadCatalog`\n   * always sets it, and a snapshot assembled by hand need not carry it. */\n  icons?: Record<string, string>\n}\n\nexport interface CatalogResult { snapshot: CatalogSnapshot; stale: boolean }\n\nexport interface CatalogFs {\n  exists: (path: string) => boolean\n  read: (path: string) => string\n  write: (path: string, data: string) => void\n}\n\nconst nodeFs: CatalogFs = {\n  exists: path => existsSync(path),\n  read: path => readFileSync(path, 'utf8'),\n  write: (path, data) => {\n    mkdirSync(dirname(path), { recursive: true })\n    writeFileSync(path, data)\n  },\n}\n\nexport interface LoadCatalogOptions {\n  /** A single HTTP origin — the explicit-override spelling. Mutually\n   * exclusive with `origins`; exactly one must be given. */\n  baseUrl?: string\n  /** Origins to race (design §3). */\n  origins?: CatalogOrigin[]\n  cacheDir: string\n  refresh?: boolean\n  fetchImpl?: typeof fetch\n  now?: () => Date\n  fsImpl?: CatalogFs\n  sleep?: (ms: number) => Promise<void>\n}\n\n/** Read and verify a cached/fetched stars sidecar; ANY irregularity degrades\n * to an empty map — stars are advisory (spec §5). */\nfunction parseStarsText(text: string): Record<string, number> {\n  try {\n    const parsed = JSON.parse(text) as { stars?: unknown }\n    if (typeof parsed.stars !== 'object' || parsed.stars === null) return {}\n    // The sidecar keys are package/repository names, so keep the parsed map\n    // free of inherited names such as `constructor`.\n    const out: Record<string, number> = Object.create(null) as Record<string, number>\n    for (const [key, value] of Object.entries(parsed.stars)) {\n      if (typeof value === 'number') out[key] = value\n    }\n    return out\n  } catch {\n    return {}\n  }\n}\n\n/** The most one catalogue icon may weigh, matching the registry's bound\n * (design 2026-10-23-shop-plugin-icons §6.2). */\nconst MAX_CATALOG_ICON_BYTES = 32 * 1024\n\n/** The longest a data URL holding MAX_CATALOG_ICON_BYTES can be: the base64\n * alphabet is 4 characters per 3 bytes, and the prefix is the longest of the\n * four media types' spellings. */\nconst MAX_ICON_DATA_URL_LENGTH = 'data:image/svg+xml;base64,'.length + Math.ceil(MAX_CATALOG_ICON_BYTES / 3) * 4\n\n/** The four types a catalogue icon can have (design §6.1); nothing else\n * reaches an `img.src`. */\nconst ICON_DATA_URL = /^data:image\\/(?:svg\\+xml|png|jpeg|webp);base64,[A-Za-z0-9+/]+={0,2}$/\n\n/**\n * Read and verify an icons sidecar; ANY irregularity degrades to no icons —\n * icons are presentation, and they never cost the reader the catalog (§7).\n * The checks are the grammar the build writes: a 64-hex sha256 keying a\n * `data:` URL of the four types, each within the per-icon bound.\n */\nfunction parseIconsText(text: string): Record<string, string> {\n  try {\n    const parsed = JSON.parse(text) as { icons?: unknown }\n    if (typeof parsed.icons !== 'object' || parsed.icons === null || Array.isArray(parsed.icons)) return {}\n    const out: Record<string, string> = Object.create(null) as Record<string, string>\n    for (const [key, value] of Object.entries(parsed.icons)) {\n      if (!/^[0-9a-f]{64}$/.test(key)) return {}\n      if (typeof value !== 'string' || value.length > MAX_ICON_DATA_URL_LENGTH || !ICON_DATA_URL.test(value)) return {}\n      out[key] = value\n    }\n    return out\n  } catch {\n    return {}\n  }\n}\n\n/**\n * Load the catalog snapshot: fetch the pointer, verify the data file's sha256\n * against it, cache both on disk, and serve the cached copy with `stale: true`\n * only when the transport itself failed — the fetch threw or returned a\n * non-2xx (§10). A schemaVersion higher than this build supports, a malformed\n * pointer or data file, an absolute data URL, or a sha256 mismatch — fresh or\n * cached — throws even when a cache exists; never silently degraded. The stars\n * sidecar is the sole exception: any irregularity there, a refused url\n * included, degrades to no stars (spec §5).\n */\nexport async function loadCatalog(options: LoadCatalogOptions): Promise<CatalogResult> {\n  const {\n    cacheDir, refresh = false,\n    fetchImpl = fetch, now = () => new Date(), fsImpl = nodeFs,\n  } = options\n  // Exactly one spelling of \"where to fetch from\": the explicit-override\n  // single origin, or the list Task 5's race consumes. tsc cannot see the\n  // XOR through to a narrowed `options.baseUrl`, hence the one assertion\n  // below — safe only because this guard runs first.\n  if ((options.baseUrl === undefined) === (options.origins === undefined)) {\n    throw new Error('loadCatalog: exactly one of baseUrl or origins is required')\n  }\n  const originList = options.origins\n    ?? [httpOrigin(options.baseUrl as string, fetchImpl)]\n  if (originList.length === 0) throw new Error('loadCatalog: no origins')\n  const indexPath = join(cacheDir, 'index.json')\n  const metaPath = join(cacheDir, META_FILE)\n\n  /** The timestamp freshness is measured from: the sidecar's fetch time when\n   * it exists and parses, else the pointer's builtAt when that parses, else\n   * null (\"no usable freshness fact\"). */\n  const freshnessTimeOf = (builtAt: string): number | null => {\n    if (fsImpl.exists(metaPath)) {\n      try {\n        const fetchedAt = Date.parse((JSON.parse(fsImpl.read(metaPath)) as { fetchedAt: string }).fetchedAt)\n        if (!Number.isNaN(fetchedAt)) return fetchedAt\n      } catch {\n        // A corrupt sidecar means \"no freshness fact\"; fall through to builtAt.\n      }\n    }\n    const built = Date.parse(builtAt)\n    return Number.isNaN(built) ? null : built\n  }\n\n  const readCached = (): CatalogSnapshot | null => {\n    let pointer: ReturnType<typeof pointerSchema.parse>\n    let data: ReturnType<typeof dataSchema.parse>\n    try {\n      pointer = pointerSchema.parse(JSON.parse(fsImpl.read(indexPath)))\n      if (pointer.schemaVersion > SUPPORTED_SCHEMA_VERSION) throw new Error(\n        `catalog schemaVersion ${pointer.schemaVersion} is newer than this build supports (${SUPPORTED_SCHEMA_VERSION})`,\n      )\n      const dataPath = cachePath(cacheDir, pointer.plugins.url, 'data')\n      const dataText = fsImpl.read(dataPath)\n      // The cached bytes must still bind to the pointer's sha: installed\n      // plugins hold full fs access and could rewrite the cache, so a file\n      // that fails the check is treated as absent, never served (§9.2).\n      const actual = createHash('sha256').update(dataText).digest('hex')\n      if (actual !== pointer.plugins.sha256) {\n        throw new Error(`cached catalog data failed integrity check: expected ${pointer.plugins.sha256}, got ${actual}`)\n      }\n      data = dataSchema.parse(JSON.parse(dataText))\n      if (data.schemaVersion > SUPPORTED_SCHEMA_VERSION) throw new Error(\n        `catalog schemaVersion ${data.schemaVersion} is newer than this build supports (${SUPPORTED_SCHEMA_VERSION})`,\n      )\n    } catch {\n      // Cache unreadable or invalid — treat as absent rather than failing a\n      // boot that could instead fetch a fresh catalog.\n      return null\n    }\n    // The binding check sits OUTSIDE the swallow: a cached row that names a\n    // trusted repo but installs an archive from somewhere else is a poisoned\n    // cache, refused loudly like the wire version — never served stale and\n    // never silently refetched (§9.2 fail-loudly).\n    validateEntryCoherence(data.plugins)\n    let stars: Record<string, number> = {}\n    if (pointer.stars !== undefined) {\n      try {\n        const starsText = fsImpl.read(cachePath(cacheDir, pointer.stars.url, 'stars'))\n        const starsActual = createHash('sha256').update(starsText).digest('hex')\n        if (starsActual === pointer.stars.sha256) stars = parseStarsText(starsText)\n      } catch {\n        // A missing or tampered cached sidecar means no stars this boot; the\n        // catalog bytes are already verified above, so nothing else fails.\n      }\n    }\n    let icons: Record<string, string> = {}\n    if (pointer.icons !== undefined) {\n      try {\n        const iconsText = fsImpl.read(cachePath(cacheDir, pointer.icons.url, 'icons'))\n        const iconsActual = createHash('sha256').update(iconsText).digest('hex')\n        if (iconsActual === pointer.icons.sha256) icons = parseIconsText(iconsText)\n      } catch {\n        // As above, for icons: presentation, degraded rather than fatal.\n      }\n    }\n    return {\n      schemaVersion: pointer.schemaVersion,\n      builtAt: pointer.builtAt,\n      entries: data.plugins,\n      denied: data.denied,\n      notAShop: data.notAShop,\n      stars,\n      icons,\n    }\n  }\n\n  if (!refresh && fsImpl.exists(indexPath)) {\n    const cached = readCached()\n    if (cached !== null) {\n      const fetchedAt = freshnessTimeOf(cached.builtAt)\n      if (fetchedAt !== null && now().getTime() - fetchedAt < FRESH_MS) {\n        return { snapshot: cached, stale: false }\n      }\n    }\n  }\n\n  // Transport failures only (fetch threw, or a non-2xx response) degrade to\n  // the cached snapshot with `stale: true`. Everything that interprets the\n  // fetched bytes — pointer parse, schemaVersion checks, sha256 comparison,\n  // data parse — throws on any irregularity, cache or no cache (§9.2, §10).\n  const cachedOrThrow = (error: unknown): CatalogResult => {\n    const cached = readCached()\n    if (cached !== null) return { snapshot: cached, stale: true }\n    throw error\n  }\n\n  // Race every origin's cheap probe and commit to the first that answers\n  // (design §3). A transport failure — in the probe, or in the `pointer()`\n  // call below, which is where npmOrigin does its bulk tarball download —\n  // moves to the next finisher; anything else throws, so a corrupt origin is\n  // never hidden behind a healthy one. \"Or on the bulk fetch\" would be too\n  // broad: the OTHER bulk fetch in this function, `handle.file()` for the\n  // data file, happens after the loop has committed and falls back to the\n  // disk cache instead, never to another origin (see below, and race.ts).\n  let handle: OriginHandle | null = null\n  let pointerText = ''\n  let lastTransportError: unknown = new TransportError('no catalog origin was reachable')\n  for await (const settled of inCompletionOrder(\n    originList.map(origin => origin.probe(AbortSignal.timeout(PROBE_TIMEOUT_MS))),\n  )) {\n    if (!('value' in settled)) {\n      if (!(settled.reason instanceof TransportError)) throw settled.reason\n      lastTransportError = settled.reason\n      continue\n    }\n    try {\n      pointerText = await withCommitBudget(settled.value.id, 'produce a pointer', () => settled.value.pointer())\n      handle = settled.value\n      break\n    } catch (error) {\n      if (!(error instanceof TransportError)) throw error\n      lastTransportError = error\n    }\n  }\n  if (handle === null) return cachedOrThrow(lastTransportError)\n\n  const pointer = pointerSchema.parse(JSON.parse(pointerText))\n  if (pointer.schemaVersion > SUPPORTED_SCHEMA_VERSION) {\n    throw new Error(\n      `catalog schemaVersion ${pointer.schemaVersion} is newer than this build supports (${SUPPORTED_SCHEMA_VERSION})`,\n    )\n  }\n\n  // Derived here, before the fetch, and loudly: the data url has to name a\n  // cache file, and deciding that is pointer INTERPRETATION like the\n  // schemaVersion check above — so it throws rather than degrading, and a url\n  // that could never be cached does not cost a download first.\n  const dataCachePath = cachePath(cacheDir, pointer.plugins.url, 'data')\n\n  // handle.file resolves (and refuses absolute/cross-origin) URLs internally\n  // now, so a refused URL surfaces as a plain Error, never a TransportError —\n  // the instanceof guard below is what keeps that refusal a loud throw like\n  // the other pointer-interpretation failures, instead of a stale fallback.\n  let dataText: string\n  try {\n    dataText = await withCommitBudget(\n      handle.id,\n      `serve ${pointer.plugins.url}`,\n      signal => handle!.file(pointer.plugins.url, signal),\n    )\n  } catch (error) {\n    if (!(error instanceof TransportError)) throw error\n    return cachedOrThrow(error)\n  }\n\n  const actual = createHash('sha256').update(dataText).digest('hex')\n  if (actual !== pointer.plugins.sha256) {\n    throw new Error(`catalog data failed integrity check: expected ${pointer.plugins.sha256}, got ${actual}`)\n  }\n\n  const data = dataSchema.parse(JSON.parse(dataText))\n  if (data.schemaVersion > SUPPORTED_SCHEMA_VERSION) {\n    throw new Error(\n      `catalog schemaVersion ${data.schemaVersion} is newer than this build supports (${SUPPORTED_SCHEMA_VERSION})`,\n    )\n  }\n  // Same coherence gate as the cached path: a tarball URL bound to anything\n  // but the entry's own repo is refused loudly whether it came from the wire\n  // or the cache — before any install spec could be built from it.\n  validateEntryCoherence(data.plugins)\n\n  let stars: Record<string, number> = {}\n  if (pointer.stars !== undefined) {\n    const sidecar = pointer.stars\n    try {\n      // Both the cache path and the fetch resolution sit inside the advisory\n      // catch: a stars url that is refused — absolute, cross-origin, or not a\n      // plain file name — must degrade to no stars like any other sidecar\n      // failure. It still prevents the fetch, but never throws the loader out\n      // of a catalog whose data fetched fine (spec §5, §9.2).\n      const starsCachePath = cachePath(cacheDir, sidecar.url, 'stars')\n      const starsText = await withCommitBudget(\n        handle.id,\n        `serve ${sidecar.url}`,\n        signal => handle!.file(sidecar.url, signal),\n      )\n      const starsActual = createHash('sha256').update(starsText).digest('hex')\n      if (starsActual === sidecar.sha256) {\n        stars = parseStarsText(starsText)\n        fsImpl.write(starsCachePath, starsText)\n      }\n    } catch {\n      // Advisory: an unreachable or refused sidecar means no stars this run\n      // (spec §5).\n    }\n  }\n\n  let icons: Record<string, string> = {}\n  if (pointer.icons !== undefined) {\n    const sidecar = pointer.icons\n    try {\n      // Advisory like the stars sidecar: a refused or unreachable icons url\n      // must degrade to default artwork, never cost the reader the catalog.\n      const iconsCachePath = cachePath(cacheDir, sidecar.url, 'icons')\n      const iconsText = await withCommitBudget(\n        handle.id,\n        `serve ${sidecar.url}`,\n        signal => handle!.file(sidecar.url, signal),\n      )\n      const iconsActual = createHash('sha256').update(iconsText).digest('hex')\n      if (iconsActual === sidecar.sha256) {\n        icons = parseIconsText(iconsText)\n        fsImpl.write(iconsCachePath, iconsText)\n      }\n    } catch {\n      // Presentation only (design 2026-10-23 §7).\n    }\n  }\n\n  const snapshot: CatalogSnapshot = {\n    schemaVersion: pointer.schemaVersion,\n    builtAt: pointer.builtAt,\n    entries: data.plugins,\n    denied: data.denied,\n    notAShop: data.notAShop,\n    stars,\n    icons,\n  }\n  // Order is the invariant: a file becomes reachable only once whatever it\n  // names is already on disk. The data file first, then the pointer that\n  // names it, then the freshness note that declares that pointer current.\n  //\n  // Reversed — as this was — a failure after `index.json` lands leaves the\n  // pointer naming a file that was never written, and `readCached` then reads\n  // the whole cache as ABSENT. So a write that fails here did not merely fail\n  // to cache the new catalog: it unbound the good one already on disk, and\n  // the next offline boot threw instead of degrading (§10).\n  //\n  // And a cache write failure is not a load failure. `snapshot` is already\n  // fetched and verified; a read-only cacheDir, a full disk, or another dsh\n  // holding `index.json` open costs offline degradation on the NEXT boot and\n  // nothing on this one, so throwing here would take a working catalog down\n  // over an optimisation.\n  try {\n    fsImpl.write(dataCachePath, dataText)\n    fsImpl.write(indexPath, JSON.stringify(pointer))\n    fsImpl.write(metaPath, JSON.stringify({ fetchedAt: now().toISOString() }))\n  } catch {\n    // Nothing to add and nothing else to try: the snapshot is returned either\n    // way, and the ordering above means a partial write leaves the previous\n    // cache readable rather than half-rebound.\n  }\n  return { snapshot, stale: false }\n}\n\n/** The catalog base the shipped `cordis.patch.yml` names. A row carrying\n * exactly this value expresses no preference, so the loader races its\n * defaults; anything else is a deliberate override and is used alone. */\nexport const DEFAULT_CATALOG_URL = 'https://LivXue.github.io/dsh-plugin-shop/v1/'\n\n/** The npm package carrying the same `v1/` tree (design §2). */\nexport const CATALOG_PACKAGE = 'dsh-plugin-shop-catalog'\n\n/** Registries raced by default: the domestic mirror first for legibility —\n * the race, not the order, decides the winner. */\nconst DEFAULT_REGISTRIES = ['https://registry.npmmirror.com/', 'https://registry.npmjs.org/']\n\n/**\n * The origins to race for this installation (design §3).\n *\n * @param catalogUrl - the row's configured base.\n * @param npmRegistry - the user's own registry from `~/.npmrc`, or null.\n */\nexport function catalogOrigins(\n  catalogUrl: string,\n  fetchImpl: typeof fetch,\n  npmRegistry: string | null,\n): CatalogOrigin[] {\n  // An explicit override must not be raced: racing would make the e2e\n  // fixture nondeterministic and would silently defeat \"point the shop at my\n  // own mirror\", which the README documents.\n  if (catalogUrl !== DEFAULT_CATALOG_URL) return [httpOrigin(catalogUrl, fetchImpl)]\n  const registries = [...DEFAULT_REGISTRIES]\n  // Normalised before the membership check: `npm config set` writes\n  // `registry=https://registry.npmmirror.com` with no trailing slash, which\n  // is byte-different from the default above and would otherwise race\n  // npmmirror twice under two different origin ids.\n  const normalizedNpmRegistry = npmRegistry === null ? null : normalizeRegistryUrl(npmRegistry)\n  if (normalizedNpmRegistry !== null && !registries.includes(normalizedNpmRegistry)) registries.unshift(normalizedNpmRegistry)\n  return [\n    ...registries.map(registry => npmOrigin(registry, CATALOG_PACKAGE, fetchImpl)),\n    httpOrigin(catalogUrl, fetchImpl),\n  ]\n}\n"
    },
