      "path": "packages/dsh-plugin-shop/src/host/install.ts",
      "content": "/** Install gate: the gate rejection paths of §7.2, as a pure function. */\n\nimport type { CatalogSnapshot } from './catalog.ts'\nimport type { CatalogEntry } from './types.ts'\nimport { holderLabel, identityKey, specVerdict } from '../shared/identity.ts'\n\nexport type InstallRejectionCode =\n  | 'not-in-catalog'\n  | 'denied'\n  | 'version-mismatch'\n  | 'needs-acknowledgement'\n  | 'tarball-integrity'\n  | 'ambiguous-identity'\n  | 'name-taken'\n  | 'desktop-profile'\n\nexport interface InstallArgs {\n  name: string\n  version: string\n  acknowledged?: boolean\n  /** Optional identity fields keep old clients readable while refusing an\n   * ambiguous name-only request when the catalog has duplicate names. */\n  source?: 'npm' | 'github'\n  repo?: string\n  subdir?: string\n}\n\nexport type ValidateResult =\n  | { ok: true; entry: CatalogEntry }\n  | { ok: false; code: InstallRejectionCode; detail: string }\n\n/**\n * Decide whether an install request may proceed and return the resolved row.\n *\n * `installedSpec` is the profile manifest's dependency for `args.name`, when\n * it has one.\n *\n * What this refuses is REPLACEMENT, and the mechanism is the manifest key: a\n * profile holds one dependency per name, the shop writes `dependencies[name]`,\n * so installing a second plugin of that name overwrites the first and a plugin\n * the user chose is gone with no notice.\n *\n * 177 of the catalog's names are claimed by more than one entry, over 461\n * entries, `dsh-skill-manager` alone by 14 (2026-09-06). This comment is the\n * ONE place that figure is kept, because three copies of it had already\n * drifted apart — the design doc said 172/451 and present.ts said 151/243.\n * It tracks the ecosystem, so re-derive rather than trust it: group\n * `registry/snapshots/manifest.lock` by bundle name, which is field 0 on an\n * npm row (`<name> <version> sha512-…`) and field 1 on every github one\n * (`<owner/slug> <bundle name> <commit|tag>`) — reading field 1 for all of\n * them undercounts by the 176 release-rescued rows.\n *\n * That is the whole of what the name buys. It is NOT the same rule as the\n * loader's, and the two must not be confused — an earlier version of this\n * comment and of the published detail said \"they declare the same loader entry\n * id\", which is false for a measurable share of the pairs refused here:\n * `Anyway-one/dsh-balance` declares `id: balance` while `ZHIZHU4410/deepseek-\n * balance`, also bundle-named `dsh-balance`, declares `id: dsh-balance`. Those\n * two would load side by side happily if a profile could hold both.\n *\n * The loader's own rule cuts the other way and this gate does not reach it:\n * two DIFFERENTLY-named bundles declaring one entry id make dsh refuse the\n * whole tree —\n *\n *   Error: dsh: plugin tree failed to load: failed to apply loader entry\n *   include (cordis:include): duplicate loader entry id: plugin-manager\n *\n * — and the profile does not boot at all. `2768651338/dsh-plugin-manager` and\n * `Dingpenghui-good/dsh-plugin-manager` carry different bundle names and both\n * declare `id: plugin-manager`, so this gate passes them. A candidate's entry\n * ids are not knowable before its files are on disk, which is why the check\n * for that lives after the install lands rather than here (see\n * `collidingEntryId` in index.ts).\n *\n * Passing the spec in rather than reading the manifest here keeps the whole\n * gate a pure function driven by fixtures.\n */\nexport function validateInstall(\n  snapshot: CatalogSnapshot,\n  args: InstallArgs,\n  installedSpec?: string,\n): ValidateResult {\n  const denied = snapshot.denied.find(d => d.name === args.name)\n  if (denied !== undefined) {\n    return { ok: false, code: 'denied', detail: `dsh-plugin-shop: installation of ${args.name} is blocked: ${denied.detail}` }\n  }\n\n  let entry: CatalogEntry | undefined\n  if (args.source === undefined) {\n    // Compatibility with an old client: unique names remain answerable, but\n    // guessing among duplicate repositories would install the wrong code.\n    const named = snapshot.entries.filter(e => e.name === args.name)\n    if (named.length > 1) {\n      return {\n        ok: false,\n        code: 'ambiguous-identity',\n        detail: `dsh-plugin-shop: the catalog has ${named.length} plugins named ${args.name}. Refresh the shop and select the one you want to install.`,\n      }\n    }\n    entry = named[0]\n  } else {\n    const wanted = identityKey({ source: args.source, name: args.name, repo: args.repo, subdir: args.subdir })\n    entry = snapshot.entries.find(candidate => identityKey(candidate) === wanted)\n    if (entry === undefined) {\n      return { ok: false, code: 'not-in-catalog', detail: `dsh-plugin-shop: ${wanted} is not in the catalog` }\n    }\n  }\n\n  if (entry === undefined) {\n    return { ok: false, code: 'not-in-catalog', detail: `dsh-plugin-shop: ${args.name} is not in the catalog` }\n  }\n  if (entry.version !== args.version) {\n    return { ok: false, code: 'version-mismatch', detail: `dsh-plugin-shop: you requested ${args.name}@${args.version}, but the catalog lists ${entry.version}. Refresh the shop and try again.` }\n  }\n  // Ahead of the acknowledgement gate, so a request that cannot proceed never\n  // asks the reader to accept a plugin's privileges first. The shipped client\n  // opens its own §9.3 dialog before it calls, so this ordering is what any\n  // OTHER caller of the RPC gets; the client closes its own gate on the same\n  // verdict (see ShopTab's nameTakenBy).\n  //\n  // A same-identity request is the ordinary update path and passes — the\n  // manifest key it would overwrite is its own.\n  if (installedSpec !== undefined) {\n    const verdict = specVerdict(entry, installedSpec)\n    if (verdict !== 'same') {\n      const holder = holderLabel(installedSpec, args.name)\n      // `unknown` is a spec the grammar does not cover — a git remote, a\n      // `file:` checkout, an `npm:` alias. Refusing it is the point: the shop\n      // must not overwrite something it cannot identify, and saying which\n      // string is in the way is the only honest thing left to say about it.\n      const what = verdict === 'unknown'\n        ? `dsh-plugin-shop: ${args.name} is already installed from ${holder}. The shop could not match it to a catalog entry.`\n        : `dsh-plugin-shop: ${args.name} is already installed from ${holder}.`\n      return {\n        ok: false,\n        code: 'name-taken',\n        detail: `${what} Installing this plugin would replace it, since a profile can hold only one plugin of each name.`\n          + ' To switch, uninstall the existing plugin first.',\n      }\n    }\n  }\n  if (entry.tier !== 'verified' && !args.acknowledged) {\n    const detail = entry.tier === 'verified-stale'\n      ? `dsh-plugin-shop: a different version of ${args.name} was reviewed. The current version has not been reviewed. Confirm the installation to continue.`\n      : `dsh-plugin-shop: ${args.name} is a community plugin and has not been reviewed. Confirm the installation to continue.`\n    return { ok: false, code: 'needs-acknowledgement', detail }\n  }\n  return { ok: true, entry }\n}\n"
    },
    {
      "path": "packages/dsh-plugin-shop/src/host/index.ts",
      "content": "/** ShopGateway: the Host half of dsh-plugin-shop (§5.1). */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport { Remote, TypertRemoteService } from '@deepseek-ai/dsh-typert-protocol'\nimport { readProfileManifest } from '@deepseek-ai/dsh-app-boot'\nimport { lt, minVersion, valid } from 'semver'\nimport { createHash, randomUUID } from 'node:crypto'\nimport { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'\nimport { fileURLToPath, pathToFileURL } from 'node:url'\nimport { dirname, join } from 'node:path'\nimport { homedir } from 'node:os'\nimport { bootId, ownPeerRanges, runningVersion } from '../own-version.ts'\nimport { catalogOrigins, loadCatalog, type LoadCatalogOptions } from './catalog.ts'\nimport type { CatalogResult, CatalogSnapshot } from './catalog.ts'\nimport type { CatalogOrigin } from './origin.ts'\nimport { npmrcRegistry } from './npmrc.ts'\nimport type { CatalogEntry, DeniedEntry } from './types.ts'\nimport { validateInstall, type InstallArgs, type InstallRejectionCode } from './install.ts'\nimport { gateOperand, INSTALL_TIMEOUT_MS, retryCommand, startInstall, startUninstall, type InstallStatus, type RunningInstall } from './executor.ts'\nimport { cleanHotDir, hotMount, hotUnmount, nodeHotFs, type HotFs } from './hot.ts'\nimport { FAVORITES_MAX, nodeShopStateFs, readShopState, rollbackSpec, writeShopState, type ShopRollbackRecord, type ShopStateFs } from './state.ts'\nimport { activationOf, type Activation } from './activation.ts'\nimport { hasClientHalf } from './client-half.ts'\nimport { restartCommand, startRestart, type RestartOutcome } from './restart.ts'\nimport { fetchLatestVersion } from './self-update.ts'\nimport { detectSupervisor } from './supervisor.ts'\nimport { readRepoPins, writeRepoPins, type RepoPinFs } from './repo-pins.ts'\nimport { collidingEntryId, declaredBundlePatch, discoverProfile, ownedEntries, ownedEntryIds, ownsEntryId, setUserLayerRows, type OwnedEntry } from './profile.ts'\nimport { patchDeclarationHazard } from './bundle-patch.ts'\nimport { isDesktopProfile } from './dsh-cli.ts'\nimport { identityKey, installedSpecMatches, parseSpec } from '../shared/identity.ts'\nimport { isTerminalInstallState, type InstallState } from '../shared/install-state.ts'\nimport { createPrefetcher, type Prefetcher } from './prefetch.ts'\nimport {\n  createPeerVersionCheck,\n  harnessPackageResolver,\n  harnessPackageVersionResolver,\n  incompatibilityMap,\n  nodeResolver,\n  nodeVersionResolver,\n  type HarnessPackageLookup,\n  type PeerResolver,\n  type PeerVersionResolver,\n} from './peers.ts'\nimport { compatibilityMap, peerVerdictsOf, type HarnessVerdict, type PeerVerdict } from './compatibility.ts'\nimport { readRunningHarness, type HarnessLocator, type RunningHarness } from './harness.ts'\nimport { continueAfter, ManagerLogs, messageOf, startManagerOperation } from './manager-runner.ts'\nimport { asPluginManager, codeReason, forDesktopReader, managerOutcome, readChange, readUpdate, thrownTail, type ManagerChange, type ManagerOutcome, type OutcomeContext, type PluginManagerLike } from './plugin-manager.ts'\n\n// Re-exported so the boundary type is reachable from the package's public\n// ./types subpath; the typert generator refuses remote parameter types it\n// cannot import from there.\nexport type { InstallArgs, InstallRejectionCode } from './install.ts'\nexport type { HotRestartReason } from './hot.ts'\n// Otherwise only reachable through a result field (e.g. ShopSetEnabledResult\n// ['activation']), which left `lib/index.d.ts` emitting it as module-local\n// and unnamed for a `dsh-plugin-shop/remote` consumer (M-5).\nexport type { Activation } from './activation.ts'\n// The catalog entry shape reaches the client half through this same boundary.\nexport type { CatalogEntry } from './types.ts'\n// So does the compatibility verdict, which lives beside the pure function that\n// forms it; the client imports it from here, never from that module.\nexport type { HarnessVerdict } from './compatibility.ts'\n\n/** One Loader inventory entry, structurally — the shop never depends on\n * cordis-plugin-loader, whose types do not reach this package's typecheck. */\nexport interface InventoryEntry {\n  entryId: string\n  moduleName: string\n  enabled: boolean\n}\n\n/** One boot-layer Loader entry, structurally — the surface `liveDisableIds`\n * consumes. `fiber` is the entry's live activation (present while the plugin\n * is up); `update` flips its options. */\nexport interface LoaderEntryLike {\n  id?: string\n  options: { name?: string }\n  fiber?: unknown\n  update(options: { disabled: boolean | null }, create?: boolean, force?: boolean): Promise<void>\n}\n\n/** Test-only injection points; production callers pass nothing. */\nexport interface ShopGatewayOptions {\n  catalogUrl?: string\n  cacheDir?: string\n  loadCatalog?: (options: LoadCatalogOptions) => ReturnType<typeof loadCatalog>\n  /** The profile dsh installs into; discovered from this module's own\n   * location when omitted. */\n  profile?: string\n  /** The profile directory the user layer lives in; discovered when omitted. */\n  profileDir?: string\n  /** The Loader plugin inventory; read from `ctx` when omitted. The REAL\n   * host-side service returns the bare snapshot OBJECT `{ entries: [...] }`,\n   * not a bare array and not a wire envelope (hub-borrowings B assumed the\n   * array and the toggle crashed on the real shape — 0.5.2 fix; the envelope\n   * exists only on the remote's client side). Both shapes normalize in\n   * `listInventory()`. */\n  inventory?: { list(): Promise<{ entries: InventoryEntry[] } | InventoryEntry[]> }\n  /** Test-only injection: the hot-mount functions; production uses the real\n   * hotMount/hotUnmount. */\n  hot?: { mount: typeof hotMount; unmount: typeof hotUnmount }\n  /** Test-only injection: the filesystem `packageHasClientHalf` reads\n   * `dsh.client` through; the same seam `hot.ts` reads its patch through.\n   * Production uses `nodeHotFs`. */\n  hotFs?: HotFs\n  /** Test-only injection: the Loader's boot-layer entries; production reads\n   * them from `ctx.loader`. */\n  loaderEntries?: () => Array<LoaderEntryLike>\n  dshBin?: string\n  /** The dsh argv this process was launched with, for `shop/restart`;\n   * defaults to the real `process.argv` minus node and the script path. */\n  restartArgv?: string[]\n  /** The JS entry `shop/restart` re-runs; defaults to `process.argv[1]`, the\n   * script this dsh was started with. It is also what identifies the running\n   * harness for the `dsh.compatibility` verdict: the package that owns this\n   * script, through symlinks, is the dsh actually running, and its own\n   * app-boot supplies the profile templates (`harness.ts`). A script owned by\n   * anything else — a test runner, the desktop app's host entry — falls back\n   * to the harness's `pluginPackages` service, which names the dsh this\n   * process runs (2026-11-06 amendment); without that service both halves of\n   * the verdict stay silent. The tests about where the running version comes\n   * from pass a fixture install here, which is the production path; the rest\n   * inject `readHarness`. */\n  restartScript?: string\n  /** Test-only injection: how the running harness is read from\n   * `restartScript`; production uses `readRunningHarness`. It exists because\n   * an in-process test cannot import a module from another Windows drive\n   * under vitest's module runner, and a Windows runner has the checkout on D:\n   * and the temp dir, where every fixture harness lives, on C:. The read's\n   * import of the fixture's app-boot fails there, and the table reads empty.\n   * Production passes nothing, so the running dsh is read as before. Read\n   * once and kept either way (see `harnessRead`), so like the default it\n   * must never reject. */\n  readHarness?: (script: string | undefined) => Promise<RunningHarness>\n  /** Test-only injection: the exit the restart calls after the response is\n   * delivered. Production uses `process.exit`. */\n  exit?: (code?: number) => void\n  /** The pid the restart helper waits on before exec'ing the new dsh;\n   * defaults to this process. Tests point it at a dead pid so the fixture\n   * runs immediately instead of waiting for the vitest worker to exit. */\n  restartParentPid?: number\n  /** Test-only injection: the shop's latest-version lookup; production\n   * fetches the npm packument. */\n  fetchLatestVersion?: () => Promise<string | null>\n  /** Test-only injection: the version of the code this process loaded;\n   * production reads it once, when own-version.ts is first evaluated. */\n  runningVersion?: string\n  /** How long the gateway waits after a successful restart response before\n   * exiting the old process; test-only shortening, production uses 2s. */\n  restartExitDelayMs?: number\n  /** Test-only injection: the pins file's filesystem; production uses node:fs. */\n  pinFs?: RepoPinFs\n  /** Test-only injection: the profile state file's filesystem (favorites and\n   * rollback records, `state.ts`); production uses node:fs with a\n   * write-then-rename. */\n  stateFs?: ShopStateFs\n  /** Test-only injection: the explicit `allowRestart` override; production\n   * reads the loader row's `config.allowRestart`. */\n  allowRestart?: boolean\n  /** The environment `detectSupervisor` reads; production uses process.env. */\n  env?: NodeJS.ProcessEnv\n  /** The platform the restart gate reads; production uses process.platform. */\n  platform?: NodeJS.Platform\n  /** The pid `detectSupervisor` inspects; production uses process.ppid —\n   * the PARENT pid (a systemd unit's main process has ppid 1). */\n  ppid?: number\n  /** Test-only injection: how the release-tarball integrity check fetches\n   * the release asset; production uses global fetch. */\n  fetchTarball?: (url: string) => Promise<Response>\n  /** Test-only injection: answers whether a peer resolves. Production builds\n   * one from the profile anchor. */\n  resolvePeer?: PeerResolver\n  /** Test-only injection: answers which version a peer resolves at, for the\n   * load-time self-check. Production builds one from the profile anchor. */\n  resolvePeerVersion?: PeerVersionResolver\n  /** Test-only injection: the peer ranges the self-check judges against;\n   * production reads them from the shipped package.json. */\n  peerRanges?: Record<string, string>\n  /** Test-only injection: the download phase's pump; production builds the\n   * real one. A test gateway left with the real pump spawns `pnpm store add`\n   * — a live registry request — from every install that finds a command\n   * already queued for its profile. */\n  prefetcher?: Prefetcher\n  /** Test-only injection: the record of packages this process may already\n   * have imported. Production shares one module-scope set across every\n   * gateway in the process (see `importedThisProcess`), which a test file\n   * building many gateways would otherwise share as well. */\n  importedModules?: Set<string>\n}\n\n/** `shop/installStart` result (§7.3): rejections are typed wire values with an\n * author-readable `detail`, not thrown RPC errors. */\nexport type ShopInstallResult =\n  | { ok: true; installId: string; state: InstallState }\n  | { ok: false; code: InstallRejectionCode; detail: string }\n\nexport interface ShopInstallStatusResult extends InstallStatus { found: boolean }\n\n/**\n * `shop/setEnabled` result (§7.3): an unknown name is a typed wire value, not\n * a thrown RPC error.\n *\n * A union rather than one flat shape with two optional fields, so that\n * \"`activation` is present exactly when `ok`\" is something the compiler\n * holds instead of a sentence this comment asks every reader to hold. Every\n * `ok` answer says what the reader must do for the toggle to be visible — a\n * toggled package with a browser half needs a reload, which this result used\n * to be unable to say (design 2026-09-11-activation-model §6) — and every\n * refusal carries the detail that names why.\n *\n * The client still defaults an absent `activation` conservatively. This type\n * binds the process it is compiled into; the WIRE outlives it, because a tab\n * can reach an older in-process host for as long as one reload after a shop\n * self-update lands on disk.\n */\nexport type ShopSetEnabledResult =\n  | { ok: true; activation: Activation }\n  | { ok: false; detail: string }\n\n/** `shop/uninstallStart` result (§7.3): a name outside the catalog or not\n * installed is a typed wire value with an author-readable `detail`, not a\n * thrown RPC error. */\nexport type ShopUninstallResult =\n  | { ok: true; installId: string }\n  | { ok: false; detail: string }\n\n/** `shop/restart` result (§7.3): the restarted server's URL, or a typed\n * failure — on failure the old process is still serving. */\nexport type ShopRestartResult = RestartOutcome\n\n/** Why `shop/restart` would refuse, for a reason fixed for the life of this\n * process: the platform, the supervisor (env and ppid are read once at\n * construction), and the launch argv. Every one of them is decided before the\n * first request arrives, which is what lets `version()` advertise it and the\n * client name it without asking again.\n *\n * `restart()` carries one further refusal this deliberately omits — a running\n * install — because that one is transient: a mount-time answer about it would\n * be stale the moment the install finished, and a card would go on saying a\n * restart was impossible after it had become possible. Static here, dynamic\n * there; the split is the whole reason this is a separate predicate rather\n * than a cache of `restart()`'s answer. */\nexport type RestartBlockedReason = 'desktop' | 'from-default-profile' | 'windows' | 'systemd' | 'port-zero'\n\n/** Each blocked reason's author-readable refusal, written once.\n *\n * `restart()` returns these as its `detail` and `version()` returns the bare\n * reason for the client to localize, so the two can no longer disagree about\n * WHY a restart is impossible. They did: `version()` reported a boolean that\n * covered two of the refusals, the client had one string for that boolean, and\n * that string named systemd — so a Windows user was told to restart a systemd\n * service and to set an override that the platform check, being checked ahead\n * of the systemd one, could never reach. */\nconst RESTART_BLOCKED_DETAIL: Record<RestartBlockedReason, string> = {\n  desktop: 'dsh-plugin-shop: this profile is managed by the DeepSeek Harness desktop app. Restart the app to apply the change.',\n  'from-default-profile': 'dsh-plugin-shop: dsh was started with --from-default-profile. In dsh 0.2.1 and later, restarting with this flag recreates the profile from its template and deletes all installed plugins, including the shop. Restart dsh manually without this flag.',\n  windows: 'dsh-plugin-shop: restarting from the shop is not supported on Windows yet. Quit dsh and start it again to apply the change.',\n  systemd: 'dsh-plugin-shop: dsh is managed by systemd. Restart the service manually; restarting from the shop could stop the service without bringing it back. To allow restarts from the shop, set allowRestart: true in the shop configuration.',\n  'port-zero': 'dsh-plugin-shop: dsh was started with --port 0. Its port will change after a restart. Restart dsh manually and open the new address.',\n}\n\n/** Why the shop changes nothing in the desktop profile, for every mutation\n * that spawns dsh's CLI: install, uninstall and self-update. dsh refuses\n * the profile before any of them would run (`isDesktopProfile`), and the\n * failure that surfaced instead read \"pnpm failed in the profile\". */\nconst DESKTOP_PROFILE_DETAIL = 'dsh-plugin-shop: this profile is managed by the DeepSeek Harness desktop app.'\n  + ' The shop cannot change it through the command line. Add or remove plugins from the app.'\n\n/** Why the shop's own update cannot run in the desktop profile, and where it\n * can (2026-11-06 amendment). dsh's plugin manager refuses an in-place\n * update of an installed package (`already-installed`), and the CLI\n * continuation every other profile takes cannot run here: dsh's launcher\n * refuses `--profile desktop` outright. dsh's own Plugins page has the\n * operation the shop lacks — check, remove, install, restore on failure —\n * so that page is the path, and the client's version row offers it there. */\nconst DESKTOP_SELF_UPDATE_DETAIL = 'dsh-plugin-shop: this profile is managed by the DeepSeek Harness desktop app,'\n  + ' where the shop cannot replace itself while it is running. Update it from dsh\\'s Plugins page (插件):'\n  + ' select dsh-plugin-shop, then update it there; dsh removes and reinstalls it, restoring the old version if that fails.'\n\n/** Why a switch through dsh's `pluginManager` waits for an operation this\n * gateway started: dsh holds its profile lock for a whole install or removal\n * (`change()` wraps pnpm) and makes any other change wait for it up to its\n * `lockWaitMs`, 120 s, so a switch clicked mid-install would spin for two\n * minutes and then fail on the lock. The check is F-5's, `hasRunningCommand`.\n * The shop's own row writer takes no dsh lock, so what it writes alone (the\n * CLI path's switch, and switching a deselected package off) is not\n * refused. */\nconst switchWhileBusyDetail = (name: string): string => 'dsh-plugin-shop: an install, update or uninstall is still running'\n  + ` in this profile. Wait for it to finish before changing the enabled state of ${name}.`\n\n/** The line a record gains when dsh's plugin manager refuses an update in\n * place and the shop continues it through dsh's CLI (design\n * 2026-10-19-dsh-021-readiness §2): what dsh refused, and the command that\n * runs instead. It names a `dsh plugin` command, so it never reaches a\n * desktop reader: the continuation does not run in that profile. */\nfunction cliFallbackLine(profile: string, spec: string): string {\n  return `dsh-plugin-shop: dsh's plugin manager cannot update this package directly (already-installed). Continuing with: \\`dsh plugin --profile ${profile} add ${spec}\\``\n}\n\n/** `shop/version` result (§7.3): the RUNNING shop version (from the shipped\n * package.json, not the manifest's range), the npm latest when the check\n * could answer (`null` = no answer — advisory, never an error), and the\n * comparison verdict. */\nexport interface ShopVersionResult {\n  /** The version of the code this process is running, read when it loaded.\n   * Not the file on disk now: a self-update rewrites that in place. */\n  installed: string\n  latest: string | null\n  outdated: boolean\n  /** Why `shop/restart` would refuse, or null when nothing static stands in\n   * its way. The client drops the restart offer on a reason and renders that\n   * reason's own copy, keeping the pending-change notice either way. */\n  restartBlocked: RestartBlockedReason | null\n  /**\n   * The version the profile has installed when it is not the one running —\n   * an update that landed and waits for a restart — or null when the running\n   * code is what is installed, or the installed copy could not be read.\n   *\n   * This host always sends it. Absent, it comes from a host older than the\n   * field, and the client reads that as a restart still pending: a client\n   * newer than its host exists only because the disk holds a newer shop than\n   * the process running (design §7.3, 2026-09-27 amendment).\n   */\n  pendingVersion?: string | null\n  /**\n   * Which process answered (own-version.ts `bootId`): fixed for its life and\n   * different in the next. The client compares it across a reconnect — a new\n   * one is dsh restarted under the page — and across a restart's reload —\n   * the same one is a restart that never happened (design §8, 2026-10-06\n   * amendment).\n   *\n   * This host always sends it. Absent, it comes from a host older than the\n   * field, and the client judges nothing by it.\n   */\n  bootId?: string\n  /**\n   * Where this profile's self-update can run, when it cannot run here:\n   * `'dsh-page'` on the desktop profile, whose app updates the shop by\n   * removing and reinstalling it (dsh's `updateBundle`, the operation this\n   * shop cannot call on itself while it runs). Null on every profile the\n   * shop's own update button serves, and absent from a host older than the\n   * field — the client reads both as \"update here\".\n   */\n  selfUpdate?: 'dsh-page' | null\n}\n\n/** `shop/updateStart` result (§7.3): the self-update spawn, or a typed\n * refusal (a version that is not plain semver, or the desktop profile, whose\n * update belongs to dsh's own Plugins page). */\nexport type ShopUpdateResult =\n  | { ok: true; installId: string; state: InstallState }\n  | { ok: false; code?: 'desktop-manual'; detail: string }\n\n/** `shop/installed` entry (§7.3): one installed catalog plugin. The identity\n * fields distinguish same-named npm and GitHub rows; `installed` remains the\n * manifest spec or the recorded GitHub pin, and the client never does version\n * math.\n *\n * `shadowed` marks a row synthesized from the profile manifest for an\n * installed GitHub dependency whose name an npm catalog entry now holds: the\n * catalog row itself is refused `shadowed-by-npm`, so this row is the only\n * one the user can act on. It carries no catalog `latest` (hence the union)\n * and no `outdated` verdict, because there is no catalog truth to compare\n * against. */\nexport interface ShopInstalledEntry {\n  name: string\n  source: 'npm' | 'github'\n  repo?: string\n  subdir?: string\n  installed: string\n  latest: string | null\n  outdated: boolean\n  enabled: boolean\n  shadowed?: true\n}\n\n/** What `shop/state` answers (design 2026-11-02-market-borrowings §6–§7):\n * starred install identities, and per identity the version an update\n * replaced — the version a rollback would restore. */\nexport interface ShopStateResult {\n  favorites: string[]\n  rollback: Record<string, string>\n}\n\n/** Whether one install identity survives `state.ts`'s bounds (`KEY_MAX_LENGTH`\n * there). The RPC and the file must agree, or a star is answered saved and\n * then filtered away. */\nfunction isStorableKey(key: string): boolean {\n  return key.length > 0 && key.length <= 300\n}\n\n/** One row of the row config the bundle patch (§cordis.patch.yml) supplies. */\ninterface ShopRowConfig {\n  catalogUrl?: unknown\n  cacheDir?: unknown\n  allowRestart?: unknown\n}\n\n/** How many bytes a release tarball may be at the integrity check. The\n * registry already refuses to publish a tarball over 32 MiB, so 64 MiB is\n * headroom, not a gate of its own. */\nexport const MAX_TARBALL_BYTES = 64 * 1024 * 1024\n\n/**\n * Fetch a release tarball and verify its sha256 against the catalog record\n * (market borrowings §3.1). Returns a rejection detail, or null when the\n * bytes match. The read streams through the byte cap, so an oversized or\n * hostile body is refused without ever being buffered. Every failure — fetch\n * throw, non-2xx, unreadable body, over-cap, hash mismatch — carries the same\n * `tarball-integrity` code with a detail naming what happened, so the plugin\n * author can read the cause.\n */\nexport async function verifyTarballSha256(\n  fetchTarball: (url: string) => Promise<Response>,\n  url: string,\n  recordedSha256: string,\n  maxBytes: number = MAX_TARBALL_BYTES,\n): Promise<string | null> {\n  let response: Response\n  try {\n    response = await fetchTarball(url)\n  } catch (error) {\n    return `dsh-plugin-shop: could not download the release archive. Installation stopped. Network error: ${(error as Error).message}`\n  }\n  if (!response.ok) {\n    return `dsh-plugin-shop: could not download the release archive (HTTP ${response.status}). Installation stopped.`\n  }\n  if (response.body === null) {\n    return 'dsh-plugin-shop: the release archive response was empty or unreadable. Installation stopped.'\n  }\n  const hash = createHash('sha256')\n  let bytes = 0\n  const reader = response.body.getReader()\n  try {\n    for (;;) {\n      const { done, value } = await reader.read()\n      if (done) break\n      bytes += value.byteLength\n      if (bytes > maxBytes) {\n        try {\n          // Close the connection the cap was protecting; the bytes beyond\n          // the cap are never read.\n          await reader.cancel()\n        } catch {\n          // The stream already closed or errored; the cap verdict stands.\n        }\n        return `dsh-plugin-shop: the release archive exceeds the size limit (${maxBytes} bytes). Installation stopped.`\n      }\n      hash.update(value)\n    }\n  } catch (error) {\n    return `dsh-plugin-shop: the release archive download failed. Installation stopped. Error: ${(error as Error).message}`\n  }\n  if (hash.digest('hex') !== recordedSha256) {\n    return 'dsh-plugin-shop: the release archive does not match the catalog checksum (SHA-256). Installation stopped.'\n  }\n  return null\n}\n\n/** `shop/catalog` result (§7.3), plus the denied list for the install gate's UI. */\nexport interface ShopCatalogResult {\n  schemaVersion: number\n  builtAt: string\n  stale: boolean\n  plugins: CatalogEntry[]\n  denied: DeniedEntry[]\n  /** Names whose shop-like NAME must not hide them from the shelf\n   * (registry/not-a-shop.yml). Absent for a catalog built before the key. */\n  notAShop?: string[]\n  /** GitHub star counts by package name; {} when the pointer names no sidecar\n   * or the sidecar could not be fetched/verified (§5). */\n  stars: Record<string, number>\n  /** sha256 → data URL for the catalogue's icons; {} when the pointer names\n   * none or it could not be read (design 2026-10-23-shop-plugin-icons §7). */\n  icons: Record<string, string>\n  /** Install identity (`npm:<name>` / `github:<repo>#<subdir>`) → the declared\n   * peers node resolution cannot find from the profile. This is the HOST half\n   * of the verdict only: a module the browser's module table serves — a\n   * platform seed word such as `react` — has no package on disk and is still\n   * listed here, so the client removes every name its live module table\n   * provides before anything renders (`client/module-table.ts`), and renders\n   * no peer verdict at all on a page that offers no usable table. A key is\n   * absent when the plugin runs here or when no verdict could be formed;\n   * same-named entries stay independent. */\n  incompatible: Record<string, string[]>\n  /** Install identity → what the entry's author declared in\n   * `dsh.compatibility` that this installation does not meet (design\n   * 2026-09-01-harness-compatibility §8.2), and what the running dsh itself\n   * will refuse the install on (`peers`, from dsh 0.1.7; design\n   * 2026-09-26-dsh-017-readiness, B1). A key is absent when nothing was\n   * declared or every declared half is met, and dsh refuses nothing. A half that cannot be judged —\n   * the running version unreadable, a range semver cannot parse — is left out\n   * while the other is still judged, so an unknown never reads as an\n   * accusation; same-named entries stay independent. A process not started\n   * by dsh's CLI judges neither half: nothing then says which harness runs\n   * (`harness.ts`). */\n  incompatibleHarness: Record<string, HarnessVerdict>\n}\n\n/** An own-property read of a dependency map parsed from the profile manifest.\n * A bare index read answers for `Object.prototype`, and `constructor` is a\n * legal npm name (`[a-z0-9][a-z0-9._-]*`), so `dependencies['constructor']`\n * hands back a function for a package that is not installed. The\n * `spec === undefined` guard then passes, and `installedSpecMatches` returns\n * TRUE for an npm entry — `parseRepoSpec` coerces the function to a string\n * that matches no `github:` shorthand and answers `null`, which is exactly\n * what an npm entry expects. So the entry reads as installed when it is not.\n * `Object.hasOwn` is the same fix already applied at the two membership\n * checks above; these two sites need the VALUE, hence a helper. */\nfunction ownDependencySpec(\n  dependencies: Readonly<Record<string, string>>,\n  name: string,\n): string | undefined {\n  return Object.hasOwn(dependencies, name) ? dependencies[name] : undefined\n}\n\n/**\n * Package names whose module this PROCESS may already hold in Node's module\n * cache (design 2026-09-26-market-borrowings §1.2).\n *\n * A hot mount can only deliver code the process has not imported yet. The hot\n * tree imports through the loader's `internal.import`, which is Node's own ESM\n * loader and caches a module by its URL, and an install rewrites a package's\n * files at the URL it already had (`nodeLinker: hoisted`). Once a name is in\n * here, a mount of it would re-run the cached module under whatever version is\n * now on disk.\n *\n * Module scope rather than a gateway field, because the cache it models is the\n * process's: a gateway rebuilt inside a running dsh — a restarted shop fiber —\n * must not forget what the process imported before it existed. Every gateway\n * seeds it with the profile's dependencies at construction (the boot\n * composition) and extends it with every name the hot path mounts. It extends\n * it again with every name one of its own installs through dsh's\n * `pluginManager` brought to the enable stage, and with the profile's\n * dependencies whenever that service reports an install: dsh's own Plugins\n * page installs through it, and the report names no package. Nothing is ever\n * removed: an uninstall disposes the fiber, not the module record.\n */\nconst importedThisProcess = new Set<string>()\n\n/** Remote-only service exposing the shop Remote methods of §7.3.\n *\n * @typert service shop */\nexport class ShopGateway extends TypertRemoteService {\n  private readonly options: ShopGatewayOptions\n  /** The context this gateway was built with: the shop's own fiber. Inside an\n   * RPC method `this.ctx` is NOT that — cordis hands a service out with `ctx`\n   * rebound to the context that looked it up, so a call arriving over the\n   * wire sees the caller's, the typert gateway's (measured on 0.1.5-rc.3 and\n   * 0.1.7-rc.2). Anything whose PARENT matters is registered from here. The\n   * hot tree above all: registered from the gateway's context it was owned by\n   * the gateway's fiber rather than the shop's, was listed under the gateway's\n   * loader entry, and — the part a reader saw — sat where dsh's client\n   * registry never composed it, so a hot-installed browser half needed a\n   * restart that a reload now does (design 2026-09-26-dsh-017-readiness). */\n  private readonly home: Context\n  /** The profile dsh installs into; discovered from this module's own\n   * location when the caller does not supply one. */\n  private readonly profile: string\n  private readonly profileDir?: string\n  private readonly inventory?: ShopGatewayOptions['inventory']\n  private readonly hot?: ShopGatewayOptions['hot']\n  private readonly hotFs?: ShopGatewayOptions['hotFs']\n  private readonly loaderEntriesInjected?: ShopGatewayOptions['loaderEntries']\n  private readonly dshBin: string\n  /** The argv `shop/restart` re-spawns: the real process argv minus node and\n   * the CLI script path, or a test-provided substitute. */\n  private readonly restartArgv: string[]\n  /** The script the restart re-runs — this process's own entry. */\n  private readonly restartScript: string | undefined\n  /** The exit the restart calls once the response is out; `process.exit` in\n   * production, a spy in tests. */\n  private readonly exit: (code?: number) => void\n  private readonly restartExitDelayMs: number\n  private readonly restartParentPid: number\n  /** The restart this process committed, once it has: every later\n   * `shop/restart` answers with it. A page that lost the first answer to an\n   * HMR swap asks again (client/restart-monitor.ts), and inside the exit\n   * delay that ask reaches this same process. */\n  private committedRestart: ShopRestartResult | null = null\n  private readonly latestVersion: () => Promise<string | null>\n  private readonly pinFs: RepoPinFs\n  /** Favorites and rollback records (`state.ts`), read and written through\n   * this seam so tests never touch the real profile. */\n  private readonly stateFs: ShopStateFs\n  private readonly allowRestart?: boolean\n  private readonly env: NodeJS.ProcessEnv\n  /** The platform the restart gate reads, and the one the plugin-manager\n   * path quotes its retry line for; production defaults to process.platform.\n   * The two-phase handoff is POSIX-only (restart.ts). */\n  private readonly platform: NodeJS.Platform\n  /** The parent pid `detectSupervisor` inspects; production defaults to\n   * process.ppid (a systemd unit's main process has ppid 1). */\n  private readonly ppid: number\n  /** The release-tarball fetch for the install-time integrity check; global\n   * fetch in production, a fixture response in tests. */\n  private readonly fetchTarball: (url: string) => Promise<Response>\n  /** One pump for the whole gateway: batching is per profile and lives inside\n   * it, so a second instance would race the first for the same store. */\n  private readonly prefetcher: Prefetcher\n  /** What this process may already have imported (see `importedThisProcess`). */\n  private readonly imported: Set<string>\n  /** Routes the output dsh's `pluginManager` streams to the record whose\n   * request id it carries (see the constructor). */\n  private readonly managerLogs: ManagerLogs\n  /** The install gate runs against the last loaded snapshot, never a fresh\n   * fetch per request (§7.2: the Host's cached snapshot is the truth). */\n  /** Finished install records retained, so a poll sees the true terminal\n   * state (§8: done / activation / failure detail). Oldest evicted on add. */\n  private static readonly MAX_FINISHED_INSTALLS = 32\n\n  /** How long the gateway waits after a successful restart response before\n   * exiting the old process — the browser must receive the URL first. */\n  private static readonly RESTART_EXIT_DELAY_MS = 2000\n\n  /** The install gate runs against the last loaded snapshot, never a fresh\n   * fetch per request (§7.2: the Host's cached snapshot is the truth). */\n  private lastSnapshot: CatalogSnapshot | null = null\n  /** A cold-cache catalog load shared by concurrent RPC calls. */\n  private inFlightLoad: Promise<CatalogResult> | null = null\n  /** The origin list built for the last-seen `catalogUrl`, memoised so the\n   * user's npmrc is read at most once per gateway (see `originsFor`). */\n  private originCache: { catalogUrl: string; origins: CatalogOrigin[] } | null = null\n  /** The user's own `registry=` from `~/.npmrc`, read at most once per\n   * gateway. A wrapper distinguishes a genuine `null` from an unread value. */\n  private npmRegistryCache: { value: string | null } | null = null\n  /** The harness this process runs, read at most once per gateway: which dsh\n   * is running cannot change while it runs, and the read imports a module. A\n   * promise, so concurrent first calls share one read; `readRunningHarness`\n   * never rejects, so there is no failure to retry. */\n  private harnessRead: Promise<RunningHarness> | null = null\n  /** Install records, running and finished, from the CLI and from dsh's\n   * `pluginManager` alike; a poll finds one here or reports not found. */\n  private readonly installs = new Map<string, RunningInstall>()\n  /** Every install id in insertion order, oldest first; finished-record eviction walks this from the front. */\n  private readonly installOrder: string[] = []\n\n  constructor(ctx: Context, options: ShopGatewayOptions = {}) {\n    super(ctx, 'shop')\n    this.home = ctx\n    this.options = options\n    this.profile = options.profile ?? discoverProfile(fileURLToPath(import.meta.url), this.bootBaseDir()).name\n    this.profileDir = options.profileDir\n    this.inventory = options.inventory\n    this.hot = options.hot\n    this.hotFs = options.hotFs\n    this.loaderEntriesInjected = options.loaderEntries\n    this.dshBin = options.dshBin ?? 'dsh'\n    this.restartArgv = options.restartArgv ?? process.argv.slice(2)\n    this.restartScript = options.restartScript ?? process.argv[1]\n    this.exit = options.exit ?? ((code?: number) => process.exit(code))\n    this.restartExitDelayMs = options.restartExitDelayMs ?? ShopGateway.RESTART_EXIT_DELAY_MS\n    this.restartParentPid = options.restartParentPid ?? process.pid\n    this.latestVersion = options.fetchLatestVersion ?? (() => fetchLatestVersion(fetch, { registry: this.npmRegistry() }))\n    this.pinFs = options.pinFs ?? {\n      exists: path => existsSync(path),\n      read: path => readFileSync(path, 'utf8'),\n      write: (path, data) => {\n        mkdirSync(dirname(path), { recursive: true })\n        writeFileSync(path, data)\n      },\n    }\n    this.allowRestart = options.allowRestart\n    this.stateFs = options.stateFs ?? nodeShopStateFs\n    this.env = options.env ?? process.env\n    this.platform = options.platform ?? process.platform\n    this.ppid = options.ppid ?? process.ppid\n    this.fetchTarball = options.fetchTarball ?? ((url: string) => fetch(url))\n    this.prefetcher = options.prefetcher ?? createPrefetcher()\n    this.imported = options.importedModules ?? importedThisProcess\n    // What the profile holds as this gateway is built is what the boot\n    // composed: imported, as far as the process's module cache is concerned.\n    // An unreadable manifest seeds nothing — an update is still recognized\n    // from the manifest at install time, so what goes unrecognized then is an\n    // uninstall followed by a reinstall, and only until the next boot.\n    this.recordDependenciesImported()\n    this.managerLogs = new ManagerLogs()\n    // The service streams each pnpm run as it happens. A context without `on`\n    // (a unit test's stub) streams nothing, and a record then takes the\n    // service's final output instead.\n    const on = (this.ctx as { on?: (event: string, listener: (payload: unknown) => void) => unknown }).on\n    on?.call(this.ctx, 'plugin-manager/install-log', payload => {\n      const chunk = payload as { requestId?: unknown; text?: unknown; stream?: unknown } | null | undefined\n      this.managerLogs.chunk(chunk?.requestId, chunk?.text, chunk?.stream)\n    })\n    // dsh's own Plugins page installs through the same service, and the\n    // event dsh sends after every install names no package (measured on\n    // 0.1.7-rc.2). So the record is read again from the profile manifest,\n    // which now holds whatever dsh installed. Of the service's changes only\n    // an install adds a name to the manifest, so it is the only one read.\n    on?.call(this.ctx, 'plugin-manager/changed', payload => {\n      if ((payload as { reason?: unknown } | null | undefined)?.reason === 'install') this.recordDependenciesImported()\n    })\n    try {\n      // The ephemeral `hot-<n>.yml` inputs from a previous session must\n      // never survive a boot: a crashed session's stale inputs would mount\n      // against this session's composition.\n      cleanHotDir(this.profileDirResolved())\n    } catch {\n      // Swallows the profile-dir discovery failure: a profile dir that does\n      // not resolve yet (the stub-ctx test constructions) has nothing to\n      // wipe, and failing a boot over a missing wipe dir would be the worse\n      // failure.\n    }\n    // The harness self-check, at load and only here: the shop declares real\n    // peer ranges on harness packages and nothing enforces them — `dsh plugin\n    // add` does not, and the catalog's presence check answers a different\n    // question (does it resolve?) about OTHER plugins. A harness that moved\n    // under this build gets one line naming it, which is what an afternoon of\n    // diagnosing a silently changed plugin path cost.\n    this.checkPeerVersions()\n  }\n\n  /**\n   * Warn once, at load, about any declared peer the harness provides outside\n   * its declared range. Advisory by construction: it cannot throw, and it\n   * never refuses the load — losing the whole shop is a worse outcome than\n   * running against a harness that moved.\n   */\n  private checkPeerVersions(): void {\n    try {\n      createPeerVersionCheck({\n        ranges: this.options.peerRanges ?? ownPeerRanges(),\n        resolve: this.options.resolvePeerVersion ?? this.peerVersionResolver(this.profileAnchor()),\n        warn: message => {\n          const logger = (this.ctx as { logger?: { warn(message: string): void } }).logger\n          if (logger === undefined) console.warn(message)\n          else logger.warn(message)\n        },\n      })()\n    } catch {\n      // Swallows a missing profile anchor (a bare test construction resolves\n      // none) and an unreadable own manifest. Either way no verdict is\n      // formable, and silence is the documented answer for a fact we cannot\n      // read — never an accusation, and never a failed load.\n    }\n  }\n\n  /** The pins file lives in the shop's own cache, next to the catalog cache. */\n  private pinsPath(): string {\n    return join(this.rowConfig().cacheDir, 'github-pins.json')\n  }\n\n  /** The boot's Loader root directory (the active profile's `cordis.yml`\n   * directory, carried on `ctx.baseUrl`), when present. A `link:` install\n   * keeps this package at its source location, so the walk-up from\n   * `import.meta.url` finds the repo rather than a profile; `ctx.baseUrl`\n   * is the boot-provided authoritative answer. */\n  private bootBaseDir(): string | undefined {\n    const baseUrl = (this.ctx as { baseUrl?: unknown }).baseUrl\n    if (typeof baseUrl !== 'string' || !baseUrl.startsWith('file:')) return undefined\n    try {\n      return fileURLToPath(baseUrl)\n    } catch {\n      // A malformed baseUrl is not a profile answer; the walk-up decides.\n    }\n    return undefined\n  }\n\n  /** The profile directory the user layer lives in — the discovered default\n   * stays lazy so `setEnabled` works in tests via the `profileDir` option\n   * without requiring a real profile above this module. */\n  private profileDirResolved(): string {\n    if (this.profileDir !== undefined) return this.profileDir\n    return discoverProfile(fileURLToPath(import.meta.url), this.bootBaseDir()).dir\n  }\n\n  /** Where every \"what can this installation's plugins import?\" question\n   * resolves from: the profile's own Loader root, which is where the harness\n   * resolves plugins from. One definition for the peer presence check and the\n   * load-time self-check, so neither can drift onto a different notion of\n   * \"the installation\". NOT where the running harness is read from: a copy\n   * of `@deepseek-ai/dsh` a plugin's dependencies hoist into the profile is\n   * importable from here and is not what runs (`harness.ts`). Throws when no\n   * profile directory can be discovered and none is given. */\n  private profileAnchor(profileDir: string = this.profileDirResolved()): string {\n    return pathToFileURL(join(profileDir, 'cordis.yml')).href\n  }\n\n  /** dsh's `pluginPackages` service, when the running harness provides one\n   * (0.1.7 and later), else null. Read on each use, like `pluginInventory`.\n   * It is how such a harness serves its own packages to plugins, which no\n   * walk of the profile's disk can see (design\n   * 2026-09-01-harness-compatibility §11). */\n  private harnessPackages(): HarnessPackageLookup | null {\n    const service = (this.ctx as { get?: (name: string) => unknown }).get?.('pluginPackages')\n    return typeof (service as { packageOf?: unknown } | null | undefined)?.packageOf === 'function'\n      ? service as HarnessPackageLookup\n      : null\n  }\n\n  /** dsh's `pluginManager` service, when the running harness provides all of\n   * it (0.1.7 and later), else null. Never cached across calls, like\n   * `pluginPackages`, but read once per RPC, at its start, and passed down:\n   * read again after an await, a service disposed in between would let a\n   * desktop mutation past the desktop gate and onto the CLI path, which dsh\n   * refuses for that profile. Design 2026-09-26-plugin-manager-delegation,\n   * section 3.1. */\n  private pluginManager(): PluginManagerLike | null {\n    return asPluginManager((this.ctx as { get?: (name: string) => unknown }).get?.('pluginManager'))\n  }\n\n  /** Whether the running harness's profile reconcile replaces a running\n   * plugin whose files changed on disk: dsh-hmr 0.2.1's `reconcileProfile`,\n   * absent on 0.1.7 and 0.2.0 (whose hmr has only\n   * `reconcileProfilePatches`) and on 0.1.5 (no hmr service). Read for what\n   * `managerOutcome` makes of an `applied` answer on a name this process\n   * imported (design 2026-10-19-dsh-021-readiness §2). A harness that offers\n   * no service, or one without the method, answers false and keeps the\n   * restart. */\n  private reconcilesRunningPlugins(): boolean {\n    const service = (this.ctx as { get?: (name: string) => unknown }).get?.('hmr')\n    return typeof (service as { reconcileProfile?: unknown } | null | undefined)?.reconcileProfile === 'function'\n  }\n\n  /** \"Does this installation provide `spec`?\", asked from `anchor`: the\n   * harness's own resolution in front of the walk where the harness has one,\n   * the walk alone where it has not. */\n  private peerResolver(anchor: string): PeerResolver {\n    const walk = nodeResolver(anchor)\n    const packages = this.harnessPackages()\n    return packages === null ? walk : harnessPackageResolver(walk, packages, anchor)\n  }\n\n  /** `peerResolver`'s twin for the versions the load-time self-check reads. */\n  private peerVersionResolver(anchor: string): PeerVersionResolver {\n    const walk = nodeVersionResolver(anchor)\n    const packages = this.harnessPackages()\n    return packages === null ? walk : harnessPackageVersionResolver(walk, packages, anchor)\n  }\n\n  /** `profileDirResolved`, or null when no profile directory can be\n   * discovered — for the reads that answer \"cannot tell\" rather than fail. */\n  private profileDirOrNone(): string | null {\n    try {\n      return this.profileDirResolved()\n    } catch {\n      // Swallows the discovery failure: no profile above this module and none\n      // on the boot's baseUrl (the bare test constructions). Every caller\n      // reads null as \"no verdict needing the profile can be formed\".\n      return null\n    }\n  }\n\n  /** The harness this process runs, read once (see `harnessRead`). */\n  private runningHarness(): Promise<RunningHarness> {\n    this.harnessRead ??= this.options.readHarness === undefined\n      ? readRunningHarness(this.restartScript, this.harnessLocator())\n      : this.options.readHarness(this.restartScript)\n    return this.harnessRead\n  }\n\n  /** Where to ask for the running dsh when the script this process started\n   * with does not name it: the desktop app boots the profile through\n   * `@deepseek-ai/dsh-desktop-host`, whose entry owns no dsh, so\n   * `process.argv[1]` names the host rather than the harness. dsh serves its\n   * own packages through `pluginPackages` (0.1.7 on), and the profile's\n   * `cordis.yml` is the anchor the peer resolver already walks from, so the\n   * service answers with this installation's dsh (design\n   * 2026-09-01-harness-compatibility, 2026-11-06 amendment). Null when the\n   * harness offers no such service (0.1.5) or no profile was found — the\n   * script read alone then decides, as before. */\n  private harnessLocator(): HarnessLocator | undefined {\n    const packages = this.harnessPackages()\n    if (packages === null) return undefined\n    const profileDir = this.profileDirOrNone()\n    if (profileDir === null) return undefined\n    return { packages, parentURL: this.profileAnchor(profileDir) }\n  }\n\n  /** The inventory, through the wire remote: an envelope `{ ok, value }` or\n   * `{ ok: false, error }`. Each row is re-validated before trust (same\n   * discipline as the rowConfig cast). */\n  private async listInventory(): Promise<InventoryEntry[]> {\n    const remote = this.inventory ?? (this.ctx as { get?: (name: string) => unknown }).get?.('pluginInventory') as\n      | { list(): Promise<unknown> }\n      | undefined\n    if (remote === undefined) throw new Error('dsh-plugin-shop: pluginInventory service is not mounted')\n    const result = await remote.list()\n    // The host-side service returns the BARE snapshot `{ entries: [...] }` —\n    // no wire envelope (that exists only on the remote's client side).\n    const list = Array.isArray(result) ? result : (result as { entries?: unknown }).entries\n    if (!Array.isArray(list)) return []\n    const entries: InventoryEntry[] = []\n    for (const item of list) {\n      if (item !== null && typeof item === 'object'\n        && typeof (item as { entryId?: unknown }).entryId === 'string'\n        && typeof (item as { moduleName?: unknown }).moduleName === 'string'\n        && typeof (item as { enabled?: unknown }).enabled === 'boolean') {\n        entries.push(item as InventoryEntry)\n      }\n    }\n    return entries\n  }\n\n  /** The Loader's boot-layer entries; a harness without the loader answers\n   * with an empty list (there is then nothing to live-disable). */\n  private loaderEntries(): Array<LoaderEntryLike> {\n    if (this.loaderEntriesInjected !== undefined) return this.loaderEntriesInjected()\n    const loader = (this.ctx as unknown as { loader?: { entries(): Iterable<LoaderEntryLike> } }).loader\n    return loader === undefined ? [] : [...loader.entries()]\n  }\n\n  /** Live-disable one boot-layer entry, retrying until its fiber is actually\n   * down. A disable can land while the entry's init is still in flight: the\n   * options flip but the finishing init brings the fiber up anyway, and a\n   * plain re-update no-ops on the empty diff (dsh-market themes.ts:74-93).\n   * The uninstall path is the one caller: an update used to swap its running\n   * instance for a hot mount through here, and no longer mounts at all\n   * (design 2026-09-26-market-borrowings §1). */\n  /** The package's owned entry ids, or none when its bundle patch cannot be\n   * read. For the paths where a live disable is an optimization and the\n   * operation must succeed regardless; `setEnabled` reports the failure\n   * instead, because there the patch IS the answer being asked for. */\n  /**\n   * The profile manifest's dependencies, or undefined when it cannot be read.\n   *\n   * `readProfileManifest` throws on an unreadable file and lets `JSON.parse`\n   * throw on a malformed one, and `profileDirResolved` can throw out of\n   * `discoverProfile`. An escaped exception crosses the RPC as a bare\n   * transport failure and the client can only render \"please retry\" (the same\n   * hazard `setEnabled` catches), so a profile caught mid-write would turn\n   * every published rejection detail on the install path — denied,\n   * not-in-catalog, version-mismatch — into that one line.\n   *\n   * Undefined is \"cannot say\", which the caller must not read as \"nothing is\n   * installed\": it means the install proceeds ungated rather than being\n   * refused over a read that did not happen.\n   */\n  private profileDependenciesOrNone(): Record<string, string> | undefined {\n    try {\n      return readProfileManifest('dsh-plugin-shop', this.profileDirResolved()).dependencies ?? {}\n    } catch {\n      return undefined\n    }\n  }\n\n  /**\n   * The profile manifest's spec for one name, or undefined when the manifest\n   * holds no such name — or could not be read at all.\n   *\n   * Through `ownDependencySpec` for the reason spelled out there: a bare index\n   * read answers for `Object.prototype`, and `constructor` is a legal npm\n   * name. The cost on this path is behavioural twice over — the gate would\n   * weigh a function as the installed spec, and a phantom `isUpdate` would\n   * refuse a hot mount to a package this process never imported.\n   */\n  private installedSpecOf(name: string): string | undefined {\n    const dependencies = this.profileDependenciesOrNone()\n    return dependencies === undefined ? undefined : ownDependencySpec(dependencies, name)\n  }\n\n  /** Add every dependency the profile manifest holds to the `imported`\n   * record (see `importedThisProcess`): each is a package dsh's loader may\n   * have loaded in this process, at boot or by an install since. An\n   * unreadable manifest adds nothing. */\n  private recordDependenciesImported(): void {\n    for (const name of Object.keys(this.profileDependenciesOrNone() ?? {})) this.imported.add(name)\n  }\n\n  private ownedEntryIdsOrNone(packageName: string): string[] {\n    try {\n      return ownedEntryIds({ profileDir: this.profileDirResolved(), packageName })\n    } catch {\n      // Unreadable patch: no ids, so nothing gets disabled live. Read by\n      // `liveEntriesDown` as \"no live entry of this package\", the same as a\n      // package with no rows — the removal still stands at the next boot,\n      // and there is nothing this process can name to bring down.\n      return []\n    }\n  }\n\n  /** Whether an installed package declares `dsh.client`. Reads through the\n   * `hotFs` option — `HotFs` is `hot.ts`'s type, but this gateway forwards\n   * the option only HERE, never into `hotMount`, which takes its own `fs`\n   * from `HotDeps`. A fixture therefore drives this read alone, which is the\n   * point: it is the only way to state what a package declared BEFORE an\n   * update overwrote its manifest. */\n  private packageHasClientHalf(packageName: string): boolean {\n    return hasClientHalf(this.hotFs ?? nodeHotFs, this.profileDirResolved(), packageName)\n  }\n\n  /**\n   * Bring every live entry the package owns down, best effort, and report\n   * whether its host half is DOWN when this returns.\n   *\n   * \"Nothing matched\" is down: a package with no live entry is not running,\n   * which is the ordinary case for removing a plugin that never loaded this\n   * session. Only a matched entry whose fiber outlives the retries — or\n   * whose `update` throws — leaves the plugin UP, and that is the one case\n   * an uninstall must not describe as stopped.\n   *\n   * The old spelling answered \"did any update succeed\", which is a different\n   * question: `update` resolving says the row was accepted, not that the\n   * instance went away. The retry loop below exists precisely because those\n   * two come apart, so reading the first as the second threw away the answer\n   * the loop was computing.\n   */\n  private async liveEntriesDown(ids: readonly string[]): Promise<boolean> {\n    if (ids.length === 0) return true\n    const owned = new Set(ids)\n    let allDown = true\n    for (const entry of this.loaderEntries()) {\n      // Matched on the entry id, never the module name: a package's entry\n      // may mount another package's module entirely (see ownedEntryIds), and\n      // the name match silently found nothing for every such package.\n      if (entry.id === undefined || !ownsEntryId(owned, entry.id)) continue\n      let down = false\n      for (let attempt = 0; attempt < 3; attempt++) {\n        try {\n          await entry.update({ disabled: true }, false, true)\n        } catch {\n          // A failing update leaves the entry running — best-effort\n          // live-disable, and the caller reports the honest outcome.\n          break\n        }\n        if (entry.fiber === undefined) {\n          down = true\n          break\n        }\n        await new Promise(resolve => setTimeout(resolve, 200))\n      }\n      if (!down) allDown = false\n    }\n    return allDown\n  }\n\n  /** Enable or disable one installed plugin, hot (§8): the write sets the\n   * `disabled` key of each owned entry's row in the user layer and changes\n   * nothing else there (design 2026-09-26-market-borrowings §2) — the CLI's\n   * watchUserPatches applies it through HMR. The shop's own row and the\n   * framework's bundles are never toggleable: disabling the host chain would\n   * break HMR itself. */\n  @Remote('setEnabled')\n  async setEnabled(args: { name: string; enabled: boolean }): Promise<ShopSetEnabledResult> {\n    if (args.name === 'dsh-plugin-shop' || args.name.startsWith('@deepseek-ai/')) {\n      return { ok: false, detail: `dsh-plugin-shop: ${args.name} is part of dsh itself and cannot be enabled or disabled from the shop.` }\n    }\n    // Read once, and passed to the deselected branch (see `pluginManager`).\n    const manager = this.pluginManager()\n    const profileDir = this.profileDirResolved()\n    // Installed-ness is the profile manifest's dependencies — the same truth\n    // `installed()` renders the row from. Reading it from a different source\n    // than the list the user clicked is what let the shop show a toggle and\n    // then deny the package existed.\n    const manifest = readProfileManifest('dsh-plugin-shop', profileDir)\n    if (!Object.hasOwn(manifest.dependencies ?? {}, args.name)) {\n      return { ok: false, detail: `dsh-plugin-shop: ${args.name} is not installed` }\n    }\n    // A malformed or unreadable bundle patch must reach the person as a\n    // reason, not as a throw: an escaped exception crosses the RPC as a bare\n    // transport failure, and the client can only render \"please retry\" for it\n    // — the one rejection on this path with no author-readable detail.\n    let owned: OwnedEntry[]\n    try {\n      owned = ownedEntries({ profileDir, packageName: args.name })\n    } catch (error) {\n      return { ok: false, detail: `dsh-plugin-shop: could not read the plugin configuration for ${args.name}: ${String(error)}` }\n    }\n    if (owned.length === 0) {\n      return { ok: false, detail: `dsh-plugin-shop: ${args.name} has no plugin entries to enable or disable.` }\n    }\n    // A bundle the profile does not select is composed by no restart. dsh\n    // 0.1.7's Plugins page deselects one with its bundle switch and keeps the\n    // package installed; nothing of it is then live, and the live-entry check\n    // below would advise the restart that cannot help.\n    const selected = this.runningProfileBundles(profileDir)\n    if (selected !== null && !selected.includes(args.name)) {\n      return this.setDeselectedEnabled(args.name, args.enabled, profileDir, owned, manager)\n    }\n    const ownedSet = new Set(owned.map(entry => entry.id))\n    // Liveness is read from the LIVE ids, which carry the namespace of every\n    // tree composed above the entry (see ownsEntryId).\n    const live = (await this.listInventory()).filter(entry => ownsEntryId(ownedSet, entry.entryId))\n    if (live.length === 0) {\n      return { ok: false, detail: `dsh-plugin-shop: ${args.name} is installed but has not been loaded. Restart dsh to load it.` }\n    }\n    // dsh 0.1.7+: switch every live entry through the service, by its LIVE\n    // id, the same row the writer below would touch, applied in place\n    // (measured 2026-09-27 on 0.1.7-rc.2). The loop is sequential and there\n    // is no rollback: a failure partway through says how many entries had\n    // already switched, because this path never reaches the writer's own row\n    // write and nothing else would report it.\n    if (manager !== null) {\n      if (this.hasRunningCommand()) return { ok: false, detail: switchWhileBusyDetail(args.name) }\n      let restart = false\n      let switched = 0\n      // A failure partway through says how many entries had already switched\n      // (R21), whatever failed: a refusal, an override or a throw. The\n      // failure's own sentence is ended first, since a thrown message\n      // carries no period of its own.\n      const failed = (detail: string): ShopSetEnabledResult => {\n        if (switched === 0) return { ok: false, detail }\n        const sentence = /[.!?]$/.test(detail) ? detail : `${detail}.`\n        return { ok: false, detail: `${sentence} ${switched} of its ${live.length} plugins had already switched ${args.enabled ? 'on' : 'off'}.` }\n      }\n      for (const entry of live) {\n        let raw: unknown\n        try {\n          raw = await manager.setPluginEnabled(entry.entryId, args.enabled)\n        } catch (error) {\n          // The service threw rather than answering: nothing says the entry\n          // switched, and the reason travels as a detail, not as a transport\n          // failure the client can only call \"retry\".\n          return failed(`dsh-plugin-shop: dsh could not switch ${args.name}${thrownTail(messageOf(error), isDesktopProfile(this.profile))}`)\n        }\n        const { change, failure } = this.readManagerAnswer(raw, {\n          act: `switch ${args.name}`, request: `the switch for ${args.name}`, stays: args.enabled ? 'off' : 'on',\n        })\n        if (failure !== null) return failed(failure)\n        switched += 1\n        if (change.application === 'restart-required') restart = true\n      }\n      if (restart) return { ok: true, activation: 'restart' }\n      return { ok: true, activation: activationOf({ hostLive: true, clientLive: true, hasClientHalf: this.packageHasClientHalf(args.name) }) }\n    }\n    // The row names the CONFIG id — the id the package's own patch inserted —\n    // never the live id it was found by. The user layer is applied by the\n    // harness's applyEntryPatches, which looks each row's id up among the ids\n    // the bundle patches declared: a row spelled `include:foo` matches nothing\n    // there and disables nothing, and a hot `mkt-foo` row would be lost for\n    // good, because the restart composes that plugin under its bare id.\n    //\n    // Every entry the package owns toggles together: a package that inserts a\n    // host row and a client row is one plugin to the person clicking. Each\n    // row carries the module its entry mounts, which is what lets the write\n    // land on a row the user named rather than beside it.\n    setUserLayerRows({\n      profileDir,\n      rows: owned.map(({ id, name }) => ({ id, disabled: !args.enabled, ...(name !== undefined ? { name } : {}) })),\n    })\n    // The user layer is hot-reloaded by the harness, so the host half is\n    // already in its new state; a package with a browser half still needs\n    // the open tab to reload (design 2026-09-11-activation-model §3).\n    // `clientLive: true` — a toggle moves a row the client registry already\n    // enumerates, and the served graph follows it (§2, measured 2026-09-11).\n    return { ok: true, activation: activationOf({ hostLive: true, clientLive: true, hasClientHalf: this.packageHasClientHalf(args.name) }) }\n  }\n\n  /**\n   * `setEnabled` for an installed package whose bundle the profile does not\n   * select.\n   *\n   * Switching it off writes the plugin-level rows and nothing else: none of\n   * it runs, and the rows keep it off if dsh selects the bundle again.\n   * Switching it on selects the bundle through dsh's own `pluginManager`, the\n   * writer behind the switch that deselected it, and then clears the\n   * plugin-level rows as an ordinary enable does. A harness without that\n   * service gets the way back in words instead. `dsh plugin add <name>` is\n   * not printed: it selects the bundle again only on 0.1.5, and it lets pnpm\n   * float a registry package to `latest`.\n   */\n  private async setDeselectedEnabled(\n    name: string,\n    enabled: boolean,\n    profileDir: string,\n    owned: readonly OwnedEntry[],\n    manager: PluginManagerLike | null,\n  ): Promise<ShopSetEnabledResult> {\n    const rows = owned.map(({ id, name: moduleName }) => ({ id, disabled: !enabled, ...(moduleName !== undefined ? { name: moduleName } : {}) }))\n    if (!enabled) {\n      setUserLayerRows({ profileDir, rows })\n      return { ok: true, activation: 'live' }\n    }\n    if (manager === null) {\n      return {\n        ok: false,\n        detail: `dsh-plugin-shop: ${name} is installed but disabled. It is missing from dsh.profile.bundles in`\n          + ` ${join(profileDir, 'package.json')}, so restarting alone will not enable it.`\n          + ` This version of dsh cannot enable the bundle from the shop. Add \"${name}\" back to that list and restart dsh,`\n          + ' or uninstall it and install it again from the shop.',\n      }\n    }\n    if (this.hasRunningCommand()) return { ok: false, detail: switchWhileBusyDetail(name) }\n    let raw: unknown\n    try {\n      raw = await manager.setBundleEnabled(name, true)\n    } catch (error) {\n      // The service threw rather than answering: nothing says the bundle was\n      // selected, so the switch stays off and the reason travels as a detail\n      // rather than as a transport failure the client can only call \"retry\".\n      return { ok: false, detail: `dsh-plugin-shop: dsh could not enable ${name} again${thrownTail(messageOf(error), isDesktopProfile(this.profile))}` }\n    }\n    const { change, failure } = this.readManagerAnswer(raw, { act: `select ${name} again`, request: `the selection of ${name}`, stays: 'off' })\n    if (failure !== null) return { ok: false, detail: failure }\n    setUserLayerRows({ profileDir, rows })\n    if (change.application === 'restart-required') return { ok: true, activation: 'restart' }\n    return { ok: true, activation: activationOf({ hostLive: true, clientLive: true, hasClientHalf: this.packageHasClientHalf(name) }) }\n  }\n\n  /**\n   * dsh's answer to a switch or a bundle selection, read the one way both\n   * callers need it (R32): the change, scrubbed for a desktop reader, and the\n   * detail that fails the request, or null when dsh applied it. `act` is what\n   * was asked, as \"switch <name>\", `request` names the request itself, as\n   * \"the switch for <name>\", and `stays` is the state the plugin keeps when\n   * the request does not take effect. An application this shop does not know\n   * fails rather than reading as applied: a later harness may answer\n   * something new.\n   *\n   * `overridden` fails too (R39). dsh answers it when, after it wrote the row\n   * and reloaded, the live entry still differs from the request\n   * (dsh-plugin-manager 0.1.7-rc.2, setPluginEnabled), and its README names\n   * what outranks the profile's own patch: home and invocation patches keep\n   * their higher priority. The change is saved and the plugin runs as it\n   * did, so a success would flip the client's switch over a plugin that did\n   * not change, and that switch never re-reads the live state.\n   * setBundleEnabled never answers it; a selection reads it the same way.\n   */\n  private readManagerAnswer(raw: unknown, words: { act: string; request: string; stays: 'on' | 'off' }): { change: ManagerChange; failure: string | null } {\n    const change = isDesktopProfile(this.profile) ? forDesktopReader(readChange(raw)) : readChange(raw)\n    if (change.application === 'failed' || change.application === 'cancelled' || change.errorCode !== null) {\n      const code = change.errorCode ?? change.application ?? 'failed'\n      // `operation-error` is what dsh codes any error that is not one of its\n      // refusals (managementError), so it reads \"could not\", not \"refused\".\n      const verb = code === 'operation-error' ? 'could not' : 'refused to'\n      return { change, failure: `dsh-plugin-shop: dsh ${verb} ${words.act} (${code})${codeReason(change, code)}` }\n    }\n    if (change.application === 'overridden') {\n      return {\n        change,\n        failure: `dsh-plugin-shop: dsh saved ${words.request}, but a home or startup configuration overrides it. The plugin remains ${words.stays}.`,\n      }\n    }\n    if (change.application === 'applied' || change.application === 'restart-required') {\n      return { change, failure: null }\n    }\n    return {\n      change,\n      failure: `dsh-plugin-shop: could not confirm ${words.request}. dsh returned an unrecognized status: \"${change.application ?? 'nothing'}\".`,\n    }\n  }\n\n  private rowConfig(): { catalogUrl: string; cacheDir: string } {\n    if (this.options.catalogUrl !== undefined && this.options.cacheDir !== undefined) {\n      return { catalogUrl: this.options.catalogUrl, cacheDir: this.options.cacheDir }\n    }\n    // Structural cast instead of the cordis-plugin-loader Context augmentation:\n    // the shop must not depend on that package. The augmentation reaches\n    // this package's typecheck through dsh-app-boot's include types, so the\n    // cast goes through `unknown`. The loader's own type of `config` is\n    // `unknown`, so the row's shape is re-validated below before it is trusted.\n    const loader = (this.ctx as unknown as {\n      loader?: { entries(): Array<{ options: { name?: string; config?: unknown } }> }\n    }).loader\n    const entry = loader?.entries().find(entry => entry.options.name === 'dsh-plugin-shop')\n    const config = entry?.options.config as ShopRowConfig | undefined\n    const catalogUrl = config?.catalogUrl\n    const cacheDir = config?.cacheDir\n    if (typeof catalogUrl !== 'string' || typeof cacheDir !== 'string') {\n      throw new Error('dsh-plugin-shop: the shop row is missing catalogUrl or cacheDir config')\n    }\n    return { catalogUrl, cacheDir }\n  }\n\n  /** The user's own registry, read once. The self-update check and catalog\n   * race share this preference so neither path repeatedly touches ~/.npmrc. */\n  private npmRegistry(): string | null {\n    const cached = this.npmRegistryCache\n    if (cached !== null) return cached.value\n    const value = npmrcRegistry(path => {\n      try {\n        return readFileSync(path, 'utf8')\n      } catch {\n        // No user npmrc, or unreadable: the defaults are raced instead. This\n        // is a preference, never a requirement.\n        return null\n      }\n    }, homedir())\n    this.npmRegistryCache = { value }\n    return value\n  }\n\n  /** The origins to race for this row's catalog. Read once per gateway: the\n   * user's npmrc does not change under a running dsh, and re-reading it on\n   * every catalog call would put a filesystem read on the hot path. */\n  private originsFor(catalogUrl: string): CatalogOrigin[] {\n    if (this.originCache?.catalogUrl === catalogUrl) return this.originCache.origins\n    const origins = catalogOrigins(catalogUrl, fetch, this.npmRegistry())\n    this.originCache = { catalogUrl, origins }\n    return origins\n  }\n\n  /** Join an in-flight load; refresh requests always start a new load. */\n  private loadCatalogOnce(refresh: boolean): Promise<CatalogResult> {\n    const existing = this.inFlightLoad\n    if (!refresh && existing !== null) return existing\n    const { catalogUrl, cacheDir } = this.rowConfig()\n    const load = this.options.loadCatalog ?? loadCatalog\n    const started = load({ origins: this.originsFor(catalogUrl), cacheDir, refresh })\n      .then(result => {\n        this.lastSnapshot = result.snapshot\n        return result\n      })\n    this.inFlightLoad = started\n    const forget = (): void => {\n      if (this.inFlightLoad === started) this.inFlightLoad = null\n    }\n    started.then(forget, forget)\n    return started\n  }\n\n  /** Return the current snapshot, loading it once when needed. */\n  private async snapshotNow(): Promise<CatalogSnapshot> {\n    if (this.lastSnapshot !== null) return this.lastSnapshot\n    const { snapshot } = await this.loadCatalogOnce(false)\n    return snapshot\n  }\n\n  /** The explicit restart override. Only the row's `config:` sub-object is\n   * passed to a plugin — a top-level `allowRestart:` beside `name:` would be\n   * silently ignored by the loader (dsh-market README, #227). */\n  /** Whether the two-phase handoff can run at all here. `restart.ts` drives\n   * it through `sh`, `kill -0` and `sleep`, none of which Windows has. */\n  private restartPlatformSupported(): boolean {\n    return this.platform !== 'win32'\n  }\n\n  /** Why a restart would be refused for this process, or null when nothing\n   * static does. One ordered list, read by `restart()` before it commits and\n   * by `version()` so the client can say the same thing up front.\n   *\n   * The order is load-bearing for the copy a reader sees. The desktop\n   * profile first: dsh itself refuses to launch it, so no platform,\n   * supervisor or port could make a restart possible there, and the remedy\n   * is the app. Then `from-default-profile` and Windows, both ahead of\n   * systemd, because neither has an override and reporting the systemd one\n   * there sends the reader to set `allowRestart: true`, which this gate would\n   * still refuse. And `from-default-profile` ahead of Windows, because every\n   * remedy after `desktop` is \"restart dsh manually\", which a reader launched\n   * with the flag would do with the flag, and on 0.2.1 that recreates the\n   * profile: its copy is the one that says \"without that flag\", and a\n   * Windows, systemd or `--port 0` reader needs it as much as any other.\n   *\n   * - `desktop`: dsh's CLI refuses `--profile desktop` (\"managed exclusively\n   *   by the Electron application\"), so the relaunch would exit at once and\n   *   leave nothing on the port; the app restarts it.\n   * - `from-default-profile`: from dsh 0.2.1, `--from-default-profile <name>`\n   *   replaces an existing custom profile with a fresh copy of the shipped\n   *   template on every launch, and the relaunch re-runs this argv verbatim,\n   *   so it would delete every plugin in the profile, this shop included.\n   *   Measured 2026-10-19 in throwaway homes: 0.2.1-rc.2 booted a relaunched\n   *   profile that had held the shop with no dependencies, while 0.2.0-rc.2\n   *   refused to boot an existing profile at all, so there the restarted dsh\n   *   failed to come back. Both spellings are the flag:\n   *   `--from-default-profile <name>` and `--from-default-profile=<name>`. It\n   *   is left in the argv rather than stripped: the restarted process would no\n   *   longer run the command the reader chose, and their next launch with the\n   *   flag recreates the profile anyway. No override (design\n   *   2026-10-19-dsh-021-readiness §3).\n   * - `windows`: the handoff helper is a POSIX shell one-liner (restart.ts)\n   *   and there is no `sh` on Windows. That spawn fails ASYNCHRONOUSLY, so\n   *   committing would answer `ok: true`, exit this process, and leave nothing\n   *   to take the port — dsh would simply be gone.\n   * - `systemd`: under a unit the two-phase handoff kills itself, because the\n   *   main process exiting also kills the unit's cgroup and takes the detached\n   *   helper with it; the service never comes back. Overridable, and the only\n   *   one that is.\n   * - `port-zero`: the OS hands the NEW process a fresh port the browser\n   *   cannot know, so a restart would strand the client on a dead origin. */\n  private staticRestartBlock(): RestartBlockedReason | null {\n    if (isDesktopProfile(this.profile)) return 'desktop'\n    if (this.restartArgv.some(arg => arg === '--from-default-profile' || arg.startsWith('--from-default-profile='))) return 'from-default-profile'\n    if (!this.restartPlatformSupported()) return 'windows'\n    if (detectSupervisor(this.env, { ppid: this.ppid }) === 'systemd' && !this.allowRestartConfigured()) return 'systemd'\n    const portIndex = this.restartArgv.indexOf('--port')\n    if (portIndex !== -1 && this.restartArgv[portIndex + 1] === '0') return 'port-zero'\n    return null\n  }\n\n  private allowRestartConfigured(): boolean {\n    if (this.allowRestart !== undefined) return this.allowRestart\n    const loader = (this.ctx as unknown as {\n      loader?: { entries(): Array<{ options: { name?: string; config?: unknown } }> }\n    }).loader\n    const entry = loader?.entries().find(entry => entry.options.name === 'dsh-plugin-shop')\n    const config = entry?.options.config as ShopRowConfig | undefined\n    return config?.allowRestart === true\n  }\n\n  /** Browse the catalog (§7.3): cached snapshot, refreshed on demand. */\n  @Remote('catalog')\n  async catalog(args?: { refresh?: boolean }): Promise<ShopCatalogResult> {\n    const { snapshot, stale } = await this.loadCatalogOnce(args?.refresh ?? false)\n    // Both verdicts are judged on every call and never remembered against the\n    // snapshot. The snapshot records what each entry DECLARES; what this\n    // installation provides is not in it, and moves under it — installing a\n    // missing peer from the shop is exactly the event that must clear its\n    // badge, and a map kept per snapshot would go on naming that peer for as\n    // long as the snapshot is served. Asking every time is cheap; design\n    // 2026-09-01-harness-compatibility §9.6 owns the measurement. The one\n    // input kept is the running harness — which dsh this process is, its\n    // template table and its peer check — because a running process cannot\n    // change it.\n    const harness = await this.runningHarness()\n    // The profile directory, looked up ONCE: the peer resolver's anchor and\n    // the profile half's bundles are read from the same directory, so the two\n    // verdicts cannot describe two different profiles. None discovered (a\n    // bare construction that supplies neither `profileDir` nor a module\n    // location under a profile) means no verdict that needs one.\n    const profileDir = this.profileDirOrNone()\n    let incompatible: Record<string, string[]> = {}\n    if (profileDir !== null) {\n      try {\n        const resolve = this.options.resolvePeer ?? this.peerResolver(this.profileAnchor(profileDir))\n        incompatible = incompatibilityMap(snapshot.entries, resolve)\n      } catch {\n        // Swallows anything incompatibilityMap throws on an entry shape this\n        // build did not expect — `peers: 5`, say, which is not iterable, and\n        // which the catalog's zod parse refuses, so only an injected snapshot\n        // can carry it. A plugin we cannot judge is never accused, so the\n        // whole map degrades to empty rather than one entry costing every\n        // reader the catalog. A resolver's own throws never reach here:\n        // incompatibilityMap turns those into no verdict for the entry.\n        incompatible = {}\n      }\n    }\n    let incompatibleHarness: Record<string, HarnessVerdict>\n    try {\n      incompatibleHarness = compatibilityMap(snapshot.entries, {\n        dshVersion: harness.dshVersion,\n        profile: { name: this.profile, bundles: profileDir === null ? null : this.runningProfileBundles(profileDir) },\n      }, harness.templates)\n    } catch {\n      // Swallows anything compatibilityMap throws on a declaration this build\n      // did not expect — `profiles: 5`, say, which has no `includes`, and\n      // which the catalog's zod parse refuses, so only an injected snapshot\n      // can carry it. The rule is the peer map's: a declaration nobody can\n      // judge is never an accusation, and this call answers for the whole\n      // shelf, so one entry must not reject it. It did: before the template\n      // table lost its prototype, one entry declaring\n      // `profiles: [\"constructor\"]` made every catalog() call reject, for\n      // every user. The whole map degrades to empty; the peer map above\n      // stands.\n      incompatibleHarness = {}\n    }\n    for (const [key, peers] of Object.entries(this.refusedByHarness(snapshot.entries, harness, profileDir))) {\n      incompatibleHarness[key] = { ...incompatibleHarness[key], peers }\n    }\n    return {\n      schemaVersion: snapshot.schemaVersion,\n      builtAt: snapshot.builtAt,\n      stale,\n      plugins: snapshot.entries,\n      denied: snapshot.denied,\n      notAShop: snapshot.notAShop ?? [],\n      stars: snapshot.stars,\n      icons: snapshot.icons ?? {},\n      incompatible,\n      incompatibleHarness,\n    }\n  }\n\n  /**\n   * The installs the running dsh will refuse on their harness peers\n   * (`peerVerdictsOf`), judged against the exemptions this profile holds —\n   * read on every call like the other verdicts, because recording one is\n   * exactly the event that must clear a card: the reader runs the command\n   * the card shows, presses Refresh, and the install is allowed. Empty when\n   * the running dsh has no such check (before 0.1.7) or no profile was\n   * found, and when either read throws: a refusal nobody could establish is\n   * never shown, least of all as a disabled button.\n   */\n  private refusedByHarness(entries: readonly CatalogEntry[], harness: RunningHarness, profileDir: string | null): Record<string, PeerVerdict> {\n    if (harness.peerCheck === null || profileDir === null) return {}\n    try {\n      return peerVerdictsOf(entries, harness.peerCheck, harness.peerCheck.exemptions(profileDir), this.profile)\n    } catch {\n      // Swallows the exemption read throwing. app-boot's reader turns an\n      // unreadable or malformed file into no exemptions rather than an error,\n      // so this is a failure it did not plan for; without the exemptions the\n      // shop cannot tell a refused install from an allowed one, and says\n      // nothing. `peerVerdictsOf` catches the rule's own throws per entry.\n      return {}\n    }\n  }\n\n  /**\n   * The bundles the profile at `profileDir` composes, or null when its\n   * manifest cannot be read — which is no verdict on the profile half rather\n   * than an accusation. `dsh.profile.bundles` is the same list\n   * `discoverProfile` uses to recognize a profile directory, read through the\n   * harness's own parser so a profile this shop was booted inside is read the\n   * way dsh reads it.\n   */\n  private runningProfileBundles(profileDir: string): readonly string[] | null {\n    try {\n      const bundles = readProfileManifest('dsh-plugin-shop', profileDir).dsh?.profile?.bundles\n      if (!Array.isArray(bundles) || !bundles.every((bundle): bundle is string => typeof bundle === 'string')) return null\n      return bundles\n    } catch {\n      // Swallows an unreadable or malformed manifest: nobody can then say what\n      // this profile composes, and the answer for that is silence on this\n      // half, never a warning.\n      return null\n    }\n  }\n\n  /**\n   * Install one cataloged version into the profile (§7.2). The rejection\n   * paths run against this Host's snapshot before anything is spawned; only a\n   * passing request reaches the executor.\n   */\n  // The wire method is `installStart`, never `install`: the client api's\n  // RemoteNamespaceService owns a method named `install` (its internal mount\n  // primitive), and mounting a namespace method with that name throws\n  // \"conflicts with its namespace service\" — the web full-flow e2e exposed\n  // this on the real composition (§7.3 amendment, 2026-08-25).\n  @Remote('installStart')\n  async install(args: InstallArgs): Promise<ShopInstallResult> {\n    // Read once, before the awaits: the desktop gate and the choice of path\n    // must see the same service (see `pluginManager`).\n    const manager = this.pluginManager()\n    if (isDesktopProfile(this.profile) && manager === null) return { ok: false, code: 'desktop-profile', detail: DESKTOP_PROFILE_DETAIL }\n    const snapshot = await this.snapshotNow()\n    // The manifest's dependency for this name, when it has one: the gate needs\n    // it to tell an update of THIS plugin from a replacement of a different one\n    // that shares the name. Read once, here, and reused for `isUpdate` below —\n    // two reads straddling the tarball fetch could see two different manifests.\n    const installedSpec = this.installedSpecOf(args.name)\n    const verdict = validateInstall(snapshot, args, installedSpec)\n    if (!verdict.ok) return { ok: false, code: verdict.code, detail: verdict.detail }\n    // The validator resolved the row by identity. Re-finding it by name is\n    // what installed another repository's commit when names collided.\n    const entry = verdict.entry\n    // The Host builds the spec itself: npm entries become `name@version`,\n    // github entries become `github:owner/slug#commit` (subpackage entries\n    // `github:owner/slug#commit&path:<subdir>`) — all from fields the\n    // snapshot validated, never from a client-supplied string (§7.2).\n    let spec: string\n    if (entry.source === 'github' && entry.tarball !== undefined) {\n      // Release-rescued entry: the spec is the prebuilt tarball URL the\n      // snapshot validated (https github.com releases of this very repo).\n      // No git, no commit pin — the recorded tag is the version.\n      // The recorded sha256 is enforced before anything spawns: fetch the\n      // tarball now and verify its bytes. The install itself re-fetches\n      // through pnpm, so an asset swapped between this check and pnpm's\n      // fetch is a TOCTOU window — this check catches passive MITM and\n      // asset tampering at the check instant, and the catalog chain\n      // (pointer sha256 + validateEntryCoherence) already pins the URL\n      // itself.\n      const integrity = await verifyTarballSha256(\n        this.fetchTarball,\n        entry.tarball.url,\n        entry.tarball.sha256,\n      )\n      if (integrity !== null) {\n        return { ok: false, code: 'tarball-integrity', detail: integrity }\n      }\n      spec = entry.tarball.url\n    } else if (entry.source === 'github') {\n      if (entry.repo === undefined || !/^[0-9a-f]{40}$/.test(args.version)) {\n        return { ok: false, code: 'version-mismatch', detail: `dsh-plugin-shop: ${args.name} has no installable commit` }\n      }\n      // No git check here, deliberately. pnpm resolves a `github:` spec\n      // through GitHub's tarball endpoint, not `git clone`, so git is not a\n      // precondition: measured with git stubbed to exit 127 on pnpm 9.15.9,\n      // 10.15.0 and 11.13.0, for this form and the `&path:` one, then end to\n      // end through the binary actually spawned below — `dsh plugin add`\n      // exited 0 on dsh 0.1.1-rc.2 and the package landed in the profile\n      // manifest. The preflight that stood here rejected EVERY github entry\n      // on a machine without git, which is 61% of the catalog, for a\n      // dependency the install does not have. A real failure still reports\n      // pnpm's stderr verbatim plus the recovery hint (executor.ts).\n      spec = `github:${entry.repo}#${args.version}${entry.subdir !== undefined ? `&path:${entry.subdir}` : ''}`\n    } else {\n      spec = `${args.name}@${args.version}`\n    }\n    // Whether this process may already have imported the package — and so\n    // whether a hot mount could deliver the new code at all (design\n    // 2026-09-26-market-borrowings §1). An update always may: whatever version\n    // is installed was composed at boot or has been mounted since. The gate\n    // above already proved that a defined spec names this very install, so\n    // \"the name is present\" and \"this is an update\" are one fact, read once;\n    // the own-property discipline lives in `installedSpecOf`. The process\n    // record adds what the manifest cannot say: a name uninstalled earlier in\n    // this session, whose module is still in the cache.\n    const isUpdate = installedSpec !== undefined\n    const alreadyImported = isUpdate || this.imported.has(args.name)\n    // What this update would replace, read BEFORE anything spawns — after it,\n    // the profile holds the new version. The record is written only once the\n    // flow reports done, so a FAILED update leaves the older rollback point\n    // where it was instead of replacing it with the version still installed\n    // (design 2026-11-02-market-borrowings §6.1).\n    const previous = isUpdate ? this.installedVersionOf(entry) : undefined\n    const replaced = previous !== undefined && previous !== entry.version ? previous : undefined\n    // Read before the spawn: the post-install check below is synchronous, and\n    // which dsh runs cannot change while it runs (see `harnessRead`).\n    const harness = await this.runningHarness()\n    if (manager !== null) {\n      // The desktop profile has no CLI continuation (dsh refuses that profile\n      // outright), so an update there takes dsh's own update operation\n      // instead: check, remove, install, and restore the old version when the\n      // install fails — the sequence dsh's Plugins page runs (`updateBundle`,\n      // 0.2.2 on). Only npm entries: `updateBundle` is a registry-version\n      // operation, while a github update installs a new commit spec, which\n      // dsh's `already-installed` guard already lets through. Design\n      // 2026-11-06-desktop-updates.\n      const updateInPlace = isUpdate && entry.source === 'npm' && isDesktopProfile(this.profile)\n        ? manager.updateBundle?.bind(manager)\n        : undefined\n      if (updateInPlace !== undefined) {\n        const running = this.startManagerUpdate(\n          updateInPlace,\n          manager,\n          entry.name,\n          entry.version,\n          `update ${spec}`,\n          raw => this.updateOutcome(raw, this.outcomeContext(args.name, 'update', alreadyImported, this.packageHasClientHalf(args.name))),\n          () => this.postInstallHazard(args.name, harness, ' It is on disk: uninstall it from the shop to undo this install.'),\n        )\n        this.track(running)\n        this.recordGithubPin(entry)\n        this.rememberOnDone(running, entry, args.name, replaced)\n        return { ok: true, installId: running.installId, state: running.status().state }\n      }\n      // An update dsh's plugin manager refuses in place continues through\n      // dsh's CLI, in this same record (design 2026-10-19-dsh-021-readiness\n      // §2): from dsh 0.2.1 (dsh-plugin-manager 0.2.1-alpha.3 on) the manager\n      // answers `already-installed` for a spec naming a package the profile\n      // depends on, and has no other way to update one, while `dsh plugin add`\n      // over it updates it as before (§2 says what was read and what was\n      // measured). Keyed on dsh's code, never on its version or the spec's\n      // form, so a dsh that updates in place again keeps being used. Not for a\n      // fresh install: the shop saw no such name installed while dsh refuses\n      // one as installed, so the two disagree about what the profile holds,\n      // and refusing is the safe side. Not on the desktop profile, which dsh's\n      // CLI refuses.\n      const continues = isUpdate && !isDesktopProfile(this.profile)\n      let refusedInPlace = false\n      const managed = this.startManagerInstall(manager, spec, `install ${spec}`, raw => {\n        const change = readChange(raw)\n        // An answer that stopped at stage `install`, a pnpm failure or a\n        // refusal, imported nothing. One that reached `enable` has filled\n        // Node's module cache, whether dsh composed the package or failed to\n        // enable it, so the next install of this name in this process must not\n        // read as live. An update records nothing here: `alreadyImported`\n        // already holds for it. Through 0.2.0 dsh answered an update without\n        // loading the new files (spec section 2); on 0.2.1 one its guard lets\n        // through is reconciled and may replace the running plugin in place\n        // (design 2026-10-19-dsh-021-readiness §2). Either way this process\n        // imported the name before.\n        if (!isUpdate && change.stage === 'enable') this.imported.add(args.name)\n        if (continues && change.errorCode === 'already-installed') refusedInPlace = true\n        return managerOutcome(raw, this.outcomeContext(args.name, isUpdate ? 'update' : 'install', alreadyImported, this.packageHasClientHalf(args.name)))\n      }, () => this.postInstallHazard(args.name, harness, ' It is on disk: uninstall it from the shop to undo this install.'))\n      // The continuation is an update's, so its CLI step mounts nothing and\n      // reports the restart that path always has for one.\n      const running = continueAfter(managed, () => refusedInPlace, () => this.startCliInstall(args.name, spec, harness, true), cliFallbackLine(this.profile, spec))\n      // Tracked first: the operation is already queued, so a pin write that\n      // throws must not leave it running where no poll or restart gate sees it.\n      this.track(running)\n      this.recordGithubPin(entry)\n      this.rememberOnDone(running, entry, args.name, replaced)\n      return { ok: true, installId: running.installId, state: running.status().state }\n    }\n    const running = this.startCliInstall(args.name, spec, harness, alreadyImported)\n    this.recordGithubPin(entry)\n    this.track(running)\n    this.rememberOnDone(running, entry, args.name, replaced)\n    return { ok: true, installId: running.installId, state: running.status().state }\n  }\n\n  /**\n   * One install of `name` through dsh's CLI, `dsh plugin --profile <p> add\n   * <spec>` (§7.2): the path every install takes when dsh offers no plugin\n   * manager, and the one that continues an update the manager refuses in\n   * place (design 2026-10-19-dsh-021-readiness §2). `alreadyImported` is\n   * whether this process may already hold the package's module, which rules\n   * out a hot mount. The caller tracks the record and records any pin, once.\n   */\n  private startCliInstall(name: string, spec: string, harness: RunningHarness, alreadyImported: boolean): RunningInstall {\n    return startInstall({\n      profile: this.profile,\n      spec,\n      dshBin: this.dshBin,\n      // §7.2 step 6: exit 0 must be confirmed against the profile manifest —\n      // a bundle that did not land is not a done install. The executor takes\n      // its own before/after snapshots of the profile's dependencies, through\n      // the same resolution the confirm uses, so a miss reports the difference\n      // and can name what actually landed.\n      expectedName: name,\n      // §7.2 step 5's new phase: an install that finds a command already\n      // queued for this profile warms pnpm's store from OUTSIDE the mutex\n      // while it waits. Best-effort — the install below is unchanged by it.\n      prefetcher: this.prefetcher,\n      // And, now that the files are on disk, the one collision the name gate\n      // cannot see. Reporting it beats a done install that kills the next\n      // boot; the package stays on disk, so the detail says how to undo it.\n      alsoConfirm: () => this.postInstallHazard(\n        name, harness, ` It is on disk: run \\`dsh plugin --profile ${this.profile} remove ${name}\\` to undo this install.`,\n      ),\n      // After the bundle lands, bring it up hot — unless this process may\n      // already hold its module (see `alreadyImported`). A failed mount falls\n      // back to restart activation, never to a silent half-state.\n      afterDone: async () => {\n        // No mount, and no live disable of the running instance. A mount would\n        // import the package's URL again and Node would answer with the module\n        // it cached, re-running the old code under the new version's name\n        // (measured 2026-09-26, web-full-flow.e2e.ts). So the running instance\n        // keeps running until the restart that loads the new files, or on dsh\n        // 0.2.1 until a profile reconcile replaces it first (design\n        // 2026-10-19-dsh-021-readiness §2) — and a plugin the user had\n        // disabled stays disabled, which the swap this replaced did not\n        // guarantee: it mounted the new rows under a `mkt-` id that no\n        // user-layer row names.\n        if (alreadyImported) return { activation: 'restart' as const, restartReason: 'already-loaded' as const }\n        const hot = this.hot ?? { mount: hotMount, unmount: hotUnmount }\n        // Recorded before the mount rather than on its success: the import is\n        // what fills the cache, and a mount that fails after importing — an\n        // activation that throws, a timeout — has filled it all the same.\n        this.imported.add(name)\n        const result = await hot.mount(\n          { plugin: (plugin, config) => (this.home as unknown as { plugin(plugin: unknown, config: unknown): { await(): Promise<unknown>; dispose(): Promise<unknown> | void } }).plugin(plugin, config) },\n          this.profileDirResolved(),\n          name,\n        )\n        if (!result.ok) {\n          return { activation: 'restart' as const, ...(result.reason !== null ? { restartReason: result.reason } : {}) }\n        }\n        // The mount SUCCEEDED, so the host half is live — and the browser\n        // half is in the graph the next page load boots from: the tree hangs\n        // off the shop's own loader entry (`home`), where dsh's client\n        // registry enumerates it like any boot-composed entry (activation.ts,\n        // measured 2026-09-26 on 0.1.5-rc.3 and 0.1.7-rc.2). So a package with\n        // a browser half is one reload away, not one restart. Only the new\n        // version is read: a fresh install has no old one in the tab.\n        return {\n          activation: activationOf({\n            hostLive: true,\n            clientLive: true,\n            hasClientHalf: this.packageHasClientHalf(name),\n          }),\n        }\n      },\n    })\n  }\n\n  /**\n   * What would stop the profile from starting now that `name`'s files are on\n   * disk, or null: an entry id another installed package already declares,\n   * or a bundle patch declaration this dsh cannot read. Neither is knowable\n   * before the files land. The package stays on disk either way, so each\n   * detail ends with `undo`, the sentence that says how to take the install\n   * back on the path that made it.\n   */\n  private postInstallHazard(name: string, harness: RunningHarness, undo: string): string | null {\n    const clash = collidingEntryId({\n      profileDir: this.profileDirResolved(),\n      packageName: name,\n      dependencies: Object.keys(this.profileDependenciesOrNone() ?? {}),\n    })\n    if (clash !== null) {\n      return `dsh-plugin-shop: ${name} and ${clash.holder} use the same plugin entry ID, \"${clash.id}\".`\n        + ' dsh cannot start this profile while both plugins are installed.' + undo\n    }\n    // The other way a landed bundle kills the next boot: a patch\n    // declaration this dsh cannot read (design\n    // 2026-09-26-dsh-017-readiness, B4).\n    const declared = declaredBundlePatch({ profileDir: this.profileDirResolved(), packageName: name })\n    switch (patchDeclarationHazard(declared, harness.patchLists)) {\n      case null: return null\n      case 'list-unsupported':\n        return `dsh-plugin-shop: ${name} uses multiple configuration files, which require dsh 0.1.7 or later.`\n          + ` Your dsh${harness.dshVersion === null ? '' : ` (${harness.dshVersion})`} only supports one file and cannot start with this plugin installed.` + undo\n      case 'malformed':\n        return `dsh-plugin-shop: ${name} has an invalid bundle patch declaration; it must be a file path or a list of paths.`\n          + ' dsh cannot start this profile with the plugin installed.' + undo\n    }\n  }\n\n  /** Remember a github entry's pinned commit: the manifest records only\n   * `github:owner/slug`, so the pins file is how `installed()` reports\n   * outdated honestly. A failed install leaves a pin behind, but the\n   * manifest presence gate keeps it invisible. */\n  private recordGithubPin(entry: CatalogEntry): void {\n    if (entry.source !== 'github') return\n    const pins = readRepoPins(this.pinFs, this.pinsPath())\n    writeRepoPins(this.pinFs, this.pinsPath(), { ...pins, [identityKey(entry)]: entry.version })\n  }\n\n  /** Forget an uninstalled package's pins: its own, and its identity pin when\n   * a catalog row matched the installed spec. Both uninstall paths call this\n   * once their operation has started, so a stale pin never outlives the\n   * uninstall in the shop's cache either way. The plugin manager path tracks\n   * its record first, so a write here that throws cannot hide an operation\n   * already queued. */\n  private forgetPins(name: string, installedEntry: CatalogEntry | undefined): void {\n    const pins = readRepoPins(this.pinFs, this.pinsPath())\n    const stalePins = [name, ...(installedEntry === undefined ? [] : [identityKey(installedEntry)])]\n    let forgot = false\n    for (const key of stalePins) {\n      if (pins[key] === undefined) continue\n      delete pins[key]\n      forgot = true\n    }\n    if (forgot) {\n      writeRepoPins(this.pinFs, this.pinsPath(), pins)\n    }\n  }\n\n  /** What `managerOutcome` reads dsh's answer against. The gateway's own\n   * facts are set here once, for every operation through the service: the\n   * profile, whether it is the desktop one, and the deadline a timeout\n   * detail names. */\n  private outcomeContext(name: string, operation: OutcomeContext['operation'], alreadyImported: boolean, hasClientHalf: boolean): OutcomeContext {\n    return {\n      profile: this.profile, name, operation, alreadyImported, hasClientHalf,\n      reconcilesRunningPlugins: this.reconcilesRunningPlugins(),\n      desktop: isDesktopProfile(this.profile), timeoutMs: INSTALL_TIMEOUT_MS,\n    }\n  }\n\n  /**\n   * One install-shaped operation through dsh's `pluginManager` (design\n   * 2026-09-26-plugin-manager-delegation, section 6): `installBundle(spec)`\n   * under the record's own id as its request id, so the output dsh streams\n   * for it reaches this record, in the profile's queue with the download\n   * phase the CLI path has. At the shop's deadline dsh is asked to cancel it;\n   * a service that offers no `cancelInstall` gets no deadline, and its record\n   * settles when dsh answers. `install` and `updateStart` differ only in the\n   * mechanism line and in how they read the answer.\n   */\n  private startManagerInstall(\n    manager: PluginManagerLike,\n    spec: string,\n    mechanism: string,\n    outcome: (raw: unknown) => ManagerOutcome,\n    alsoConfirm?: () => string | null,\n  ): RunningInstall {\n    // The operand gate the CLI path runs in spawnPluginCli (R41): the spec\n    // goes to installBundle and to the download phase, whose pump relies on\n    // the gate. It throws as that path does, before anything is queued.\n    gateOperand(spec)\n    // The CLI line that retries this spec by hand, which a failure here\n    // carries (design 2026-11-02-market-borrowings §5, 2026-11-06\n    // amendment): from dsh 0.1.7 every fresh install takes this path, so with\n    // the line on the CLI path alone no current dsh ever showed one. The same\n    // builder and the same gated operand as that path's own line; none on the\n    // desktop profile, whose CLI dsh refuses.\n    const command = retryCommand(this.platform, this.profile, 'add', spec)\n    // Bound here, because the runner calls it apart from the service.\n    const cancel = manager.cancelInstall?.bind(manager)\n    return startManagerOperation({\n      profile: this.profile,\n      requestId: randomUUID(),\n      mechanism,\n      logs: this.managerLogs,\n      run: requestId => manager.installBundle(spec, { requestId }),\n      ...(cancel !== undefined ? { cancel } : {}),\n      outcome,\n      ...(alsoConfirm !== undefined ? { alsoConfirm } : {}),\n      prefetcher: this.prefetcher,\n      spec,\n      desktop: isDesktopProfile(this.profile),\n      ...(command !== undefined ? { command } : {}),\n    })\n  }\n\n  /**\n   * One update through dsh's `updateBundle` (0.2.2 on): the operation dsh's\n   * own Plugins page runs, remove → install → restore. The desktop profile\n   * needs it because dsh's CLI cannot manage that profile, so the CLI\n   * continuation an update takes everywhere else is unavailable there; with\n   * neither, every desktop update ended on dsh's `already-installed`\n   * refusal (measured 2026-11-06, design 2026-11-06-desktop-updates).\n   *\n   * `spec` is the same `name@version` the install path builds, and only\n   * warms the download phase and spells the mechanism line; the service is\n   * handed the name and version `updateBundle` takes.\n   */\n  private startManagerUpdate(\n    updateBundle: NonNullable<PluginManagerLike['updateBundle']>,\n    manager: PluginManagerLike,\n    name: string,\n    version: string,\n    mechanism: string,\n    outcome: (raw: unknown) => ManagerOutcome,\n    alsoConfirm?: () => string | null,\n  ): RunningInstall {\n    const spec = `${name}@${version}`\n    // The operand gate the CLI path runs in spawnPluginCli (R41): the spec\n    // goes to the download phase, whose pump relies on it. It throws as that\n    // path does, before anything is queued.\n    gateOperand(spec)\n    const cancel = manager.cancelInstall?.bind(manager)\n    return startManagerOperation({\n      profile: this.profile,\n      requestId: randomUUID(),\n      mechanism,\n      logs: this.managerLogs,\n      run: requestId => updateBundle(name, version, { requestId }),\n      ...(cancel !== undefined ? { cancel } : {}),\n      outcome,\n      ...(alsoConfirm !== undefined ? { alsoConfirm } : {}),\n      prefetcher: this.prefetcher,\n      spec,\n      desktop: isDesktopProfile(this.profile),\n    })\n  }\n\n  /**\n   * What one `updateBundle` answer means to the reader: the nested change is\n   * fed to `managerOutcome` exactly as an `installBundle` answer is, and\n   * dsh's own restore attempt is named when the install failed after a\n   * removal. Saying nothing about it would leave a reader on the failure\n   * detail alone, unable to tell whether the old version is still there —\n   * dsh reinstalls it, and the answer records whether that worked.\n   */\n  private updateOutcome(raw: unknown, context: OutcomeContext): ManagerOutcome {\n    const update = readUpdate(raw)\n    const outcome = managerOutcome(update.result ?? raw, context)\n    if (outcome.state !== 'failed' || update.restore === null) return outcome\n    const restore = readChange(update.restore)\n    const restored = restore.application !== 'failed' && restore.application !== 'cancelled'\n    const sentence = restored\n      ? `The previously installed version${update.from === null ? '' : ` (${update.from})`} was restored.`\n      : 'Restoring the previously installed version also failed.'\n    if (outcome.detail === undefined) return { ...outcome, detail: `dsh-plugin-shop: ${sentence}` }\n    const needsPeriod = !/[.!?]$/.test(outcome.detail)\n    return { ...outcome, detail: `${outcome.detail}${needsPeriod ? '.' : ''} ${sentence}` }\n  }\n\n  /** Keep a started record where `installStatus`, the restart gate and\n   * eviction find it, then bound the finished ones. */\n  private track(running: RunningInstall): void {\n    this.installs.set(running.installId, running)\n    this.installOrder.push(running.installId)\n    this.evictFinishedInstalls()\n  }\n\n  /** Bound retained finished records at MAX_FINISHED_INSTALLS, evicting the\n   * oldest finished ones (insertion order, oldest first). Live records —\n   * running AND queued — are never evicted; an id absent from the map reports\n   * `found: false`. */\n  private evictFinishedInstalls(): void {\n    const finishedIds: string[] = []\n    for (const id of this.installOrder) {\n      const record = this.installs.get(id)\n      // Terminal, not \"not running\". A QUEUED install reports 'downloading',\n      // and counting it here evicts a live record: `installStatus` then answers\n      // found: false and the client renders \"install record lost\" for an\n      // install that is about to run. The comment above this method — live\n      // records are never evicted — is only true with this predicate.\n      if (record !== undefined && isTerminalInstallState(record.status().state)) finishedIds.push(id)\n    }\n    const excess = Math.max(0, finishedIds.length - ShopGateway.MAX_FINISHED_INSTALLS)\n    for (const id of finishedIds.slice(0, excess)) this.installs.delete(id)\n  }\n\n  /**\n   * Write the rollback record once `running` reports done.\n   *\n   * The version was captured before the spawn by the caller; this only\n   * decides WHEN it lands. A failed update therefore leaves the previous\n   * record alone — it used to replace it with the version still installed,\n   * silently losing the older rollback point (design\n   * 2026-11-02-market-borrowings §6.1 says \"after the flow reports success\").\n   *\n   * Every failure here is swallowed. A rollback point is a convenience; an\n   * install that would succeed must not fail because the profile directory\n   * could not take a bookmark.\n   */\n  private rememberOnDone(running: RunningInstall, entry: CatalogEntry, name: string, version: string | undefined): void {\n    if (version === undefined) return\n    // A `.catch` on the derived promise, not only on the status: `finished`\n    // can reject when the spawn setup throws, and a bare `.then` would turn\n    // that into an unhandled rejection — process death by default, with an\n    // update in flight.\n    void running.finished.then(status => {\n      if (status.state !== 'done') return\n      try {\n        const state = readShopState(this.stateFs, this.profileDirResolved())\n        state.previous[identityKey(entry)] = {\n          source: entry.source,\n          name,\n          ...(entry.repo !== undefined ? { repo: entry.repo } : {}),\n          ...(entry.subdir !== undefined ? { subdir: entry.subdir } : {}),\n          version,\n        }\n        writeShopState(this.stateFs, this.profileDirResolved(), state)\n      } catch {\n        // Swallows an unwritable state file: the install stands, and there is\n        // simply no rollback offer for this one.\n      }\n    }).catch(() => {\n      // Swallows the derived promise's rejection (see above): the record is a\n      // convenience, and the install it describes is already tracked.\n    })\n  }\n\n  /**\n   * The version of `entry` currently on disk, or undefined when it cannot be\n   * read.\n   *\n   * npm reads the installed package's own manifest rather than the profile's\n   * dependency spec: a profile may hold a RANGE (`^1.2.3`), and recording\n   * that as \"the previous version\" would roll a reader forward to whatever\n   * the registry serves on the day they click. github reads the pin the shop\n   * wrote at install time, which is the commit that actually runs.\n   */\n  private installedVersionOf(entry: CatalogEntry): string | undefined {\n    if (entry.source === 'github') {\n      try {\n        const pins = readRepoPins(this.pinFs, this.pinsPath())\n        return pins[identityKey(entry)] ?? pins[entry.name]\n      } catch {\n        // Swallows an unreadable pins file: no pin means no recordable\n        // version, and the caller then records nothing.\n        return undefined\n      }\n    }\n    try {\n      const manifest = JSON.parse(\n        this.pinFs.read(join(this.profileDirResolved(), 'node_modules', entry.name, 'package.json')),\n      ) as { version?: unknown }\n      return typeof manifest.version === 'string' && manifest.version.trim() !== '' ? manifest.version : undefined\n    } catch {\n      // Swallows an absent or unreadable installed manifest: the package is\n      // not where a hoisted install puts it, so no version is recorded.\n      return undefined\n    }\n  }\n\n  /** Whether any command this gateway started is still running — or still\n   * waiting its turn. */\n  private hasRunningCommand(): boolean {\n    for (const record of this.installs.values()) {\n      // A queued install is a command this gateway started and has not\n      // finished. Asking `=== 'running'` would let a restart boot a new dsh\n      // against a profile with installs pending — what F-5 refuses.\n      if (!isTerminalInstallState(record.status().state)) return true\n    }\n    return false\n  }\n\n  /** Poll one install's progress (§7.2); unknown ids report `found: false`. */\n  @Remote('installStatus')\n  installStatus(args: { installId: string }): ShopInstallStatusResult {\n    const running = this.installs.get(args.installId)\n    if (running === undefined) return { found: false, state: 'failed', log: [], detail: `The installation record (${args.installId}) is no longer available. Refresh the shop to check whether the plugin was installed.` }\n    return { found: true, ...running.status() }\n  }\n\n  /**\n   * The profile manifest's dependency spec for every name it holds — exactly\n   * what the install gate reads, unfiltered.\n   *\n   * The client cannot derive this from `installed()`. That list drops any\n   * dependency no catalog entry matches, so a fork, a hand `dsh plugin add`,\n   * or an entry the catalog has since dropped is invisible to it — while the\n   * gate, which reads the raw manifest, still refuses over it. That gap is\n   * what made the card show a plain Install button for a name the host was\n   * about to refuse. Shipping the gate's own input is what makes the badge\n   * and the refusal one rule rather than two implementations that agree\n   * until they do not.\n   *\n   * `null` is \"cannot say\" — an unreadable manifest — and is deliberately\n   * distinct from `{}`, \"nothing is installed\": the client must not read a\n   * failed read as a clean bill of health.\n   */\n  @Remote('installedSpecs')\n  async installedSpecs(): Promise<Record<string, string> | null> {\n    return this.profileDependenciesOrNone() ?? null\n  }\n\n  /**\n   * What the shop remembers between visits: the reader's favorites and, per\n   * install identity, the version an update replaced (design\n   * 2026-11-02-market-borrowings §6–§7).\n   *\n   * `rollback` carries a VERSION rather than a spec: the client renders it as\n   * the offer (\"roll back to 1.2.3\"), and the spec that installs it is built\n   * by the host from the same record. A malformed or missing file reads as\n   * empty state — losing stars must never take the page down.\n   */\n  @Remote('state')\n  async shopState(): Promise<ShopStateResult> {\n    let state\n    try {\n      state = readShopState(this.stateFs, this.profileDirResolved())\n    } catch {\n      // A read-only call: a file that exists but cannot be read is shown as\n      // no state rather than failing the page. Nothing is written from it.\n      return { favorites: [], rollback: {} }\n    }\n    const rollback: Record<string, string> = {}\n    // No offer at all on the desktop profile (2026-11-06): `rollbackStart`\n    // runs dsh's CLI, which refuses that profile in any letter case, while an\n    // update there goes through the plugin manager and still writes a record.\n    // Forwarding it drew \"Roll back to 1.0.0\" and the click could only answer\n    // `desktop-profile`. The records stay on disk; the stars are answered as\n    // on any profile.\n    for (const [key, record] of isDesktopProfile(this.profile) ? [] : Object.entries(state.previous)) {\n      // Only a record `rollbackSpec` can turn into a spec is offered. A\n      // release-rescued entry's version is a tag, which no spec form installs:\n      // forwarding it drew \"Roll back to v1.0.0\" and then answered\n      // `version-mismatch` — an offer the host could not honour.\n      if (rollbackSpec(record) !== undefined) rollback[key] = record.version\n    }\n    return { favorites: state.favorites, rollback }\n  }\n\n  /**\n   * Star or unstar one install identity (§7).\n   *\n   * A write failure is reported rather than swallowed: the client flips its\n   * star optimistically and would otherwise show a favorite that is gone on\n   * the next visit. The key is stored verbatim — it is the identity the\n   * catalog itself uses, and an unknown one is harmless until it matches.\n   */\n  @Remote('setFavorite')\n  async setFavorite(args: { key: string; favorite: boolean }): Promise<{ ok: boolean; detail?: string }> {\n    // The store bounds what it keeps (`state.ts`), so a key it would filter\n    // away must not be answered as saved: the star would show until the next\n    // visit and then be gone.\n    if (!isStorableKey(args.key)) {\n      return { ok: false, detail: 'dsh-plugin-shop: that plugin cannot be starred in this profile.' }\n    }\n    let state\n    try {\n      state = readShopState(this.stateFs, this.profileDirResolved())\n    } catch {\n      // The file is there but could not be read. Writing the empty base over\n      // it would lose every star and every rollback record, so the save is\n      // refused instead.\n      return { ok: false, detail: 'dsh-plugin-shop: the favorites file could not be read, so nothing was saved.' }\n    }\n    const has = state.favorites.includes(args.key)\n    if (args.favorite && !has && state.favorites.length >= FAVORITES_MAX) {\n      // The store would drop the new key (`writeShopState` slices), so an ok\n      // here would show a star that is gone next visit.\n      return { ok: false, detail: 'dsh-plugin-shop: this profile holds the maximum number of favorites.' }\n    }\n    if (args.favorite && !has) state.favorites.push(args.key)\n    if (!args.favorite && has) state.favorites = state.favorites.filter(key => key !== args.key)\n    try {\n      writeShopState(this.stateFs, this.profileDirResolved(), state)\n      return { ok: true }\n    } catch (error) {\n      return { ok: false, detail: `The favorite could not be saved: ${(error as Error).message}` }\n    }\n  }\n\n  /**\n   * Re-install the version an entry was updated from (§6).\n   *\n   * Takes only the install identity. The spec is built by `rollbackSpec` from\n   * this host's own record, so a client cannot name a version or a spec the\n   * shop never wrote — the same invariant `installStart` holds by building\n   * its spec from the snapshot. The install then runs through the ordinary\n   * CLI path, with the same records, activation verdict and notices an\n   * update gets.\n   */\n  @Remote('rollbackStart')\n  async rollbackStart(args: { key: string }): Promise<ShopInstallResult> {\n    // The desktop profile refuses the CLI this path spawns, manager or no\n    // manager: the install path's `isDesktopProfile && manager === null` test\n    // exists because a manager can serve it, and a rollback never goes\n    // through one.\n    if (isDesktopProfile(this.profile)) return { ok: false, code: 'desktop-profile', detail: DESKTOP_PROFILE_DETAIL }\n    let record: ShopRollbackRecord | undefined\n    try {\n      const state = readShopState(this.stateFs, this.profileDirResolved())\n      record = Object.hasOwn(state.previous, args.key) ? state.previous[args.key] : undefined\n    } catch {\n      return { ok: false, code: 'not-in-catalog', detail: 'dsh-plugin-shop: the profile\\'s rollback records could not be read, so there is nothing to roll back to.' }\n    }\n    if (record === undefined) {\n      return { ok: false, code: 'not-in-catalog', detail: 'dsh-plugin-shop: there is no earlier version recorded for this plugin.' }\n    }\n    const spec = rollbackSpec(record)\n    if (spec === undefined) {\n      return { ok: false, code: 'version-mismatch', detail: `dsh-plugin-shop: the recorded earlier version of ${record.name} cannot be installed.` }\n    }\n    // The name may have changed hands since the record was written: the\n    // profile's dependency for it must still be THIS identity, or the\n    // rollback would replace a different plugin (the rule `installStart`s\n    // gate holds through `validateInstall`).\n    const snapshot = await this.snapshotNow()\n    const current = snapshot.entries.find(entry => identityKey(entry) === args.key)\n    if (current === undefined) {\n      return { ok: false, code: 'not-in-catalog', detail: `dsh-plugin-shop: ${record.name} is no longer listed, so its earlier version cannot be restored.` }\n    }\n    const holder = this.installedSpecOf(record.name)\n    if (holder !== undefined && !installedSpecMatches(current, holder)) {\n      return { ok: false, code: 'name-taken', detail: `dsh-plugin-shop: ${record.name} is now installed from a different source, so rolling back would replace it.` }\n    }\n    const harness = await this.runningHarness()\n    const running = this.startCliInstall(record.name, spec, harness, true)\n    this.track(running)\n    // Both the pin and the record move only once the host says done. Writing\n    // the pin before that left a failed rollback reporting the version it\n    // never restored; keeping the record left the offer pointing at what is\n    // already installed, for npm whose row carries a spec and never the exact\n    // version it was compared against.\n    void running.finished.then(status => {\n      if (status.state !== 'done') return\n      try {\n        if (record.source === 'github' && record.repo !== undefined) {\n          const pins = readRepoPins(this.pinFs, this.pinsPath())\n          const key = identityKey({ source: 'github', name: record.name, repo: record.repo, subdir: record.subdir })\n          writeRepoPins(this.pinFs, this.pinsPath(), { ...pins, [key]: record.version })\n        }\n        const state = readShopState(this.stateFs, this.profileDirResolved())\n        if (Object.hasOwn(state.previous, args.key)) {\n          delete state.previous[args.key]\n          writeShopState(this.stateFs, this.profileDirResolved(), state)\n        }\n      } catch {\n        // Swallows an unreadable or unwritable cache file: the rollback itself\n        // landed, and the worst case is an offer that outlives its record.\n      }\n    }).catch(() => {\n      // Swallows the derived promise's rejection, as `rememberOnDone` does.\n    })\n    return { ok: true, installId: running.installId, state: running.status().state }\n  }\n\n  /** Installed catalog plugins (§7.3): every entry of the snapshot the profile\n   * manifest declares as a dependency, with the Host's `outdated` verdict\n   * attached. The tab's shelf cards and its Updatable section both derive\n   * from this one list. */\n  @Remote('installed')\n  async installed(): Promise<ShopInstalledEntry[]> {\n    const snapshot = await this.snapshotNow()\n    const manifest = readProfileManifest('dsh-plugin-shop', this.profileDirResolved())\n    const dependencies = manifest.dependencies ?? {}\n    const pins = readRepoPins(this.pinFs, this.pinsPath())\n    // The inventory knows the real enabled state. When the service is not\n    // mounted (an older harness), every entry reads as enabled — the same\n    // optimistic assumption the pre-inventory client made.\n    const live = new Map<string, boolean>()\n    let haveInventory = false\n    try {\n      for (const entry of await this.listInventory()) live.set(entry.entryId, entry.enabled)\n      haveInventory = true\n    } catch {\n      // pluginInventory is not mounted; `enabled` stays the default below.\n    }\n    // The bundles the profile selects. Read apart from the inventory, and\n    // first: a deselected bundle has no live entry at all, which the\n    // inventory cannot tell from one not composed until a restart.\n    const selected = this.runningProfileBundles(this.profileDirResolved())\n    /** A package is enabled when the profile selects its bundle and every\n     * entry it owns and that is live is enabled. Keyed by entry id, never by\n     * module name: the entry a package inserts may mount a different\n     * package's module (see ownedEntryIds). */\n    const enabledOf = (name: string): boolean => {\n      if (selected !== null && !selected.includes(name)) return false\n      if (!haveInventory) return true\n      let owned: string[]\n      try {\n        owned = ownedEntryIds({ profileDir: this.profileDirResolved(), packageName: name })\n      } catch {\n        // A malformed bundle patch in ONE installed package must not take the\n        // whole installed list down with it; the row reads as enabled, and\n        // acting on it returns the read failure as a rejection detail (see\n        // setEnabled) rather than a wrong state.\n        return true\n      }\n      const ownedSet = new Set(owned)\n      const present = [...live].filter(([entryId]) => ownsEntryId(ownedSet, entryId))\n      return present.length === 0 || present.every(([, enabled]) => enabled)\n    }\n    const installed: ShopInstalledEntry[] = []\n    // Second pass for shadowed rows, below: a manifest name no catalog row\n    // claimed may still need one of its own. Track which names the catalog\n    // iteration consumed so that pass adds only the remainder.\n    const claimed = new Set<string>()\n    for (const entry of snapshot.entries) {\n      const spec = ownDependencySpec(dependencies, entry.name)\n      if (spec === undefined) continue\n      // A profile has one dependency per name, so the spec is the only way\n      // to choose among same-named catalog entries.\n      if (!installedSpecMatches(entry, spec)) continue\n      claimed.add(entry.name)\n      const identity = { source: entry.source, repo: entry.repo, subdir: entry.subdir }\n      if (entry.source === 'github') {\n        // The manifest spec is `github:owner/slug` — no commit. The pin the\n        // shop recorded at install time is the commit truth; without one the\n        // entry was installed by other means and reads as current rather\n        // than killing the RPC over an unknowable comparison.\n        //\n        // `pin !== entry.version` is an INEQUALITY, not an ordering. Two\n        // commit shas cannot be ordered without asking the repository, so\n        // this reports that the catalog offers a DIFFERENT commit, never\n        // that it offers a newer one; the npm arm below is a real semver\n        // comparison. §7.3's 2026-09-16 follow-up records what that bounds\n        // the Updatable heading to, and why a probe per installed github\n        // entry is not worth what it would cost.\n        const pin = pins[identityKey(entry)] ?? pins[entry.name]\n        installed.push({\n          name: entry.name,\n          ...identity,\n          installed: pin ?? spec,\n          latest: entry.version,\n          outdated: pin !== undefined && pin !== entry.version,\n          enabled: enabledOf(entry.name),\n        })\n      } else {\n        installed.push({\n          name: entry.name,\n          ...identity,\n          installed: spec,\n          latest: entry.version,\n          outdated: this.isBehind(spec, entry.version),\n          enabled: enabledOf(entry.name),\n        })\n      }\n    }\n    // The second pass: a manifest dependency whose name no catalog row claimed\n    // may be a shadowed github install — the catalog refuses it\n    // `shadowed-by-npm`, so the first loop never visited it, but the card list\n    // is this profile's only control. An npm-shaped spec with no catalog row\n    // reads as a departure (§A2, out of MVP scope); an unparseable spec the\n    // shop cannot act on either — both render no row at all. A github-shaped\n    // one gets a row with what the manifest knows: no catalog truth to compare\n    // against, so `latest: null` and `outdated: false`.\n    for (const name of Object.keys(dependencies)) {\n      if (claimed.has(name)) continue\n      const spec = ownDependencySpec(dependencies, name)\n      if (spec === undefined) continue\n      const origin = parseSpec(spec)\n      if (origin?.kind !== 'github') continue\n      // The pin was recorded at install time under `identityKey(entry)` —\n      // `github:${repo}#${subdir}` — so a subdir-installed entry's pin does\n      // not sit under the no-subdir key. The manifest spec names no subdir,\n      // so ANY `github:${repo}#*` pin is the install this row describes.\n      const pinPrefix = `github:${origin.repo}#`\n      const pinKey = pins[pinPrefix] !== undefined\n        ? pinPrefix\n        : Object.keys(pins).find(key => key.startsWith(pinPrefix))\n      installed.push({\n        name,\n        source: 'github',\n        repo: origin.repo,\n        installed: (pinKey === undefined ? undefined : pins[pinKey]) ?? pins[name] ?? spec,\n        latest: null,\n        outdated: false,\n        enabled: enabledOf(name),\n        shadowed: true,\n      })\n    }\n    return installed\n  }\n\n  /** Whether an installed dependency spec sits behind the catalog's version.\n   * A spec identical to the catalog version is current by definition; a\n   * pnpm-written non-semver spec like `workspace:*` is not reportable and\n   * reads as current rather than killing the RPC. */\n  private isBehind(spec: string, latest: string): boolean {\n    if (spec === latest) return false\n    let floor: string | null\n    try {\n      floor = minVersion(spec)?.version ?? null\n    } catch {\n      floor = null\n    }\n    return floor !== null && lt(floor, latest)\n  }\n\n  /** Uninstall one installed catalog plugin from the profile (§7.3 follow-up\n   * amendment). Removing revokes privilege rather than granting it, so there\n   * is no acknowledgement gate. The name must be a catalog entry the profile\n   * manifest declares as a dependency — the RPC cannot remove profile\n   * dependencies the shop does not manage (the base bundle, the shop\n   * itself). The same install records/polling serve the client. */\n  @Remote('uninstallStart')\n  async uninstall(args: { name: string }): Promise<ShopUninstallResult> {\n    // Read once, before the await (see `pluginManager`).\n    const manager = this.pluginManager()\n    if (isDesktopProfile(this.profile) && manager === null) return { ok: false, detail: DESKTOP_PROFILE_DETAIL }\n    const snapshot = await this.snapshotNow()\n    const named = snapshot.entries.filter(entry => entry.name === args.name)\n    const manifest = readProfileManifest('dsh-plugin-shop', this.profileDirResolved())\n    const dependencies = manifest.dependencies ?? {}\n    const spec = ownDependencySpec(dependencies, args.name)\n    if (named.length === 0) {\n      // Shadowed-github arm (§C10 MVP): the catalog refused this entry\n      // `shadowed-by-npm`, so its row is absent from the snapshot by\n      // construction — yet the profile manifest still holds its spec, and the\n      // card this refusal would orphan is the only control the reader has.\n      // When the manifest's OWN spec parses as a github reference, proceed\n      // through the same removal path the matched arm uses. An npm-shaped or\n      // unparseable spec with no catalog row is a departure the MVP does not\n      // recover, and keeps today's refusal.\n      if (spec === undefined) {\n        return { ok: false, detail: `dsh-plugin-shop: ${args.name} is not in the catalog` }\n      }\n      const origin = parseSpec(spec)\n      if (origin?.kind !== 'github') {\n        return { ok: false, detail: `dsh-plugin-shop: ${args.name} is not in the catalog` }\n      }\n      // Fall through with `named` empty: `installedEntry` below is then\n      // undefined, which `forgetPins` already reads as \"no catalog identity\n      // pin to forget\".\n    }\n    if (spec === undefined) {\n      return { ok: false, detail: `dsh-plugin-shop: ${args.name} is not installed` }\n    }\n    // The dependency is removed by name, but the matching row tells us which\n    // identity pin to forget. If no row matches, still allow removal: revoking\n    // a dependency is safer than trapping it behind an unrecognised spec.\n    const installedEntry = named.find(entry => installedSpecMatches(entry, spec))\n    // Resolve the entry ids while the package is still on disk: `afterDone`\n    // runs after the uninstall removed it, and its bundle patch with it.\n    // Best-effort for the same reason as the update path: a package with an\n    // unreadable patch must still be removable.\n    const priorEntryIds = this.ownedEntryIdsOrNone(args.name)\n    // Read the browser half while the package is still on disk — `afterDone`\n    // runs after the uninstall deleted its manifest, and the conservative\n    // fallback would then answer `true` for every package, turning this\n    // verdict into a constant. Same ordering constraint, same reason, as\n    // `priorEntryIds` above.\n    const hadClientHalf = this.packageHasClientHalf(args.name)\n    if (manager !== null) {\n      // removeBundle deselects the bundle and reloads itself, refusing with\n      // bundle-in-use if a fiber survives, so this branch skips the CLI\n      // path's own afterDone teardown below. It carries no request id the\n      // way installBundle does, so the record takes its final output rather\n      // than a stream.\n      const running = startManagerOperation({\n        profile: this.profile,\n        requestId: randomUUID(),\n        mechanism: `remove ${args.name}`,\n        logs: this.managerLogs,\n        run: () => manager.removeBundle(args.name),\n        outcome: raw => managerOutcome(raw, this.outcomeContext(args.name, 'uninstall', false, hadClientHalf)),\n        desktop: isDesktopProfile(this.profile),\n      })\n      // Tracked first, as the manager install is: the operation is already\n      // queued, so a pin write that throws must not leave it running where no\n      // poll or restart gate sees it.\n      this.track(running)\n      this.forgetPins(args.name, installedEntry)\n      return { ok: true, installId: running.installId }\n    }\n    const running = startUninstall({\n      profile: this.profile,\n      name: args.name,\n      dshBin: this.dshBin,\n      expectedName: args.name,\n      // Bring the plugin down the moment the bundle is gone: a session hot\n      // mount first, else the live boot entry. The package is removed from\n      // the profile manifest either way — nothing can come back — so the\n      // result never demands a restart, even when neither arm found anything\n      // (the plugin simply never loaded this session).\n      afterDone: async () => {\n        const hot = this.hot ?? { mount: hotMount, unmount: hotUnmount }\n        const hotRemoved = await hot.unmount(args.name)\n        // Privilege is revoked the moment the fiber is gone, and the boot\n        // composition drops the entry row at the next boot either way — so\n        // neither arm finding anything still reports a live removal. What\n        // this must NOT do is claim the plugin stopped while its fiber is\n        // still up: \"Removed and stopped immediately\" would then be a false\n        // statement about privilege, and a restart is the honest advice.\n        const stopped = hotRemoved || await this.liveEntriesDown(priorEntryIds)\n        // `clientLive: true` for the same reason as the toggle: what an\n        // uninstall removes is a row of the boot composition, and dropping\n        // one from the served graph is the measured half of §2.\n        return { activation: activationOf({ hostLive: stopped, clientLive: true, hasClientHalf: hadClientHalf }) }\n      },\n    })\n    this.forgetPins(args.name, installedEntry)\n    this.track(running)\n    return { ok: true, installId: running.installId }\n  }\n\n  /** Restart the dsh process the shop runs in (§8 amendment, 2026-08-27):\n   * commit a two-phase handoff — a detached helper waits for this pid to\n   * exit, then re-runs this process's own command line — and exit once the\n   * response is out. The browser monitors the origin and refreshes when the\n   * new server answers. Refusals are issued before anything is torn down. */\n  @Remote('restart')\n  async restart(): Promise<ShopRestartResult> {\n    // Asked again after committing: the same answer, and nothing started\n    // twice — a second takeover helper would race the first for the port, and\n    // a second timer is a second exit. Ahead of every refusal, because the\n    // commit is irrevocable: refusing a repeat over an install begun since\n    // would tell the page nothing is under way while this process exits.\n    if (this.committedRestart !== null) return this.committedRestart\n    // A running install owns the profile: `pnpm` may be rewriting its\n    // package.json, lockfile and node_modules. Exiting now would hand the\n    // takeover helper a half-written profile, so refuse before anything is\n    // torn down (F-5).\n    if (this.hasRunningCommand()) {\n      return {\n        ok: false,\n        detail: 'dsh-plugin-shop: an install is still running in this profile. Wait for it to finish before restarting so the configuration can be saved completely.',\n      }\n    }\n    // The static refusals, in the order `staticRestartBlock` states\n    // them, and each one before anything is torn down. Asking it rather than\n    // repeating its checks is what keeps the answer the client was given at\n    // mount identical to the answer a press gets.\n    const blocked = this.staticRestartBlock()\n    if (blocked !== null) {\n      return { ok: false, detail: RESTART_BLOCKED_DETAIL[blocked] }\n    }\n    let logFile: string\n    try {\n      const { cacheDir } = this.rowConfig()\n      const { command, args } = restartCommand({\n        dshBin: this.dshBin,\n        argv: this.restartArgv,\n        execPath: process.execPath,\n        execArgv: process.execArgv,\n        script: this.restartScript,\n      })\n      logFile = join(cacheDir, 'restart.log')\n      startRestart({\n        command,\n        args,\n        parentPid: this.restartParentPid,\n        logFile,\n        env: process.env,\n      })\n    } catch (error) {\n      // A refused restart must not tear anything down; the detail names the\n      // config or log problem in the shop's own words.\n      return { ok: false, detail: `dsh-plugin-shop: could not start the restart process: ${(error as Error).message}` }\n    }\n    // The response must reach the browser before this process exits; the\n    // helper holds the child back until this pid is gone, so the port is\n    // free when the new dsh binds. It names the log the new process writes,\n    // for the page to point at if that process never stays up, and the\n    // process it replaces, for the page to recognise if it is still the one\n    // answering after the reload.\n    this.committedRestart = { ok: true, logFile, bootId, pid: this.restartParentPid }\n    setTimeout(() => this.exit(0), this.restartExitDelayMs)\n    return this.committedRestart\n  }\n\n  /** The shop's own version and whether npm has a newer one (§7.3). The\n   * check is advisory: a registry that cannot answer leaves `latest` null\n   * and the client shows the version alone. `installed` is the RUNNING\n   * version (own-version.ts), not the manifest's range spec. */\n  @Remote('version')\n  async version(): Promise<ShopVersionResult> {\n    const installed = this.options.runningVersion ?? runningVersion()\n    const latest = await this.latestVersion()\n    return {\n      installed,\n      latest,\n      outdated: latest !== null && lt(installed, latest),\n      restartBlocked: this.staticRestartBlock(),\n      pendingVersion: this.pendingVersion(installed),\n      bootId,\n      selfUpdate: isDesktopProfile(this.profile) ? 'dsh-page' : null,\n    }\n  }\n\n  /**\n   * The version of the shop the profile has installed, when it is not the\n   * one this process runs; null when they match or the copy cannot be read.\n   *\n   * Read from the profile's own copy — the directory `dsh plugin add` writes\n   * and the next boot loads — rather than from the file beside this module.\n   * For the hoisted install those are one directory, but a `link:` install\n   * runs from its link target, which an update replaces in the profile and\n   * never touches at the target, so reading beside the module would never see\n   * the update land.\n   *\n   * Unreadable is null, never a throw: the version check is advisory, and a\n   * missing field would tell the client this host predates it.\n   */\n  private pendingVersion(running: string): string | null {\n    try {\n      const manifest = JSON.parse(readFileSync(join(this.profileDirResolved(), 'node_modules', 'dsh-plugin-shop', 'package.json'), 'utf8')) as { version?: unknown }\n      return typeof manifest.version === 'string' && manifest.version !== running ? manifest.version : null\n    } catch {\n      // No discoverable profile (a bare test construction), no installed copy,\n      // or a manifest mid-write: nothing pending that this host can name.\n      return null\n    }\n  }\n\n  /** Update the shop itself to a published version (§7.3): the explicit pin\n   * is the only install form that bypasses pnpm's release cooldown. The\n   * version is re-validated as plain semver at the boundary — the spec\n   * `dsh-plugin-shop@<version>` is built here, never from the wire. */\n  @Remote('updateStart')\n  async updateStart(args: { version: string }): Promise<ShopUpdateResult> {\n    // Read once (see `pluginManager`).\n    const manager = this.pluginManager()\n    if (isDesktopProfile(this.profile) && manager === null) return { ok: false, detail: DESKTOP_PROFILE_DETAIL }\n    if (valid(args.version) === null) {\n      return { ok: false, detail: `dsh-plugin-shop: ${args.version} is not a valid version` }\n    }\n    // The desktop profile's update belongs to dsh's own Plugins page. dsh's\n    // manager refuses an in-place update (`already-installed`) and the CLI\n    // cannot manage this profile, while the shop cannot remove itself\n    // mid-operation — so say where the update runs instead of surfacing the\n    // refusal after a spawn that could never finish (design\n    // 2026-11-06-desktop-updates).\n    if (isDesktopProfile(this.profile)) {\n      return { ok: false, code: 'desktop-manual', detail: DESKTOP_SELF_UPDATE_DETAIL }\n    }\n    const spec = `dsh-plugin-shop@${args.version}`\n    if (manager !== null) {\n      // The shop is always installed, so every self-update is an update, and\n      // one dsh's plugin manager refuses in place continues through dsh's\n      // CLI (s